local config = {
  ui_story_5084_50840100_1_dialog_content = "Ini adalah... makam?",
  ui_story_5084_50840100_2_dialog_content = "\"Varaki, takdirmu telah terungkap, namun hatimu masih menyimpan keraguan.\"",
  ui_story_5084_50840100_3_dialog_content = "Ini karena aku mengerti harga yang harus dibayar. Untuk memperoleh kekuatan adalah menjadi tawanan dari kekuatan itu sendiri, dan melepaskan rasa damai untuk sisa hidup seseorang.",
  ui_story_5084_50840100_4_dialog_content = "Saya tidak ingin seperti orang tua saya dan menderita karena kekuatan saya. Mereka hanya menemukan istirahat setelah setiap tetes terakhir Varaki hilang dari tubuh mereka.",
  ui_story_5084_50840100_5_dialog_content = "\"Kamu bukan murid Varaki. Seperti saya, kamu hanya menyembah Lord of Truth.\"",
  ui_story_5084_50840100_6_dialog_content = "\"Sebagai murid dari Kebenaran, kamu telah menjelajahi dunia ini dan menemukan kekuatan yang besar.\"",
  ui_story_5084_50840100_7_dialog_content = "\"Jika hatimu benar-benar merindukan kedatangan Lord of Truth, maka kamu tidak memiliki alasan untuk takut berkorban.\"",
  ui_story_5084_50840100_8_dialog_content = "Apa yang Anda ingin saya lakukan?",
  ui_story_5084_50840100_9_dialog_content = "\"Bantu saya mendapatkan kembali kekuatan dan bentuk fisik saya. Sebagai gantinya, saya akan mengekstrak kekuatan dari tubuhmu dan memberimu istirahat abadi.\"",
  ui_story_5084_50840100_10_dialog_content = "\"Saya merasa rasa bahaya itu paling menggairahkan.\"",
  ui_story_5084_50840100_11_dialog_content = "\"Karena itu memungkinkan saya untuk menikmati Truth untuk diri saya sendiri.\"",
  ui_story_5084_50840100_12_dialog_content = "Apa yang kamu lihat, Lady Victoria?",
  ui_story_5084_50840100_13_dialog_content = "Momen ketika saya membuat perjanjian dengan Bloody Bible. Saat itu, ia tidak mengungkapkan masa depan cincin ini kepada saya.",
  ui_story_5084_50840100_14_dialog_content = "Tapi sekarang ini kembali ada di tanganku... Bahkan sebelum melihatnya, aku merasakan panggilan kekuatan kuno.",
  ui_story_5084_50840100_15_dialog_content = "Sensasi kesemutan yang familiar menghantuiku setiap kali aku memegangnya....",
  ui_story_5084_50840100_16_dialog_content = "Kamu memiliki koneksi dengan cincin ini?",
  ui_story_5084_50840100_17_dialog_content = "Ya. Ini adalah peninggalan kuno Varaki, yang diturunkan dari generasi ke generasi oleh para pemimpin True Order.",
  ui_story_5084_50840100_18_dialog_content = "Agar dia kembali kepada pemilik aslinya adalah alasan untuk merayakan.",
  ui_story_5084_50840100_19_dialog_content = "Yang paling penting bukanlah cincin itu sendiri, tetapi waktu di balik kemunculannya.",
  ui_story_5084_50840100_20_dialog_content = "Saat kedatangan Truth semakin dekat, aku menemukan cincin yang sebelumnya hilang ini kembali dalam milikku.",
  ui_story_5084_50840100_21_dialog_content = "…!",
  ui_story_5084_50840100_22_dialog_content = "Victoria!",
  ui_story_5084_50840100_23_dialog_content = "Hahahaha... Varaki...",
  ui_story_5084_50840100_24_dialog_content = "Kamu! Agh... Argh!",
  ui_story_5084_50840100_25_dialog_content = "Ahhhhhhhhh—!!!",
  ui_story_5084_50840100_26_dialog_content = "Victoria!",
  ui_story_5084_50840100_27_dialog_content = "Yang baru saja kulihat...",
  ui_story_5084_50840100_28_dialog_content = "Rasanya seperti ramalan... Namun sepertinya itu telah terjadi di masa lalu...",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>Fwoosh—!</color>",
  ui_story_5084_50840100_30_dialog_content = "\"Katalis telah dipanggil.\"",
  ui_story_5084_50840100_31_dialog_content = "\"Makam menunggu kedatangannya.\"",
  ui_story_5084_50840100_32_dialog_content = "\"Pengetahuan tentang Truth harus diuji dan diverifikasi.\"",
  ui_story_5084_50840100_33_dialog_content = "\"Sebuah upacara besar diadakan di bawah bulan tua.\"",
  ui_story_5084_50840100_34_dialog_content = "\"Waktunya telah tiba.\"",
  ui_story_5084_50840100_35_dialog_content = "...",
  ui_story_5084_50840100_36_dialog_content = "Pengungkapan ini tampak agak samar, Lady Victoria.",
  ui_story_5084_50840100_37_dialog_content = "Ketika dikombinasikan dengan prediksi masa lalunya, wahyu cincin ini sebenarnya cukup jelas.",
  ui_story_5084_50840100_38_dialog_content = "\"Saatnya akhirnya tiba. Pertemuan tak terduga akan terjadi selama Kedatangan 'Truth'.\"",
  ui_story_5084_50840100_39_dialog_content = "\"Untuk memastikan pemahaman kita tentang Kebenaran, kita harus mencari guardian Starry Crypt.\"",
  ui_story_5084_50840100_40_dialog_content = "\"Untuk usaha ini, kita membutuhkan bantuan dari Caelestite.\"",
  ui_story_5084_50840100_41_dialog_content = "Ini adalah kali pertama Bloody Bible mencoba menyamarkan salah satu ramalannya.",
  ui_story_5084_50840100_42_dialog_content = "Tampaknya wahyu yang ditawarkan oleh cincin yang telah lama hilang ini akan menghubungkan hari-hari dan peristiwa yang tidak pernah disaksikan.",
  ui_story_5084_50840100_43_dialog_content = "Aku percaya sekarang aku mengerti.",
  ui_story_5084_50840100_44_dialog_content = "Aku meninggalkan tugas merekrut teman berdarah segar kita kepada kamu.",
  ui_story_5084_50840100_45_dialog_content = "Ya, Lady Victoria.",
  ui_story_5084_50840100_46_dialog_content = "Aku tahu kamu sudah menjelaskan semuanya, tapi aku masih tidak mengerti. Mengapa aku harus ikut dalam perayaan True Order?",
  ui_story_5084_50840100_47_dialog_content = "Maafkan aku, tapi aku hanya mengikuti keinginan Lady Victoria dan Lord of Truth.",
  ui_story_5084_50840100_48_dialog_content = "Huft, kalian seperti biasa, tidak jelas, saya melihat...",
  ui_story_5084_50840100_49_dialog_content = "Kita sudah cukup jauh dari Umbraton sekarang. Tepatnya kamu membawa saya kemana?",
  ui_story_5084_50840100_50_dialog_content = "Wah—",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5084_50840100_52_dialog_content = "Apa ini benda yang tampak gelap... Dan kenapa bergerak?!",
  ui_story_5084_50840100_53_dialog_content = "Oh, jadi kamu yang mengganggu tidurku, Bola Salju.",
  ui_story_5084_50840100_54_dialog_content = "... Sikare?",
  ui_story_5084_50840100_55_dialog_content = "Apakah barusan aku tersandung pada tanaman merambatmu?",
  ui_story_5084_50840100_56_dialog_content = "Tidak sopan bertanya terus setelah menginjak seseorang. Kamu seharusnya minta maaf, tahu?",
  ui_story_5084_50840100_57_dialog_content = "M-Maaf soal itu... Jadi, apa yang kamu lakukan di sini?",
  ui_story_5084_50840100_58_dialog_content = "Saya bisa menanyakan hal yang sama. Ada perlu apa kamu kemari hari ini?",
  ui_story_5084_50840100_59_dialog_content = "Ini semua salahku. Aku tahu hari ini aku akan membuat kesalahan yang tak bisa dimaafkan.",
  ui_story_5084_50840100_60_dialog_content = "Jika kamu tidak keberatan, Nona Sikare, saya ingin bertobat atas dosa-dosaku di sini dan sekarang...",
  ui_story_5084_50840100_61_dialog_content = "Tampaknya setiap orang sekarang hadir, Lady Victoria.",
  ui_story_5084_50840100_62_dialog_content = "Miss Victoria...",
  ui_story_5084_50840100_63_dialog_content = "Kamu pernah bilang padaku bahwa waktunya belum tiba, dan bahwa rahasia di dalam Starry Crypt masih di luar pemahamanku.",
  ui_story_5084_50840100_64_dialog_content = "Bloody Bible telah membimbing saya ke sini hari ini.",
  ui_story_5084_50840100_65_dialog_content = "May Saya bertanya apa jenis artifact yang telah kamu temukan kali ini?",
  ui_story_5084_50840100_66_dialog_content = "Yang ini.",
  ui_story_5084_50840100_67_dialog_content = "Jika apa yang kamu katakan itu benar, maka sekarang kamu memiliki hak istimewa untuk memasuki Starry Crypt.",
  ui_story_5084_50840100_68_dialog_content = "Tempat macam apa ini, sih?",
  ui_story_5084_50840100_69_dialog_content = "Dalam istilah awam, ini adalah tempat di mana orang mati dikuburkan.",
  ui_story_5084_50840100_70_dialog_content = "Apa?! Tapi... Tapi Faust mengatakan bahwa ini untuk perayaan mendatang True Order!",
  ui_story_5084_50840100_71_dialog_content = "Dalam arti tertentu, ya. Demi apa yang akan datang, kita harus datang ke tempat ini terlebih dahulu.",
  ui_story_5084_50840100_72_dialog_content = "Jangan takut. Apa yang ada di dalam Starry Crypt lebih berharga daripada semua kekayaan di Lumopolis digabungkan.",
  ui_story_5084_50840100_73_dialog_content = "Tak terhitung banyaknya orang yang datang mencari rahasia kripta ini, hanya untuk menemukan diri mereka terkubur di sini. Anggaplah diri kalian beruntung.",
  ui_story_5084_50840100_74_dialog_content = "M-Meskipun ini harta karun, aku... aku butuh waktu untuk memikirkan ini! Benar...?",
  ui_story_5084_50840100_75_dialog_content = "Sebelum memasuki Starry Crypt, aku hanya memiliki tiga peringatan untuk dibagikan.",
  ui_story_5084_50840100_76_dialog_content = "Pertama, darah adalah satu-satunya cara Faria mengenali mereka yang ingin masuk ke ruang bawah tanah, dan hanya mereka yang telah membentuk pact darah dengannya yang dapat melakukannya.",
  ui_story_5084_50840100_77_dialog_content = "Pintu lain yang dibuka oleh Faria akan mematuhi kehendak yang terikat.",
  ui_story_5084_50840100_78_dialog_content = "Ini adalah Faria.",
  ui_story_5084_50840100_79_dialog_content = "Kedua, objek yang Anda bawa pada diri Anda memiliki kehadiran yang membimbing. Karena mereka milik waktu, mereka akan secara alami mengikuti waktu ke tempat-tempat di mana mereka seharusnya berada.",
  ui_story_5084_50840100_80_dialog_content = "Ketiga, takdir telah lama ditentukan. Tidak ada yang bisa mempertanyakannya, menyesalinya, atau mengubahnya.",
  ui_story_5084_50840100_81_dialog_content = "Meski tampaknya kamu masih memiliki banyak pertanyaan, Bola Salju.",
  ui_story_5084_50840100_82_option_content = "Sebuah \"perjanjian darah\"?",
  ui_story_5084_50840100_83_dialog_content = "Apakah ini berarti kita harus berdarah?",
  ui_story_5084_50840100_84_dialog_content = "Wahai Tuhan Yang Maha Esa, ambillah setetes darahku yang tercemar jika itu adalah keinginan-Mu...",
  ui_story_5084_50840100_85_option_content = "Sebuah \"takdir\" yang tak terbantahkan?",
  ui_story_5084_50840100_86_dialog_content = "Sepertinya salah satu dari cerita tentang dikirim ke dunia yang berbeda.",
  ui_story_5084_50840100_87_dialog_content = "Kamu tampak jauh lebih bersemangat tiba-tiba.",
  ui_story_5084_50840100_88_dialog_content = "Mulailah persiapan, Faria.",
  ui_story_5084_50840100_89_dialog_content = "T-Tunggu! Darahku... Apakah darah Caelestite bahkan akan berfungsi untuk jenis hal ini?",
  ui_story_5084_50840100_90_dialog_content = "Colek—!",
  ui_story_5084_50840100_91_dialog_content = "<size=45>Yeowch!!!</size>",
  ui_story_5084_50840100_92_dialog_content = "Tidakkah kamu mendengar? Sikare menyuruh Faria untuk bersiap, jadi mari kita bergerak!",
  ui_story_5084_50840100_93_dialog_content = "Kamu harus membawa Beau dan aku bersamamu, Lady Victoria! Saya berjanji kami akan melakukan yang terbaik!",
  ui_story_5084_50840100_94_dialog_content = "Apa Lenore tahu kamu ada di sini, May?",
  ui_story_5084_50840100_95_dialog_content = "Dia adalah, dan dia juga menyuruh saya untuk bersenang-senang banyak!",
  ui_story_5084_50840100_96_dialog_content = "Beau telah menyimpan banyak benang, yang berarti aku bisa menjahit sebanyak mungkin luka yang kamu butuhkan!",
  ui_story_5084_50840100_97_dialog_content = "Aku akan merawatmu dengan baik PlayerName, jadi jangan pergi terlalu jauh dariku!",
  ui_story_5084_50840100_98_dialog_content = "Meong!",
  ui_story_5084_50840100_99_dialog_content = "Aku rasa sebaiknya aku menjaga jarak untuk saat ini...",
  ui_story_5084_50840100_100_dialog_content = "Jika semua orang sudah siap sekarang, Faria bisa mulai.",
  ui_story_5084_50840100_101_dialog_content = "Lord of Truth, tunjukkan aku jawaban yang aku cari.",
  ui_story_5084_50840100_102_dialog_content = "Tuhan Kebenaran, berkatilah perjalanan kami dengan keamanan dan kecepatan.",
  ui_story_5084_50840100_103_dialog_content = "Lord of Truth, hukum aku atas dosa-dosaku.",
  ui_story_5084_50840100_104_dialog_content = "Lord of Truth, bimbing aku ke tempat yang menyenangkan!",
  ui_story_5084_50840100_105_dialog_content = "Kamu bisa menarik pakaianku sepuasnya... Aku tetap tidak akan...",
  ui_story_5084_50840100_106_dialog_content = "Urk...!",
  ui_story_5084_50840100_107_dialog_content = "S... Sikare...",
  ui_story_5084_50840100_108_dialog_content = "Selamatkan aku...",
  ui_story_5084_50840100_109_dialog_content = "Kamu terlihat seperti sedang kesakitan dengan mata tertutup seperti itu, Snowball.",
  ui_story_5084_50840100_110_dialog_content = "Bukalah dan lihat sekeliling. Tidak ada bahaya di sini.",
  ui_story_5084_50840100_111_dialog_content = "T-Tapi tanaman merambat tebal itu tadi... Mereka sangat gatal dan menakutkan...",
  ui_story_5084_50840100_112_dialog_content = "Tidakkah kamu ingin tahu lebih banyak tentang The Truth? Oh tunggu, aku baru saja ingat bahwa kamu belum bergabung dengan True Order.",
  ui_story_5084_50840100_113_dialog_content = "... Kamu benar-benar tidak memperhatikan banyak hal, bukan, Sikare?",
  ui_story_5084_50840100_114_dialog_content = "Pokoknya, saya tidak percaya mereka menghilang begitu saja!",
  ui_story_5084_50840100_115_dialog_content = "Masalah sebenarnya adalah kamu juga tidak menghilang.",
  ui_story_5084_50840100_116_dialog_content = "Aku perlu mendengar kamu mengatakan sesuatu seperti \"Aku ingin mendekatkan diri kepada Truth,\" atau \"Aku ingin menyerahkan pikiranku dan membiarkan indraku menjelajahi dunia di sekitarku.\"",
  ui_story_5084_50840100_117_dialog_content = "Kamu seorang Caelestite, jadi kamu seharusnya cukup mahir dalam hal seperti ini.",
  ui_story_5084_50840100_118_dialog_content = "Kamu bisa memberi tahu saya siapa kamu, atau mengapa kamu ada di sini, atau kemana kamu ingin pergi...",
  ui_story_5084_50840100_119_dialog_content = "Sangat samar... Aku datang hanya karena Faust mengundangku ke perayaan \"sekali seumur hidup\".",
  ui_story_5084_50840100_120_dialog_content = "Lalu, pikirkan saja tentang perayaan. Jika kamu masih takut, cukup meraba-raba di sekitar tanaman merambat dan mencari sebuah kandil.",
  ui_story_5084_50840100_121_dialog_content = "Sebatang lilin...",
  ui_story_5084_50840100_122_dialog_content = "O-Oh, lihat, aku benar-benar menemukan satu...",
  ui_story_5084_50840100_123_dialog_content = "Ini akan menjadi pemandumu, tapi jangan terbawa suasana; ingatlah untuk kembali sebelum lilinmu habis terbakar.",
  ui_story_5084_50840100_124_dialog_content = "Tapi... Bagaimana cara melakukannya? Dan ke mana seharusnya aku kembali?",
  ui_story_5084_50840100_125_dialog_content = "... Sikare?",
  ui_story_5084_50840100_126_dialog_content = "Sikare!",
  ui_story_5084_50840201_1_dialog_content = "(Terima kasih saya mendapatkan kandil ini dari Sikare, atau else itu akan sangat gelap di sini...)",
  ui_story_5084_50840201_2_dialog_content = "(Meskipun saya masih tidak tahu di mana mencari yang lainnya...)",
  ui_story_5084_50840201_3_dialog_content = "Sebentar, ini...?",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>Saat lonceng kuno berbunyi, tak terhitung menara jam tiba-tiba muncul dan menjulang menuju bulan merah darah di langit malam.</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>Cahaya merahnya bersinar turun pada jalan orang-orang yang setia dan dinding serta pintu kota yang diukir dengan rumit.</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>Ini mendengar pengakuan di dalam Kuil Kebenaran, dan berbicara tentang kemuliaan dan rahasia dari keluarga darah...</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>Lompat, lompat—!</color>",
  ui_story_5084_50840201_8_dialog_content = "Tanah di sini nyata... Dan begitu juga dinding-dinding ini!",
  ui_story_5084_50840201_9_dialog_content = "Ini bukan seperti Manor of Truth, bukan? Tempat di mana tidak ada yang sadar apa yang terjadi kecuali mereka benar-benar di sini...",
  ui_story_5084_50840201_10_dialog_content = "Ah ya, bulan berdarah telah muncul. Sekarang, Kedatangan Kebenaran, yang hanya terjadi sekali setiap tiga tahun, akhirnya dapat dimulai.",
  ui_story_5084_50840201_11_dialog_content = "Doaku sudah siap, dan aku akan membacakannya kepada Tuhan Kebenaran dengan sepenuh hati selama prosesi.",
  ui_story_5084_50840201_12_dialog_content = "Doa-doa kamu tidak akan didengar kecuali kamu dipilih sebagai \"Initiate.\" Hanya dengan mengorbankan dirimu sendiri, Lord of Truth akan merespon permohonanmu.",
  ui_story_5084_50840201_13_dialog_content = "Kota Varaki... Apakah ini tempat True Order mengadakan \"perayaan\" mereka? Parade Advent of Truth...",
  ui_story_5084_50840201_14_dialog_content = "Bagaimana aku bisa sampai di sini? Dan kemana semua orang lain pergi...?",
  ui_story_5084_50840201_15_dialog_content = "Pertama, kamu harus membaca, belajar, dan berinteraksi dengan orang lain. Saudara-saudara di True Order bisa mengajari kamu banyak hal yang tidak akan kamu pelajari sendiri.",
  ui_story_5084_50840201_16_dialog_content = "Kedua, kamu harus makan, berkumpul, dan memuji Lord of Truth.",
  ui_story_5084_50840201_17_dialog_content = "Dengan makan bersama orang-orang yang setia setiap hari, Truth akan akhirnya menunjukkan dirinya kepada kamu.",
  ui_story_5084_50840201_18_dialog_content = "Ketiga, kamu harus menggali dan menjelajah. Jika kamu memiliki bakat, kamu akan menemukan harta karun untuk setiap orang kagumi dan nikmati.",
  ui_story_5084_50840201_19_dialog_content = "Jika kamu suka menjelajah seperti yang biasa saya lakukan, maka tidak ada keluarga yang lebih baik untukmu selain True Order.",
  ui_story_5084_50840201_20_dialog_content = "Bahkan Beau berhenti rontok setelah kita bergabung!",
  ui_story_5084_50840201_21_dialog_content = "Saya juga berhasil mendapatkan rasa hormat dari Lady Victoria cukup cepat, itulah sebabnya dia sering mempercayai saya untuk menangani pekerjaannya yang penting sendiri.",
  ui_story_5084_50840201_22_dialog_content = "Nah? Bukankah itu membuatmu ingin bergabung dengan True Order?",
  ui_story_5084_50840201_23_dialog_content = "Meong!",
  ui_story_5084_50840201_24_dialog_content = "Sepertinya dia cukup percaya diri pada dirinya sendiri...",
  ui_story_5084_50840201_25_dialog_content = "Sebelum berkhotbah kepada kami, mungkin Anda harus berpakaian lebih menyenangkan.",
  ui_story_5084_50840201_26_dialog_content = "Lady Victoria adalah seorang bangsawan dari Keluarga Varaki. Bagaimana mungkin dia bisa mempercayai seorang gadis kecil seperti dirimu untuk mengurus urusannya...?",
  ui_story_5084_50840201_27_dialog_content = "Lebih lanjut, apakah benar ini pertama kalinya kamu di Varaki Town?",
  ui_story_5084_50840201_28_dialog_content = "Jika begitu, izinkan saya untuk menjelaskan kepada Anda tentang asal-usul dan ajaran dari True Order, serta rahasia yang tersembunyi di dalam kripta...",
  ui_story_5084_50840201_29_dialog_content = "Tu-Tunggu, apakah kalian senior dari True Order...? Tapi kalian berdua sangat berbeda dari orang-orang yang aku kenal...",
  ui_story_5084_50840201_30_dialog_content = "May...!",
  ui_story_5084_50840201_31_dialog_content = "PlayerName? Mengapa Anda menarik saya pergi?! Kedua orang itu hampir bergabung dengan kita!",
  ui_story_5084_50840201_32_dialog_content = "Mengesampingkan fakta bahwa mereka jelas tidak memiliki niat untuk \"bergabung\" denganmu...",
  ui_story_5084_50840201_33_dialog_content = "Belumkah kamu mendengarkan orang-orang di jalanan? Mereka telah berbicara tentang Advent of Truth dan semacam prosesi... Aku tidak yakin bagaimana, tapi kita berakhir di Varaki Town! Kota kelahiran Lady Victoria!",
  ui_story_5084_50840201_34_dialog_content = "Kampung halaman Lady Victoria... Ya, aku rasa aku pernah mendengar tentang itu sebelumnya. Jadi apa masalahnya?",
  ui_story_5084_50840201_35_dialog_content = "Maksudmu, kau tidak terkejut dengan semua ini? Bukankah kamu penasaran kemana sisanya dari grup kita pergi?",
  ui_story_5084_50840201_36_dialog_content = "Ha ha ha, saya mengerti sekarang! Setiap orang sedang berpakaian untuk perayaan sekarang ini!",
  ui_story_5084_50840201_37_dialog_content = "Mari kita tanya di mana mereka membeli pakaian mereka dan beli beberapa untuk kita sendiri!",
  ui_story_5084_50840201_38_dialog_content = "Hah? Kenapa kamu begitu bersemangat? Tempat ini lebih mirip penjahit berhantu daripada toko apa pun...",
  ui_story_5084_50840201_39_dialog_content = "Eh... May?",
  ui_story_5084_50840201_40_dialog_content = "Dengar! Prosesi itu menuju ke sini! Pegang tanganku dan jangan lepas!",
  ui_story_5084_50840201_41_dialog_content = "Saya mendengar orang di dalam peti mati itu adalah leluhur Varaki, dan mereka dipilih oleh Tuhan Kebenaran!",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>Dengan bulan berdarah sebagai saksi mereka, sekelompok orang dalam jubah elegan berjalan perlahan melalui jalan, membawa peti mati yang terlihat kuno dan mewah di bahu mereka.</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>Di dalam peti mati terbaring apa yang disebut \"leluhur\" Varaki, memegang teks suci dan memancarkan Kebenaran bersama dengan cahaya bulan darah.</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>Murid-murid Kebenaran mengikuti dengan penuh penghormatan, tidak berani mengalihkan pandangan mereka dari peti mati.</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>Pelan dan khidmat, mereka melewati setiap jalan di kota sebelum tiba di gerbang Temple of Truth.</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>Kriek... Duk—</color>",
  ui_story_5084_50840201_47_dialog_content = "Prosesi telah berakhir, dan Truth telah tiba.",
  ui_story_5084_50840201_48_dialog_content = "Para pengikut setia telah mendekati tuan kita dan memberikan persembahan kepada-Nya.",
  ui_story_5084_50840201_49_dialog_content = "Puji Tuhan Kebenaran!",
  ui_story_5084_50840201_50_dialog_content = "Aku mempersembahkan hidupku untuk Lord of Truth!",
  ui_story_5084_50840201_51_dialog_content = "Sekarang...",
  ui_story_5084_50840201_52_dialog_content = "Salah satu dari kalian akan dipilih oleh yang ilahi dan diizinkan untuk memasuki peti ini yang penuh dengan wahyu tak terbatas, untuk mendengar dan menerima Kebenaran.",
  ui_story_5084_50840201_53_dialog_content = "Dengan wawasan yang mendalam, kamu akan melihat bahkan rahasia tergelap dalam sejarah. ",
  ui_story_5084_50840201_54_dialog_content = "Dengan cara ini, kamu akan melampaui individualitasmu dan menjadi perwujudan dari True Order dan kebijaksanaan kolektifnya. ",
  ui_story_5084_50840201_55_dialog_content = "Semua yang kamu alami akan membimbing ordo suci kita menuju masa depan yang lebih besar. ",
  ui_story_5084_50840201_56_dialog_content = "Setelah tenggelam dalam aliran ketiadaan yang tak terbatas, batas waktu dan ruang akan larut di sekitarmu.",
  ui_story_5084_50840201_57_dialog_content = "Hanya ketika Tuhan Kebenaran muncul dan membersihkanmu dari ego, kamu akan mencapai bentuk terbersihmu.",
  ui_story_5084_50840201_58_dialog_content = "Dengarkan Kebenaran, bangkitkan pikiranmu, dan naik ke tingkat yang lebih tinggi.",
  ui_story_5084_50840201_59_dialog_content = "Ketika saatnya tiba, kamu akan mencapai kesatuan dengan yang ilahi.",
  ui_story_5084_50840201_60_dialog_content = "Pilih saya, Tuan Wilhelm!",
  ui_story_5084_50840201_61_dialog_content = "Aku ingin mendengar Truth...!",
  ui_story_5084_50840201_62_dialog_content = "Aku juga ingin mendengar Truth!",
  ui_story_5084_50840201_63_dialog_content = "Ssst! Tenanglah, May!",
  ui_story_5084_50840201_64_dialog_content = "Sudah cukup sulit bagi kita untuk membaur dengan kerumunan...",
  ui_story_5084_50840201_65_dialog_content = "Tapi jika aku ingin menjadi anggota penting dari True Order, aku harus belajar lebih banyak tentang Kebenaran! Ini adalah kesempatan yang sempurna untuk itu, sekarang pergi, Beau!",
  ui_story_5084_50840201_66_dialog_content = "\"Takdir telah lama ditentukan. Tidak ada yang bisa mempertanyakannya, menyesalinya, atau mengubahnya.\"",
  ui_story_5084_50840201_67_dialog_content = "Meong...?",
  ui_story_5084_50840201_68_dialog_content = "Apakah kamu sudah lupa peringatan yang Sikare berikan kepada kita, May?",
  ui_story_5084_50840201_69_dialog_content = "L... Lady Victoria?!",
  ui_story_5084_50840201_70_dialog_content = "Hah? Apa itu dengan pakaian itu?",
  ui_story_5084_50840201_71_dialog_content = "Saya bisa menanyakan hal yang sama. Apakah Anda mendapatkan mereka untuk bisa masuk ke tempat ini?",
  ui_story_5084_50840201_72_dialog_content = "Itu adalah ide May. Setelah itu, kami hanya mengikuti kerumunan hingga kemari.",
  ui_story_5084_50840201_73_dialog_content = "Jadi kamu tahu di mana kita sekarang?",
  ui_story_5084_50840201_74_dialog_content = "Aku pikir begitu. Menurut para pemuja itu, kita berada di Varaki Town... Rumahmu. Rasanya benar-benar seperti kita pergi ke dunia lain, tahu...",
  ui_story_5084_50840201_75_dialog_content = "Ini semua di masa lalu.",
  ui_story_5084_50840201_76_dialog_content = "Masa lalu?",
  ui_story_5084_50840201_77_dialog_content = "Saat itu, aku belum bergabung dengan True Order. Aku sedang berkeliling dunia mencari The Truth untuk diriku sendiri.",
  ui_story_5084_50840201_78_dialog_content = "Kita berada di tahun 1915. Menyusul Advent of Truth ini, pemimpin True Order menghilang.",
  ui_story_5084_50840201_79_dialog_content = "... Ke mana dia pergi?",
  ui_story_5084_50840201_80_dialog_content = "Tuhan dari Truth membimbingku ke sini melalui cincin itu. Sama seperti yang dikatakan Sikare: sebagai objek yang milik waktu, itu membimbingku ke tempat yang benar dalam sejarah.",
  ui_story_5084_50840201_81_dialog_content = "Bloody Bible ada di kepemilikan leluhur saya, tetapi cincin masih berada di tangan pemimpin True Order.",
  ui_story_5084_50840201_82_dialog_content = "Tidak peduli berapa banyak tahun berlalu, kutukan dari garis keturunan Varaki tidak pernah bisa dibatalkan.",
  ui_story_5084_50840201_83_dialog_content = "Dalam aliran waktu yang tak berujung, pencerahan sejati diperlukan untuk menjawab pertanyaan yang kamu pendam.",
  ui_story_5084_50840201_84_dialog_content = "Truth harus meresap ke dalam dirimu untuk mendapatkan pemahaman yang lebih besar tentang dunia.",
  ui_story_5084_50840201_85_dialog_content = "Aku, Wilhelm Varaki, pemimpin True Order, di bawah bimbingan Lord of Truth, dengan ini mengumumkan Inisiasi dari Advent of Truth ini—",
  ui_story_5084_50840201_86_dialog_content = "Victoria Varaki.",
  ui_story_5084_50840201_87_dialog_content = "Apa...?",
  ui_story_5084_50840201_88_dialog_content = "Victoria Varaki? Kenapa dia di sini...?",
  ui_story_5084_50840201_89_dialog_content = "Heheh. Menarik.",
  ui_story_5084_50840201_90_dialog_content = "...",
  ui_story_5084_50840201_91_dialog_content = "Lady Victoria? Itu dia! Dia benar-benar di sini!",
  ui_story_5084_50840201_92_dialog_content = "Tapi dia adalah satu-satunya putri dari Varaki...",
  ui_story_5084_50840201_93_dialog_content = "Ya, tapi saya dengar kepala keluarga tidak mengakui dia sebagai anggota mereka...",
  ui_story_5084_50840201_94_dialog_content = "...",
  ui_story_5084_50840301_1_dialog_content = "<size=30>... Itu Lady Victoria!</size>",
  ui_story_5084_50840301_2_dialog_content = "Mengapa kamu terlihat begitu bahagia?! Dia telah dilihat oleh orang-orang dari masa lalu!",
  ui_story_5084_50840301_3_dialog_content = "Bukankah itu melanggar aturan kita berada di sini?!",
  ui_story_5084_50840301_4_dialog_content = "Ikuti bimbingan hatimu, dan wahyu dari Truth tidak akan menyesatkanmu.",
  ui_story_5084_50840301_5_dialog_content = "Hingga bulan darah berikutnya, murid-murid yang setia. Lord of Truth mengawasi kita semua, dengan sabar menunggu kita untuk mendekat kepadanya.",
  ui_story_5084_50840301_6_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840301_7_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840301_8_dialog_content = "Haruskah kita pergi bersama mereka?",
  ui_story_5084_50840301_9_dialog_content = "Jika saya boleh, hati saya mengatakan untuk berdiri di samping dan mengamati dalam diam.",
  ui_story_5084_50840301_10_dialog_content = "Ungkapkan pendapatmu, Victoria.",
  ui_story_5084_50840301_11_dialog_content = "Aku bukan anggota True Order. Kehormatan mendengar The Truth sia-sia bagiku.",
  ui_story_5084_50840301_12_dialog_content = "Namun, saya tidak mendengar ada keberatan saat saya memilih Anda di Kuil Kebenaran.",
  ui_story_5084_50840301_13_dialog_content = "Mencari Kebenaran dan membentuk aliansi; bukankah ini hanya cara kamu untuk mempersiapkan diri bergabung dengan True Order di masa depan?",
  ui_story_5084_50840301_14_dialog_content = "Bisnisku bukan urusanmu.",
  ui_story_5084_50840301_15_dialog_content = "Anda masih belum menjawab saya. Katakan padaku, apa sebenarnya itu Truth?",
  ui_story_5084_50840301_16_dialog_content = "...",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>Krrrrak—!</color>",
  ui_story_5084_50840301_18_dialog_content = "Kehormatan mendengar The Truth... Saya sangat ingin mendengar pikiran dari seseorang yang cerdas seperti kamu, Victoria Varaki. Menurut definisimu, apa itu The Truth?",
  ui_story_5084_50840301_19_dialog_content = "Truth... adalah pengetahuan.",
  ui_story_5084_50840301_20_dialog_content = "Humph, Victoria Varaki... Meskipun kita berbagi garis darah yang sama, dalam hal kekuatan, kebijaksanaan, kemampuan, dan bahkan kecantikan... Aku jauh di atas kamu.",
  ui_story_5084_50840301_21_dialog_content = "Jadi apa yang membuatmu berpikir cincin ini benar-benar milikmu?",
  ui_story_5084_50840301_22_dialog_content = "Aku adalah Varaki sejati, dan pemimpin True Order!",
  ui_story_5084_50840301_23_dialog_content = "Untukmu... Kamu harus terlebih dahulu menunjukkan bahwa kamu layak atas nama keluarga kita. Jangan mengecewakanku.",
  ui_story_5084_50840301_24_dialog_content = "...",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>Crrrrack—!</color>",
  ui_story_5084_50840301_26_dialog_content = "Pilih kata-kata dan frasa dari buku yang tidak dapat kamu pahami, dan cari pencerahan dari gambar yang mereka ciptakan di pikiranmu...",
  ui_story_5084_50840301_27_dialog_content = "Bukankah ini cara kau mencari jawaban?",
  ui_story_5084_50840301_28_dialog_content = "Apa yang baru saja kamu lihat? Apa yang terlintas di pikiranmu?",
  ui_story_5084_50840301_29_dialog_content = "Keraguan? Ketakutan? Penolakan? Kekuatan Varaki tidak bisa dipilih, karena kekuatan itu sendiri yang memilih mereka yang layak menerimanya.",
  ui_story_5084_50840301_30_dialog_content = "...",
  ui_story_5084_50840301_31_dialog_content = "(Dia memakai cincin keluarga Victoria...)",
  ui_story_5084_50840301_32_dialog_content = "Wilhelm... Kukira kau bilang Victoria telah berangkat dari Kota Varaki?",
  ui_story_5084_50840301_33_dialog_content = "Heheh, memang begitu.",
  ui_story_5084_50840301_34_dialog_content = "Bagaimana kamu bisa begitu kasar terhadap wanita muda yang cerah dan penuh harapan, Varaki?",
  ui_story_5084_50840301_35_dialog_content = "Sudah cukup lama, Lady Victoria.",
  ui_story_5084_50840301_36_dialog_content = "Ini memiliki.",
  ui_story_5084_50840301_37_dialog_content = "Lord of Truth telah membimbingku untuk memilihnya, Porfirio. Varaki dan aku tak berdaya untuk mengubah kehendak-Nya.",
  ui_story_5084_50840301_38_dialog_content = "Heheheh, saya tidak menyalahkanmu untuk ini, Wilhelm. Saya hanya meratapi ketidaksetaraan yang mencolok antara cabang-cabang keluarga darah kita.",
  ui_story_5084_50840301_39_dialog_content = "Apakah Lord of Truth masih akan muncul di depan kita? Apakah pilihan-Nya kurang dalam iman atau layak?",
  ui_story_5084_50840301_40_dialog_content = "Keputusan ini berada di tangan kepala dari dua belas keluarga cabang, bukan hanya pemimpin Varaki.",
  ui_story_5084_50840301_41_dialog_content = "Hahaha, satu lagi balasan elegan dan pedas, Porfirio.",
  ui_story_5084_50840301_42_dialog_content = "Dalam hal apapun, kehendak Truth tidak boleh diabaikan. Mari kita lihat... Pengetahuan apa yang akan diberikan oleh Tuhan Truth kepada wanita ini...",
  ui_story_5084_50840301_43_dialog_content = "Kepala keluarga!",
  ui_story_5084_50840301_44_dialog_content = "Apakah ada keberatan terhadap Inisiat yang dipilih untuk Penjelmaan Kebenaran ini?",
  ui_story_5084_50840301_45_dialog_content = "...",
  ui_story_5084_50840301_46_dialog_content = "Tidak ada keberatan...",
  ui_story_5084_50840301_47_dialog_content = "Apakah keberatan akan mengubah apa pun pada titik ini?",
  ui_story_5084_50840301_48_dialog_content = "Hmph.",
  ui_story_5084_50840301_49_dialog_content = "Lanjutkan saja. Lord of Truth tidak bisa menunggu lebih lama lagi.",
  ui_story_5084_50840301_50_dialog_content = "Jangan takut, Victoria Varaki.",
  ui_story_5084_50840301_51_dialog_content = "Saya secara pribadi akan mengantar Anda ke kuil dan menempatkan Anda di peti mati sakral itu.",
  ui_story_5084_50840301_52_dialog_content = "Teguhkan dirimu dalam hati dan pikiran, dan bersiaplah untuk berbagi pengetahuanmu tentang Truth dengan tuan kita.",
  ui_story_5084_50840301_53_dialog_content = "...",
  ui_story_5084_50840301_54_dialog_content = "(Saya mendengar seseorang di jalan mengatakan bahwa Inisiator harus \"mengorbankan\" diri mereka sendiri... Apa sebenarnya upacara ini...?)",
  ui_story_5084_50840301_55_dialog_content = "(Saya merasakan bahaya serius datang dari para kepala keluarga ini...)",
  ui_story_5084_50840301_56_dialog_content = "(Apa yang akan terjadi jika Victoria benar-benar dikorbankan?!)",
  ui_story_5084_50840301_57_dialog_content = "(Tidak mungkin, aku harus melakukan sesuatu sebelum Victoria masuk ke dalam peti mati itu...)",
  ui_story_5084_50840301_58_option_content = "Tautan Telepati",
  ui_story_5084_50840301_59_dialog_content = "Akhirnya kamu berhasil mengejar.",
  ui_story_5084_50840301_60_dialog_content = "Ada yang tidak beres di sini, Victoria... Apakah kamu benar-benar akan membiarkan pria ini memasukkanmu ke dalam peti mati dan mengorbankanmu?!",
  ui_story_5084_50840301_61_dialog_content = "Ya.",
  ui_story_5084_50840301_62_dialog_content = "L-Lalu... Apa yang harus May dan saya lakukan?!",
  ui_story_5084_50840301_63_dialog_content = "Apakah kamu ingat kata-kata Sikare?",
  ui_story_5084_50840301_64_dialog_content = "Tentu saja aku tahu! \"Takdir telah lama ditentukan. Tidak ada yang bisa mempertanyakannya, membencinya, atau mengubahnya.\"",
  ui_story_5084_50840301_65_dialog_content = "Tidak bisa dipertanyakan...",
  ui_story_5084_50840301_66_dialog_content = "Sepertinya kamu mengerti sekarang.",
  ui_story_5084_50840301_67_dialog_content = "Sepertinya kamu telah terpisah dari setiap orang lainnya, Caelestite.",
  ui_story_5084_50840301_68_dialog_content = "Dan meskipun peringatan Sikare, pikiranmu penuh dengan pertanyaan dan keraguan.",
  ui_story_5084_50840301_69_dialog_content = "Saya rasa cukup normal untuk meragukan situasi saat ini...",
  ui_story_5084_50840301_70_dialog_content = "Ikuti saja intuisimu dan saksikan masa lalu terungkap bersamaku.",
  ui_story_5084_50840301_71_dialog_content = "Victoria!",
  ui_story_5084_50840301_72_dialog_content = "Sekarang...",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_74_dialog_content = "Masuk ke dalam peti mati!",
  ui_story_5084_50840301_75_dialog_content = "...",
  ui_story_5084_50840301_76_dialog_content = "Angin...? Apakah Lady Victoria benar-benar akan berbaring di dalam sana?",
  ui_story_5084_50840301_77_option_content = "Tautan Telepati",
  ui_story_5084_50840301_78_dialog_content = "(Rasanya seperti ada sesuatu yang menghalangiku...)",
  ui_story_5084_50840301_79_dialog_content = "Haha…",
  ui_story_5084_50840301_80_dialog_content = "Haha... Hahahaha...",
  ui_story_5084_50840301_81_dialog_content = "Hahahaha... Hahahahaha...",
  ui_story_5084_50840301_82_dialog_content = "(Itu beberapa tawa yang menyeramkan... Apa sebenarnya yang mereka lakukan?)",
  ui_story_5084_50840301_83_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840301_84_dialog_content = "(Bahkan orang Wilhelm itu juga ikut bergabung...)",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName?",
  ui_story_5084_50840301_87_dialog_content = "Jangan khawatir, May! Aku tepat di sini!",
  ui_story_5084_50840301_88_dialog_content = "Apa-apaan…?!",
  ui_story_5084_50840301_89_dialog_content = "Sepertinya angin hitam tadi telah memadamkan lilinku... Aku tidak bisa melihat apa-apa di sini!",
  ui_story_5084_50840301_90_dialog_content = "Cara orang-orang itu tertawa sangat mengganggu... Apakah mereka semua bersekongkol satu sama lain?",
  ui_story_5084_50840301_91_dialog_content = "Belum lagi semua hal yang dikatakan pria bernama Wilhelm tentang Victoria...",
  ui_story_5084_50840301_92_dialog_content = "Dia tidak dalam bahaya, bukan? Tidak... Aku harus tahu apa yang mereka tertawakan!",
  ui_story_5084_50840301_93_option_content = "Peningkatan Kekuatan—",
  ui_story_5084_50840301_94_dialog_content = "(A-Aku... Aku hampir tidak bisa melihat apa-apa... Apa yang terjadi di sini...?)",
  ui_story_5084_50840301_95_dialog_content = "Apakah kepemimpinan True Order telah memakan korban setelah semua tahun ini, Wilhelm Varaki?",
  ui_story_5084_50840301_96_dialog_content = "Kamu tahu persis apa artinya bagi seseorang untuk masuk ke peti mati itu. Pasti kamu memiliki motif tersembunyi untuk memilih putri dari <color=#FFB400>Osten Varaki</color>?",
  ui_story_5084_50840301_97_dialog_content = "Dia adalah pemimpin sebelumnya dari True Order dan kakak laki-lakiku. Tentu saja, mengawasi putri kesayangannya adalah tanggung jawabku.",
  ui_story_5084_50840301_98_dialog_content = "(Tunggu, jadi Wilhelm... Adalah paman Victoria?)",
  ui_story_5084_50840301_99_dialog_content = "Aku mulai lelah dengan kata-kata sombongmu, Varaki.",
  ui_story_5084_50840301_100_dialog_content = "Saya sangat menyadari bahwa kamu belum menemukan solusi.",
  ui_story_5084_50840301_101_dialog_content = "Jika kamu benar-benar memiliki kepentingan terbaik untuknya, kenapa tidak bergabung dengannya di sana...?",
  ui_story_5084_50840301_102_dialog_content = "Tunggu—",
  ui_story_5084_50840301_103_dialog_content = "Apa yang kamu pikir kamu lakukan, Wilhelm? Ini sama sekali tidak seperti yang kamu katakan sebelumnya.",
  ui_story_5084_50840301_104_dialog_content = "Memang bukan, Clavis. Namun, kamu sudah membuat keputusanmu.",
  ui_story_5084_50840301_105_dialog_content = "...",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_107_dialog_content = "(Oh tidak... Sepertinya angin hitam ini ditujukan untuk menyembunyikan segalanya sejak awal...)",
  ui_story_5084_50840301_108_dialog_content = "(Clavis, Wilhelm, dan Victoria... Apa yang mereka rencanakan?)",
  ui_story_5084_50840301_109_dialog_content = "Urgh, berhenti mencengkeramku begitu kuat, PlayerName! Kamu akan mematahkan lenganku...",
  ui_story_5084_50840301_110_dialog_content = "O-oh, maaf...",
  ui_story_5084_50840301_111_dialog_content = "Di sana, jauh lebih baik!",
  ui_story_5084_50840301_112_dialog_content = "Saya harus memikirkan sesuatu... Tapi apa yang sebenarnya bisa saya lakukan...?",
  ui_story_5084_50840301_113_dialog_content = "Dan apa yang terjadi antara Victoria dan pamannya? Mengapa dia berkorban untuk keponakannya sendiri...?",
  ui_story_5084_50840301_114_dialog_content = "Apakah kamu mencoba membuat rencana, PlayerName? Nyala lilin berkedip-kedip... Lihat, pemandangan mulai berubah.",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>Lubang-tepuk, lubang-tepuk...</color>",
  ui_story_5084_50840401_2_dialog_content = "Suara itu...!",
  ui_story_5084_50840401_3_dialog_content = "Meong?",
  ui_story_5084_50840401_4_dialog_content = "Jangan takut, Beau! Aku di sini!",
  ui_story_5084_50840401_5_dialog_content = "Syukurlah kalian berdua masih di sana. Untuk sejenak, aku pikir aku sendirian lagi.",
  ui_story_5084_50840401_6_dialog_content = "Sepertinya kita berakhir di tempat baru. Ada aroma yang enak juga. Apakah itu aroma pakaian bersih...?",
  ui_story_5084_50840401_7_dialog_content = "Hah?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5084_50840401_9_dialog_content = "S-Seseorang di sini!",
  ui_story_5084_50840401_10_dialog_content = "Mmph... Hei, jangan tutupi... Mmph!",
  ui_story_5084_50840401_11_dialog_content = "... Hmph. Aku memakai pakaian ini kemarin, yang membuatnya menjadi sejarah lama sekarang.",
  ui_story_5084_50840401_12_dialog_content = "Dan kain ini terasa seperti amplas di kulitku! Aku adalah seniman, bukan tukang kayu rendahan...",
  ui_story_5084_50840401_13_dialog_content = "Untuk yang ini... Warnanya sangat tidak kreatif... Seorang seniman sejati tidak akan pernah menyerah untuk mengenakan warna yang begitu hambar.",
  ui_story_5084_50840401_14_dialog_content = "Bah! Apakah ini dibuat di toko pakaian anak-anak?! Saya lebih dari cukup umur untuk memakai pakaian dewasa!",
  ui_story_5084_50840401_15_dialog_content = "Sial semua ini—! Aku seharusnya tidak pernah mempercayai kata-kata Ayah sepenuh hati!",
  ui_story_5084_50840401_16_dialog_content = "Duo yang kurang cerdas itu tidak akan pernah bisa membuat pakaian formal untuk Charon yang hebat!",
  ui_story_5084_50840401_17_dialog_content = "<color=#e8d9bb>Membanting!</color>",
  ui_story_5084_50840401_18_dialog_content = "…?",
  ui_story_5084_50840401_19_dialog_content = "Ch-Charon?!?",
  ui_story_5084_50840401_20_dialog_content = "Tunggu... apa dia tidak bisa melihat kita?",
  ui_story_5084_50840401_21_dialog_content = "Huff, huff... A-Akhirnya, kamu melepaskan aku! Apakah kamu kenal anak ini, PlayerName?",
  ui_story_5084_50840401_22_dialog_content = "Ya... Rambut itu dan ekspresi itu... Tidak ada yang salah mengenali \"hebatnya Charon\" untuk orang lain!",
  ui_story_5084_50840401_23_dialog_content = "Barusan dia berdiri tepat di depan kita, 'kan?",
  ui_story_5084_50840401_24_dialog_content = "Yep, dan sepertinya dia sedang memilih pakaian. Hmm... Pakaian yang beraroma enak ini benar-benar luar biasa! Saya tidak pernah bisa merangkai sesuatu sebaik ini...",
  ui_story_5084_50840401_25_dialog_content = "Jadi kita berada di lemari Charon... Tapi dari penampilannya, dia tampaknya tidak lebih dari sepuluh tahun...",
  ui_story_5084_50840401_26_dialog_content = "Lagi pula... Aku tak pernah bisa menebak usia pria itu. Tapi sepertinya tidak begitu penting, karena kita berada di masa lalu sekarang.",
  ui_story_5084_50840401_27_dialog_content = "Tunggu... Kembali di Advent of Truth, Victoria mengatakan kita berada di tahun 1915, yang berarti...",
  ui_story_5084_50840401_28_dialog_content = "Dan ada apa dengan lilin ini sebenarnya? Selalu membawa saya ke tempat yang berbeda setiap kali mulai berkelip-kelip, dan kali ini malah membawa kamu juga, May!",
  ui_story_5084_50840401_29_dialog_content = "Kamu sangat bodoh, PlayerName! Jelas, itu hanya terjadi karena kamu memegang lilin itu di satu tangan dan Beau di tangan lainnya!",
  ui_story_5084_50840401_30_dialog_content = "Sikare memiliki berbagai jenis benda ajaib yang kuat di disposisinya. Tetapi jika kamu tidak percaya pada sihir, maka tidak banyak lagi yang bisa dikatakan.",
  ui_story_5084_50840401_31_dialog_content = "...? Apakah kamu tidak khawatir atau bahkan penasaran tentang semua hal yang baru saja kita lihat?",
  ui_story_5084_50840401_32_dialog_content = "Apakah kamu maksud penasaran yang bahagia, atau yang ketakutan?",
  ui_story_5084_50840401_33_dialog_content = "Ah, apa peduli? Aku suka dua-duanya! Hahaha!",
  ui_story_5084_50840401_34_dialog_content = "Lalu apakah lilin ini alasan bahwa Charon tidak bisa melihat atau mendengar kita...?",
  ui_story_5084_50840401_35_dialog_content = "Hal yang sama terjadi kembali di Temple of Truth... Hanya Victoria dari masa sekarang yang bisa melihat kami.",
  ui_story_5084_50840401_36_dialog_content = "Ini seperti barang dari salah satu cerita itu! Jenis yang bisa memberikan kemampuan tidak terlihat!",
  ui_story_5084_50840401_37_dialog_content = "Hahaha, sudah pasti!",
  ui_story_5084_50840401_38_dialog_content = "Kita tidak tahu apa yang terjadi pada Victoria setelah dia masuk ke dalam peti itu, atau di mana Nails dan Faust berada sekarang...",
  ui_story_5084_50840401_39_dialog_content = "Benarkah kita sampai di sini dengan mengikuti petunjuk dari hati kita...?",
  ui_story_5084_50840401_40_dialog_content = "Apa yang sedang kamu pikirkan tadi?",
  ui_story_5084_50840401_41_dialog_content = "Maksud kamu ketika cahaya lilin mulai berkelap-kelip? Itu seperti...",
  ui_story_5084_50840401_42_dialog_content = "\"Clavis, Wilhelm, dan Victoria... Apa yang mereka rencanakan?\"",
  ui_story_5084_50840401_43_dialog_content = "Jika ayah Charon dan \"duo bodoh\" itu adalah tiga dari mereka...",
  ui_story_5084_50840401_44_dialog_content = "Mungkin ini yang dimaksud Sikare ketika dia mengatakan lilin akan menjadi pemanduku!",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5084_50840401_46_dialog_content = "Saya melakukan ini hanya untuk melestarikan sifat tidak memihak dari seni saya. Kaus kaki ini adalah harta terbesar saya, tetapi dengan berat hati saya akan menggantinya demi kebaikan mereka.",
  ui_story_5084_50840401_47_dialog_content = "(Charon sangat serius ketika harus mengganti bajunya...)",
  ui_story_5084_50840401_48_dialog_content = "\"Oh Tuhan Charon, di mana kamu menemukan untuk membeli kaus kaki yang begitu mempesona dan megah?\"",
  ui_story_5084_50840401_49_dialog_content = "\"Tak ada selera yang bisa menyamai milikmu, Tuan Charon...\"",
  ui_story_5084_50840401_50_dialog_content = "Hmph, jadi ini rasanya menjadi terkenal? Sungguh keberadaan yang merepotkan...",
  ui_story_5084_50840401_51_dialog_content = "<color=#e8d9bb>Membanting!</color>",
  ui_story_5084_50840401_52_dialog_content = "...",
  ui_story_5084_50840401_53_dialog_content = "Dia sudah berbeda dari semua orang sejak dia masih anak-anak, ya...",
  ui_story_5084_50840401_54_dialog_content = "Ayo kita lihat sekeliling, May. Jangan berjalan terlalu jauh dariku meskipun!",
  ui_story_5084_50840401_55_dialog_content = "Aku tahu, aku tahu!",
  ui_story_5084_50840401_56_dialog_content = "Lama tidak bertemu, Clavis.",
  ui_story_5084_50840401_57_dialog_content = "Halo, Paman Clavis.",
  ui_story_5084_50840401_58_dialog_content = "Ini Lady Victoria! Hei—",
  ui_story_5084_50840401_59_dialog_content = "Tenanglah, May! Meskipun dia tidak merespon, saya yakin dia sudah menyadari keberadaan kita dari jarak ini. Ini pasti versi lain dari dirinya di masa lalu, bukan?",
  ui_story_5084_50840401_60_dialog_content = "Meski tampaknya tidak banyak berbeda dari Victoria yang kita kenal saat ini...",
  ui_story_5084_50840401_61_dialog_content = "Itu karena dia adalah anggota bangsawan dari keluarga darah! Begitu dia membangkitkan kekuatannya, proses penuaan berhenti untuknya.",
  ui_story_5084_50840401_62_dialog_content = "Dan mengapa kamu masih bersembunyi jika orang-orang di masa lalu tidak bisa melihat kita, PlayerName?",
  ui_story_5084_50840401_63_dialog_content = "Hah?! Oh ya... Mungkin karena segala sesuatu dan setiap orang di sekitar sini terlihat sedikit menakutkan?",
  ui_story_5084_50840401_64_dialog_content = "Haha... Melihat kalian berdua di sini pada saat yang sama cukup jarang terjadi.",
  ui_story_5084_50840401_65_dialog_content = "Hmmm...",
  ui_story_5084_50840401_66_dialog_content = "Di mana Charon muda?!?",
  ui_story_5084_50840401_67_dialog_content = "Oh, kamu tahu anak laki-laki itu. Begitu dia tahu kita mengharapkan tamu, dia menghabiskan berjam-jam untuk membuat dirinya tampak rapi...",
  ui_story_5084_50840401_68_dialog_content = "...",
  ui_story_5084_50840401_69_dialog_content = "Hei, Tuan Charon. Kaos kaki bagus yang kamu miliki di sana.",
  ui_story_5084_50840401_70_dialog_content = "K-Katakan apapun yang kamu mau, aku masih tidak akan...",
  ui_story_5084_50840401_71_dialog_content = "Jaga sopan santunmu, Charon.",
  ui_story_5084_50840401_72_dialog_content = "... Halo, Paman Wilhelm.",
  ui_story_5084_50840401_73_dialog_content = "Bukankah kamu lupa seseorang? Ini adalah Victoria, keponakan Paman Wilhelm kamu.",
  ui_story_5084_50840401_74_dialog_content = "Halo, sepupu.",
  ui_story_5084_50840401_75_dialog_content = "... Halo, sepupu.",
  ui_story_5084_50840401_76_dialog_content = "Charon, kenapa kamu tidak membawa Victoria ke ruangan lain dan minum teh serta makanan penutup?",
  ui_story_5084_50840401_77_dialog_content = "... Ya, Ayah.",
  ui_story_5084_50840401_78_dialog_content = "Saya terkejut Anda memiliki waktu untuk mengunjungi kami di Old Town. Apakah masalah di Varaki Town lebih atau kurang terselesaikan?",
  ui_story_5084_50840401_79_dialog_content = "Datang ke sini sama sekali tidak mudah, tapi kamu tahu saya akan melakukan perjalanan sejauh apapun untuk bertemu denganmu, Clavis.",
  ui_story_5084_50840401_80_dialog_content = "...",
  ui_story_5084_50840401_81_dialog_content = "...",
  ui_story_5084_50840401_82_dialog_content = "Berapa lama kau akan terus menatapku?",
  ui_story_5084_50840401_83_dialog_content = "Apakah kamu bersekutu dengan orang-orang malang lainnya?",
  ui_story_5084_50840401_84_dialog_content = "Orang-orang sial yang mana, tepatnya?",
  ui_story_5084_50840401_85_dialog_content = "Tahu 'kan, para pemuja itu yang sama seperti Wilhelm Varaki.",
  ui_story_5084_50840401_86_dialog_content = "Jika yang kamu maksud adalah True Order, maka tidak, aku bukan salah satu dari mereka. Juga cukup tidak sopan untuk menyebut pemimpin mereka dengan nama lengkap, bukan menurutmu?",
  ui_story_5084_50840401_87_dialog_content = "Panggil saja itu intuisi seorang seniman, tetapi tidak ada satu pun yang berhubungan dengannya yang melakukan sesuatu yang baik. Hanya atas permintaan ayahku, aku muncul di hadapanmu hari ini.",
  ui_story_5084_50840401_88_dialog_content = "Kamu bilang kamu tidak tahan dengan rekan ayahmu, dan namun kamu berusaha keras untuk membuat dirimu tampak layak.",
  ui_story_5084_50840401_89_dialog_content = "...! I-Ini semua demi seni!",
  ui_story_5084_50840401_90_dialog_content = "Oh? Lalu apa sebenarnya itu seni?",
  ui_story_5084_50840401_91_dialog_content = "Kamu sadar bahwa kita semua harus mati suatu hari, bukan? Namun, ada satu hal di dunia ini yang tidak pernah bisa mati; apakah kamu tahu apa itu?",
  ui_story_5084_50840401_92_dialog_content = "Ini seni!",
  ui_story_5084_50840401_93_dialog_content = "Seni adalah bunga terlarang yang bisa mekar di kedalaman neraka! Kereta api yang tak terhentikan yang muncul dari air sungai Styx.",
  ui_story_5084_50840401_94_dialog_content = "Dan aku akan menjadi kondektur, seorang jurumudi jiwa, dan sebuah karya seni abadi.",
  ui_story_5084_50840401_95_dialog_content = "Sebuah karya seni abadi, katamu... Heheh, sepertinya aku ditakdirkan menjadi penumpangmu suatu hari nanti.",
  ui_story_5084_50840401_96_dialog_content = "Tentu saja! Tunggu, sejak orang-orang bodoh itu mengejek keahlian seniku...",
  ui_story_5084_50840401_97_dialog_content = "Seorang anak seumur ini seharusnya tidak begitu terobsesi dengan urinoir...",
  ui_story_5084_50840401_98_dialog_content = "... Seperti seorang pria yang terlalu mabuk, kelalaian cerobohnya hampir menghibur.",
  ui_story_5084_50840401_99_dialog_content = "Sejak hari itu, saya memutuskan bahwa hanya mereka yang menghargai seni saya yang bisa naik kereta saya...",
  ui_story_5084_50840401_100_dialog_content = "Saya menolak untuk menerima siapa pun yang telah hidup terlalu lama, berperilaku terlalu kasar, atau tidak memiliki selera dalam seni.",
  ui_story_5084_50840401_101_dialog_content = "Kamu cukup percaya diri, Charon.",
  ui_story_5084_50840401_102_dialog_content = "Itu hanya alami, karena tidak ada orang lain di Kota Tua yang memiliki selera yang bisa menyaingi diriku.",
  ui_story_5084_50840401_103_dialog_content = "Dan suatu hari nanti, saya akan mendirikan kelompok teater saya sendiri, serta kelompok untuk menghargai hal-hal seperti musik, seni, dan kereta api model...",
  ui_story_5084_50840401_104_dialog_content = "Aku tidak keberatan memberitahumu, sejak lama aku telah menemukan \"kebenaran\" yang selalu diperbincangkan oleh orang-orang bodoh itu. Itu adalah seni, sederhana dan jelas.",
  ui_story_5084_50840401_105_dialog_content = "Nah? Karena kamu belum menemukan organisasi untuk bergabung, apakah kamu cukup berani untuk menghadapi proses penerimaan saya?",
  ui_story_5084_50840401_106_dialog_content = "Heheh, menarik. Dan apa sebenarnya \"proses pengakuan\" ini milikmu?",
  ui_story_5084_50840401_107_dialog_content = "Sungguh sederhana. Ketika kamu melihat kereta apiku lewat, mobilisasi semua indra kamu dan masuk ke dunia seniku! Setelah itu, kamu juga harus menunjukkan pemahamanmu tentang seni.",
  ui_story_5084_50840401_108_dialog_content = "Sangat baik, saya terima.",
  ui_story_5084_50840401_109_dialog_content = "Maka tunggulah di sana. Ayah tidak setuju aku menunjukkan hal-hal ini kepada orang lain.",
  ui_story_5084_50840401_110_dialog_content = "Sekarang nikmati penampilan seorang conductor dan saksikan arti sebenarnya dari seni!",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian...</color>",
  ui_story_5084_50840401_112_dialog_content = "Dengarkan dengan saksama! Rel kereta api bergema dengan tangisan kiamat!",
  ui_story_5084_50840401_113_dialog_content = "Saksikan kereta terakhir berangkat dari dunia yang sekarat menuju keabadian! ",
  ui_story_5084_50840401_114_dialog_content = "Hanya seniman yang bercita-cita untuk keabadian yang boleh menaikinya dan bepergian melampaui surga yang mulia! ",
  ui_story_5084_50840401_115_dialog_content = "Bebas dari rantai yang memenjarakan tubuhnya, roda yang tak terikat ini berputar tanpa henti saat ia terus melaju selamanya!",
  ui_story_5084_50840401_116_dialog_content = "Mesin ini mengarah ke langit dan aku, Charon yang hebat, adalah konduktornya! Bersama, kita akan melarikan diri dari jurang terkutuk ini!",
  ui_story_5084_50840401_117_dialog_content = "Aku akan memerintahkan neraka itu sendiri untuk membuka gerbangnya dan membiarkan cahaya dunia baru masuk!",
  ui_story_5084_50840401_118_dialog_content = "Wow... Aku rasa aku benar-benar melihat kereta api dalam kegelapan...",
  ui_story_5084_50840401_119_dialog_content = "Itu adalah Charon untukmu... Tidak peduli kemana dia pergi, dunia adalah panggungnya...",
  ui_story_5084_50840401_120_dialog_content = "Ka-chunk, ka-chunk, ka-chunk—! Dengarkan simfoni dunia lama dan baru saat keluar dari mulutku! Jangan takut pada suaranya!",
  ui_story_5084_50840401_121_dialog_content = "Sekarang berkendara! Berkendara sampai kita menembus pintu dunia baru! Surga abadi menanti kita!",
  ui_story_5084_50840401_122_dialog_content = "...",
  ui_story_5084_50840401_123_dialog_content = "Sekarang giliranmu, sepupu!",
  ui_story_5084_50840401_124_dialog_content = "Heheh, kamu memang memiliki bakat untuk drama, tetapi \"pintu ke dunia baru\" ini hanyalah ilusi!",
  ui_story_5084_50840401_125_dialog_content = "\"Pintu\" yang sangat kamu cari itu lebih mirip dinding tanpa bentuk yang akan dengan keras menabrak wajahmu!",
  ui_story_5084_50840401_126_dialog_content = "Rel kereta api akan menyala, dan raksasa merah dan emas ini akan membakar mimpi-mimpi Anda menjadi abu.",
  ui_story_5084_50840401_127_dialog_content = "Kematian adalah Kebenaran mutlak! Prelude untuk akhir harus ditawarkan sebagai penghormatan! Keabadian hanyalah ketakutan dan panik yang tak berujung!",
  ui_story_5084_50840401_128_dialog_content = "Ketakutan akan menghancurkanmu menjadi serangga yang tidak berarti dan menjebakmu dalam sangkar keabadian tanpa harapan untuk melarikan diri.",
  ui_story_5084_50840401_129_dialog_content = "Sebuah mainan tak berdaya untuk diperhatikan dan disiksa oleh makhluk yang lebih tinggi!",
  ui_story_5084_50840401_130_dialog_content = "Lihat ke atas!",
  ui_story_5084_50840401_131_dialog_content = "Inilah realitas dunia baru—Siklus manipulasi yang tak ada habisnya!",
  ui_story_5084_50840401_132_dialog_content = "…!",
  ui_story_5084_50840401_133_dialog_content = "Di mata penguasa tersembunyi kita, kegilaanmu hanya menjadi hiburan bagi mereka.",
  ui_story_5084_50840401_134_dialog_content = "Kekuatan untuk menginspirasi ketakutan adalah seni sejati!",
  ui_story_5084_50840401_135_dialog_content = "... Waaaahhhh!",
  ui_story_5084_50840401_136_dialog_content = "... Sepupu, kamu—!",
  ui_story_5084_50840401_137_dialog_content = "Ini jauh lebih menarik daripada seni abadi, bukan?",
  ui_story_5084_50840401_138_dialog_content = "Hahahahahahaha...!",
  ui_story_5084_50840401_139_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_140_dialog_content = "K-Keretaku... Hentikan! Hentikan sekarang juga!",
  ui_story_5084_50840401_141_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840401_142_dialog_content = "Saya tidak tahu Lady Victoria memiliki sepupu kecil yang lucu.",
  ui_story_5084_50840401_143_dialog_content = "Hah? Sepertinya kamu melewatkan masalah sebenarnya di sini... Bagaimana bisa Victoria begitu kejam pada Charon?!",
  ui_story_5084_50840401_144_dialog_content = "Tak heran dia selalu enggan membicarakan Victoria sebagai kerabatnya... Seni macam apa ini?!",
  ui_story_5084_50840401_145_dialog_content = "Saya tidak bisa setuju dengan itu, Wilhelm...",
  ui_story_5084_50840401_146_dialog_content = "Apa yang sangat kamu takuti, Clavis? Atau apakah kamu benar-benar gagal melihat memburuknya situasi kita?",
  ui_story_5084_50840401_147_dialog_content = "Porfirio dan penguasa rumah telah berhenti mengikuti aturan setelah memisahkan diri dari garis keturunan Varaki.",
  ui_story_5084_50840401_148_dialog_content = "Kamu tidak akan menyelamatkan siapa pun seperti ini.",
  ui_story_5084_50840401_149_dialog_content = "Tapi dalam keadaan sekarang, True Order tidak lebih dari kutukan bagi kita dan orang-orang di kota ini! Ajaran dari keluarga berdarah memenjarakan kita semua!",
  ui_story_5084_50840401_150_dialog_content = "Haus darah ada dalam sifat kita, Wilhelm... Dalam darah kita sendiri. Dan meskipun kamu dan aku sedikit lebih beruntung daripada yang lain, kita tidak berbeda dalam hal ini.",
  ui_story_5084_50840401_151_dialog_content = "Alam kita, katamu...? Sejak kapan kamu mulai peduli dengan pembicaraan seperti ini, Clavis?",
  ui_story_5084_50840401_152_dialog_content = "Jangan salahkan aku untuk ini, Wilhelm. Aku hanya tidak bisa menyangkal apa yang aku tahu itu benar...",
  ui_story_5084_50840401_153_dialog_content = "Kunci <color=#FFB400>itu</color> hanya akan membawa bahaya untukmu.",
  ui_story_5084_50840401_154_dialog_content = "Tepat sebelum dia meninggal, saudara saya mengambilnya kembali dari <color=#FFB400>Vinekeepers</color> dan memberikannya kepada kamu... Jelas, itu adalah untuk memastikan bahwa kunci itu akan sampai di tangan saya suatu hari nanti.",
  ui_story_5084_50840401_155_dialog_content = "... Atau mungkin itu untuk mencegah Anda mengambilnya secara paksa dari <color=#FFB400>Vinekeepers</color> sendiri.",
  ui_story_5084_50840401_156_dialog_content = "Meskipun cara Anda tidak ortodoks, Anda telah memimpin True Order sebagai pengganti saudara Anda selama bertahun-tahun sekarang.",
  ui_story_5084_50840401_157_dialog_content = "Semua yang telah terjadi telah diprediksi dalam nubuat kuno.",
  ui_story_5084_50840401_158_dialog_content = "Jalannya takdir tidak bisa diubah. Kamu tahu ini lebih baik daripada saya.",
  ui_story_5084_50840401_159_dialog_content = "Tidak! Saya menolak untuk menerimanya!",
  ui_story_5084_50840401_160_dialog_content = "Aku menaruh kepercayaanku pada Lord of Truth; nasib Varaki tidak penting bagiku! Paling tidak, aku menolak untuk menerima apa yang disebut \"jalur takdir...\" ini.",
  ui_story_5084_50840401_161_dialog_content = "Tak peduli apa yang menimpa saya, saya akan bertahan. Saya harus.",
  ui_story_5084_50840401_162_dialog_content = "Sejak awal, aku hanya mengikuti petunjuk hatiku. Bagiku, itu adalah Truth.",
  ui_story_5084_50840401_163_dialog_content = "Dan bagaimana dengan Victoria? Saudaramu menyerahkan dia padamu—",
  ui_story_5084_50840401_164_dialog_content = "Tak perlu menyebut dia, Clavis.",
  ui_story_5084_50840401_165_dialog_content = "Penghinaan Victoria terhadap kekuatan kita dan ketidakpeduliannya terhadap urusan Kota Varaki bahkan lebih besar daripada milikku. Dia bisa menjaga dirinya sendiri.",
  ui_story_5084_50840401_166_dialog_content = "Heheh... Mungkin ini juga hukuman untuk tindakan kakakku.",
  ui_story_5084_50840401_167_dialog_content = "Wilhelm...",
  ui_story_5084_50840401_168_dialog_content = "Dalam hal apapun... Tolong jaga keluargamu dengan baik, Clavis.",
  ui_story_5084_50840401_169_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_170_dialog_content = "...",
  ui_story_5084_50840401_171_dialog_content = "Sudah waktunya kita pergi, Victoria Varaki.",
  ui_story_5084_50840401_172_dialog_content = "...",
  ui_story_5084_50840401_173_dialog_content = "Sudah? Tapi aku belum belajar apa-apa... Aku harus menemukan cara untuk mengejar mereka... Tunggu, itu dia! Aku hanya perlu fokus, dan...",
  ui_story_5084_50840401_174_dialog_content = "Berhasil! Lilinnya mulai berkedip! Cepat—",
  ui_story_5084_50840401_175_dialog_content = "Keringkan air matamu, Charon...",
  ui_story_5084_50840401_176_dialog_content = "Kutuk dia... Kutuk wanita gila itu...!",
  ui_story_5084_50840401_177_dialog_content = "Cukup! Sekarang, angkut semua potongan yang rusak itu!",
  ui_story_5084_50840401_178_dialog_content = "... Endus...",
  ui_story_5084_50840501_1_dialog_content = "Saya rasa saya sudah mulai mengerti sekarang. Ketika lilin mulai berkedip, saya mulai bertanya-tanya apa yang dipikirkan Wilhelm.",
  ui_story_5084_50840501_2_dialog_content = "Jadi apakah itu berarti... Kita sekarang berada di rumah Lord Wilhelm?",
  ui_story_5084_50840501_3_dialog_content = "Dia orangnya! Tuan Wilhelm!",
  ui_story_5084_50840501_4_dialog_content = "Dia terlihat sangat sedih memegang cincin itu...",
  ui_story_5084_50840501_5_dialog_content = "Kami masih belum tahu apa yang sebenarnya dia pikirkan, meskipun begitu.",
  ui_story_5084_50840501_6_dialog_content = "Kamu adalah Caelestite Terakhir yang legendaris, bukan? Cukup menguping pikirannya saja!",
  ui_story_5084_50840501_7_dialog_content = "D-Jangan sebut itu \"menguping\"! Itu bukanlah tujuan dari kekuatanku!",
  ui_story_5084_50840501_8_dialog_content = "Yah, bagaimana lagi kita seharusnya bisa mencari tahu apa yang dia rencanakan?!",
  ui_story_5084_50840501_9_dialog_content = "...",
  ui_story_5084_50840501_10_dialog_content = "Berhenti membuang-buang waktu sekarang juga! Sebagai orang dewasa, kamu harus lebih tegas!",
  ui_story_5084_50840501_11_dialog_content = "Baiklah! Saya cukup yakin itu tidak melanggar aturan Sikare jika saya hanya membaca pikirannya sedikit...",
  ui_story_5084_50840501_12_option_content = "Telepati—",
  ui_story_5084_50840501_13_dialog_content = "Bisikan yang terperangkap dalam peninggalan ini... Hanya dengan memakainya, aku akan merasakan rasa sakit yang tak terhitung jumlahnya karena ditelan dalam sekejap...",
  ui_story_5084_50840501_14_dialog_content = "Varaki... Dan sisa keluarga darah... Apakah benar kita bisa melarikan diri dari takdir kita...?",
  ui_story_5084_50840501_15_dialog_content = "Lahir sebagai Aurorian namun dikutuk untuk hidup di kota gelap dan tanpa matahari ini, di mana kekuatan hanya bisa diturunkan melalui warisan.",
  ui_story_5084_50840501_16_dialog_content = "Di bawah bimbingan leluhur kami, kami berlari, bersembunyi, dan menjalani hidup yang tidak lebih baik dari kematian...",
  ui_story_5084_50840501_17_dialog_content = "Kehendak leluhur kita... Pewarisan kekuasaan... Betapa sia-sianya. Varaki akan mengabaikan generasi masa depan kita sebelum menyerahkan sedikit pun kontrol.",
  ui_story_5084_50840501_18_dialog_content = "Dan meski kita telah belajar untuk bertahan dengan substitusi darah, tidak ada cara untuk menghilangkan sumber kekuatan jahat kita.",
  ui_story_5084_50840501_19_dialog_content = "(Substitusi darah... \"Sari kehidupan\" yang selalu dibicarakan Victoria... Apakah bisa jadi...?)",
  ui_story_5084_50840501_20_dialog_content = "Kutuk cincin neraka ini...",
  ui_story_5084_50840501_21_dialog_content = "Kutuklah semuanya...",
  ui_story_5084_50840501_22_dialog_content = "Dengan setiap tahun yang berlalu, kepala keluarga semakin lapar akan darah segar...",
  ui_story_5084_50840501_23_dialog_content = "Huh, Clavis... Sudah tiga tahun sejak kita terakhir berbicara. Aku penasaran bagaimana keadaannya sekarang ini?",
  ui_story_5084_50840501_24_dialog_content = "(Sudah tiga tahun sejak Wilhelm dan Victoria mengunjungi ayah Charon? Tunggu... Jadi sekarang tahun berapa?)",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5084_50840501_26_dialog_content = "...",
  ui_story_5084_50840501_27_dialog_content = "Ini Victoria...",
  ui_story_5084_50840501_28_dialog_content = "Tapi kehadirannya itu... Sepertinya masih versi masa lalunya.",
  ui_story_5084_50840501_29_dialog_content = "Ini Lady Victoria dari masa lalu lagi! Jadi, apakah kamu baru saja mendengar sesuatu yang penting?",
  ui_story_5084_50840501_30_dialog_content = "Wilhelm segera menyimpan cincin itu begitu Victoria masuk ke ruangan. Sekarang rasanya seperti ada sesuatu yang menghalangi kekuatanku...",
  ui_story_5084_50840501_31_dialog_content = "Jadi, kamu tidak bisa membaca pikirannya lagi?",
  ui_story_5084_50840501_32_dialog_content = "Benar... Saya pikir cincin itu memberi tekanan besar pada psikisnya. Mari kita lihat apa yang mereka katakan kali ini.",
  ui_story_5084_50840501_33_dialog_content = "Ugh...",
  ui_story_5084_50840501_34_dialog_content = "Selamat kembali... Kali ini kamu pergi selama tiga bulan. Bagaimana hasilnya?",
  ui_story_5084_50840501_35_dialog_content = "... Itu bukan urusanmu.",
  ui_story_5084_50840501_36_dialog_content = "Sorot matamu... Begitu penuh dengan rasa benci dan ketidakpastian...",
  ui_story_5084_50840501_37_dialog_content = "Apa yang tadi kaulihat di dunia luar, Wilhelm Varaki?",
  ui_story_5084_50840501_38_dialog_content = "Aku tidak ingat membiarkanmu masuk ke kamarmu.",
  ui_story_5084_50840501_39_dialog_content = "Anda adalah pemimpin dari True Order, dan namun Anda sering pergi tanpa menyelesaikan tugas Anda... Anda juga telah menghabiskan lebih sedikit waktu di rumah.",
  ui_story_5084_50840501_40_dialog_content = "Berapa kali harus kukatakan bahwa itu bukan urusanmu?! Sekarang tinggalkan aku!",
  ui_story_5084_50840501_41_dialog_content = "Baiklah; Aku bukan orang asing yang ditolak percakapannya. Tapi mengingat malam ini adalah kedatangan Truth, aku berharap kita bisa memiliki satu diskusi terakhir.",
  ui_story_5084_50840501_42_dialog_content = "Tentang Kebenaran, dan diri kita sendiri...",
  ui_story_5084_50840501_43_dialog_content = "Aku bilang pergi! Jangan buat aku mengulangi perintah!",
  ui_story_5084_50840501_44_dialog_content = "...",
  ui_story_5084_50840501_45_dialog_content = "Lord Wilhelm begitu bermusuhan sekarang... Apa yang mungkin terjadi padanya...?",
  ui_story_5084_50840501_46_dialog_content = "... Nngh... <size=45>Arrrgh...!</size>",
  ui_story_5084_50840501_47_dialog_content = "Ada yang tidak beres dengan Lord Wilhelm... Cepat, lakukan sesuatu!",
  ui_story_5084_50840501_48_dialog_content = "Apakah itu cincin itu...?",
  ui_story_5084_50840501_49_option_content = "Telepati—",
  ui_story_5084_50840501_50_dialog_content = "Hahahahaha! Gigit jari-jarinya! Patahkan leher kecilnya yang cantik!",
  ui_story_5084_50840501_51_dialog_content = "Jadilah diam...",
  ui_story_5084_50840501_52_dialog_content = "Betapa bodohnya. Dalam keputusasaanmu untuk mempertahankan kekuasaan, kau dengan sukarela memakai cincin yang membuatmu gila di depan pemimpin sejati dari rakyatmu.",
  ui_story_5084_50840501_53_dialog_content = "Apakah kamu ingin mengakhiri hidupnya... Atau hidupmu sendiri?",
  ui_story_5084_50840501_54_dialog_content = "Heheh... Aku sudah mati rasa terhadap rasa sakit yang kamu berikan padaku sejak lama...",
  ui_story_5084_50840501_55_dialog_content = "Varaki akan hancur di tanganmu.",
  ui_story_5084_50840501_56_dialog_content = "Heh... Jika aku ditakdirkan untuk hancur, maka True Order akan berbagi takdirku...",
  ui_story_5084_50840501_57_dialog_content = "Dia telah membuat banyak aliansi baru. Setelah garis keturunan Varaki dihapuskan, True Order akan lahir kembali.",
  ui_story_5084_50840501_58_dialog_content = "Dia akan menjadi orang yang mengakhiri Varaki sekali dan untuk selamanya.",
  ui_story_5084_50840501_59_dialog_content = "Termasuk aku?",
  ui_story_5084_50840501_60_dialog_content = "Hanya dengan mati di tangan mereka, kau akan benar-benar mulai hidup...",
  ui_story_5084_50840501_61_dialog_content = "Bisakah kamu mendengar dirimu sendiri sekarang?",
  ui_story_5084_50840501_62_dialog_content = "Ya, dan aku menyuruhmu untuk mati!!",
  ui_story_5084_50840501_63_dialog_content = "(Suara-suara ini sangat menakutkan! Seperti mereka sedang menggerogoti kesadaran Wilhelm...)",
  ui_story_5084_50840501_64_dialog_content = "(Bisakah jadi cincin ini memberikan pemakainya kekuatan besar sebagai imbalan menyebabkan mereka menderita sangat?)",
  ui_story_5084_50840501_65_dialog_content = "(Memang terdengar sangat seperti sesuatu dari True Order, itu pasti...)",
  ui_story_5084_50840501_66_dialog_content = "(Dan suara-suara siapa itu? Leluhur Varaki? Pemilik asli cincin itu? Atau mungkin...)",
  ui_story_5084_50840501_67_dialog_content = "<size=45>Urgh... Ahhhhhhhhh!</size>",
  ui_story_5084_50840501_68_dialog_content = "Berjuang melawan takdir sepuas hati Anda...",
  ui_story_5084_50840501_69_dialog_content = "Keluar... Sekarang!!!",
  ui_story_5084_50840501_70_dialog_content = "Kenali batasmu, bodoh.",
  ui_story_5084_50840501_71_dialog_content = "Tubuhku... <size=45>Keluar dari tubuhku!!!</size>",
  ui_story_5084_50840501_72_dialog_content = "Lord of Truth...! Tunjukkan aku jalan!!!",
  ui_story_5084_50840501_73_dialog_content = "(Wilhelm akan pingsan!)",
  ui_story_5084_50840501_74_dialog_content = "(Suara-suara ini berubah menjadi monster di pikirannya. Mungkin aku bisa melakukan sesuatu di sini!)",
  ui_story_5084_50840502_1_dialog_content = "Oh? Sepertinya kamu telah mempelajari kemampuan baru, Wilhelm...",
  ui_story_5084_50840502_2_dialog_content = "Pikiranmu... Begitu tenang dan stabil...",
  ui_story_5084_50840502_3_dialog_content = "...",
  ui_story_5084_50840502_4_dialog_content = "(Uh-oh! Jangan bilang mereka memperhatikanku...)",
  ui_story_5084_50840502_5_dialog_content = "Sebagai imbalannya, aku akan membiarkanmu melihat sesuatu yang menarik.",
  ui_story_5084_50840502_6_dialog_content = "May Truth memberkati dia.",
  ui_story_5084_50840502_7_dialog_content = "Akhirnya... Prestasi besar lainnya kini telah selesai.",
  ui_story_5084_50840502_8_dialog_content = "Darah seorang murid... Betapa aku merindukan rasanya...",
  ui_story_5084_50840502_9_dialog_content = "Apa pengetahuan yang kamu dapatkan dari Truth?",
  ui_story_5084_50840502_10_dialog_content = "Truth menunjukkan satu hal kepada saya... Rasa terima kasih.",
  ui_story_5084_50840502_11_dialog_content = "Hanya di bawah cahaya bulan darah kita benar-benar dapat meredakan dahaga kita akan darah.",
  ui_story_5084_50840502_12_dialog_content = "Para pengikut setia menari liar saat mereka berdoa, menawarkan tubuh mereka yang telah mereka hukum sendiri kepada dewa yang mereka tidak akan pernah benar-benar mengerti.",
  ui_story_5084_50840502_13_dialog_content = "Selama berabad-abad... Mereka telah hidup dengan cara ini...",
  ui_story_5084_50840502_14_dialog_content = "Tetapi rasa lezat ini layak mendapatkan lebih banyak penghargaan...",
  ui_story_5084_50840502_15_dialog_content = "Mengapa tidak memilih beberapa murid setia lagi untuk Advent Truth tahun ini?",
  ui_story_5084_50840502_16_dialog_content = "Apakah ini pengetahuan yang kamu peroleh dari mengkonsumsi darah dari pelayan yang setia ini?",
  ui_story_5084_50840502_17_dialog_content = "Tidak sepenuhnya.",
  ui_story_5084_50840502_18_dialog_content = "Ketika The Truth mengalir melalui tubuh mereka, kami mengonsumsi darah mereka untuk mendapatkan pengetahuan ini dan meneruskannya ke generasi mendatang.",
  ui_story_5084_50840502_19_dialog_content = "Ini adalah perjanjian antara kita, kepala keluarga, dan orang-orang yang setia.",
  ui_story_5084_50840502_20_dialog_content = "Pengorbanan seperti itu tidak berarti jika tidak memungkinkan kita untuk menyaksikan The Truth.",
  ui_story_5084_50840502_21_dialog_content = "Apakah ada yang diungkapkan kepada Anda?",
  ui_story_5084_50840502_22_dialog_content = "Tentu saja.",
  ui_story_5084_50840502_23_dialog_content = "Biarkan saya mengingatkan Anda tentang prinsip-prinsip kita dan kebutuhan kita akan kerahasiaan.",
  ui_story_5084_50840502_24_dialog_content = "Sebagai kepala keluarga, kamu berkewajiban untuk mempertahankannya. Dalam keadaan apapun, kita tidak diperbolehkan kembali ke cara-cara barbar kita yang lama.",
  ui_story_5084_50840502_25_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840502_26_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840502_27_dialog_content = "Visi-visi ini telah terungkap padaku sejak lama, ketika kekuatan dari garis keturunan saya terbangkitkan.",
  ui_story_5084_50840502_28_dialog_content = "Sebuah ritual kuno untuk Kedatangan Kebenaran, di mana leluhur kita sepenuhnya mengkonsumsi darah korban untuk mendapatkan inspirasi ilahi.",
  ui_story_5084_50840502_29_dialog_content = "Tunggu... Apakah ini berarti Inisiator dimakan setiap kali Advent of Truth?!",
  ui_story_5084_50840502_30_dialog_content = "Tidak heran mereka tertawa seperti itu sebelumnya!!",
  ui_story_5084_50840502_31_dialog_content = "Apakah Victoria benar-benar dikorbankan seperti ini?!",
  ui_story_5084_50840502_32_dialog_content = "Apakah seseorang di sana...?",
  ui_story_5084_50840502_33_dialog_content = "Oh? Sepertinya kamu kedatangan tamu, Wilhelm.",
  ui_story_5084_50840502_34_dialog_content = "...",
  ui_story_5084_50840502_35_dialog_content = "Uh, PlayerName... Apa yang telah kamu lakukan? Lord Wilhelm tidak melihat kita, bukan?",
  ui_story_5084_50840502_36_dialog_content = "Maaf... Aku pasti terlalu bersemangat tadi...",
  ui_story_5084_50840502_37_dialog_content = "Tapi aku melihat beberapa hal yang sangat mengganggu di pikiran Wilhelm...",
  ui_story_5084_50840502_38_dialog_content = "Aku masih cukup khawatir tentang Victoria, jadi aku akan mencoba lagi!",
  ui_story_5084_50840502_39_option_content = "Mindlink—",
  ui_story_5084_50840502_40_dialog_content = "Bagaimana dengan ini?",
  ui_story_5084_50840502_41_dialog_content = "Bahkan setelah menawarkan keponakanmu sendiri, Lord of Truth tidak memberikanmu wahyu apa pun. Apakah kegagalanmu sendiri akhirnya membuatmu gila?",
  ui_story_5084_50840502_42_dialog_content = "Tidak masalah. Aku sudah lama bosan dengan permainanmu, Wilhelm.",
  ui_story_5084_50840502_43_dialog_content = "Bloody Bible kini milikku! Kebenaran ada dalam genggamanku!",
  ui_story_5084_50840502_44_dialog_content = "...! Apakah ini sebuah ramalan...? Kedatangan Truth... Malam ini...",
  ui_story_5084_50840502_45_dialog_content = "(Itu dia pria yang saya lihat di kuil sebelumnya! Mereka akan mengorbankan Victoria untuk Advent of Truth... Yang berarti kita kembali ke tahun 1915!)",
  ui_story_5084_50840502_46_dialog_content = "Masih tidak percaya padaku?",
  ui_story_5084_50840502_47_dialog_content = "... Apakah ini cara hidupku berakhir?",
  ui_story_5084_50840502_48_dialog_content = "Kamu masih gagal memahami kekuatan Varaki, namun kamu akan menghukum keluarga darah hingga mati karena kesialanmu sendiri.",
  ui_story_5084_50840502_49_dialog_content = "Anak muda selalu meremehkan dogma dari pendahulu mereka.",
  ui_story_5084_50840502_50_dialog_content = "Tapi, kamu sejak awal memang bukan pemimpin dari True Order.",
  ui_story_5084_50840502_51_dialog_content = "Heheh... Hahahaha...",
  ui_story_5084_50840502_52_dialog_content = "Kebenaran? Sungguh absurd...",
  ui_story_5084_50840502_53_dialog_content = "Apakah kamu menghabiskan begitu banyak waktu pada tangan kakakku sehingga kamu mewarisi sifat buruknya?",
  ui_story_5084_50840502_54_dialog_content = "Dia mengutukku dengan mempercayakan keluarga dan putrinya padaku... Dan sekarang Victoria, pemimpin sejati dari ordo, telah meninggalkan kita...",
  ui_story_5084_50840502_55_dialog_content = "Dia membiarkan dirinya tertipu oleh visi masa depan yang palsu, membiarkannya terdistorsi dan dimanipulasi untuk tujuan orang lain.",
  ui_story_5084_50840502_56_dialog_content = "Sebuah perasaan yang aku kenal terlalu baik...",
  ui_story_5084_50840502_57_dialog_content = "Aku pernah melakukan kesalahan itu sebelumnya. Apakah aku mampu melakukannya lagi?",
  ui_story_5084_50840502_58_dialog_content = "Apakah kamu benar-benar ingin menyelamatkan Victoria?",
  ui_story_5084_50840502_59_dialog_content = "Ya.",
  ui_story_5084_50840502_60_dialog_content = "Kamu ragu-ragu.",
  ui_story_5084_50840502_61_dialog_content = "Orang-orang yang ingin melihatnya mati adalah kepala keluarga lainnya. Sebagai putra kedua dari Varaki, kematianku tidak akan berarti apa-apa; apa yang mereka benar-benar takutkan adalah melihat Victoria naik ke tampuk kekuasaan.",
  ui_story_5084_50840502_62_dialog_content = "Jika ramalan itu benar...",
  ui_story_5084_50840502_63_dialog_content = "Kekuatan dalam garis darah Victoria terbangun cukup terlambat, dan dia tidak responsif terhadap Kebenaran yang saya sampaikan kepadanya.",
  ui_story_5084_50840502_64_dialog_content = "Jika aku mati, parasit-parasit itu tidak akan pernah membiarkannya pergi...",
  ui_story_5084_50840502_65_dialog_content = "Victoria... Victoria...",
  ui_story_5084_50840502_66_dialog_content = "(Huh? Apakah dia khawatir tentang Victoria?)",
  ui_story_5084_50840502_67_dialog_content = "Benar! Sebagai pemimpin True Order, aku adalah orang yang mendeklarasikan Inisiasi! Tapi...",
  ui_story_5084_50840502_68_dialog_content = "Dia bilang dia tidak berniat hadir di Advent of Truth malam ini... Di mana dia mungkin berada...?",
  ui_story_5084_50840502_69_dialog_content = "Itu berarti Victoria muncul di kuil pada saat yang sangat tidak tepat! Dia benar-benar dikorbankan!",
  ui_story_5084_50840502_70_dialog_content = "Siapa di sana? Tunjukkan dirimu...",
  ui_story_5084_50840502_71_dialog_content = "(Oh tidak, jangan lagi...!)",
  ui_story_5084_50840502_72_dialog_content = "Heheh, jadi kamu punya rencana darurat di pikiranmu?",
  ui_story_5084_50840502_73_dialog_content = "PlayerName! Apakah kamu melakukan sesuatu lagi?!",
  ui_story_5084_50840502_74_dialog_content = "Selesai sudah... Begitu dia menyebutkan pengorbanan Victoria, aku tidak bisa menahan diri...",
  ui_story_5084_50840502_75_dialog_content = "Mengorbankan Lady Victoria... Tunggu, itu malam ini? Apakah itu berarti hal yang sama persis akan terjadi?!",
  ui_story_5084_50840502_76_dialog_content = "Aku takut begitu... Meskipun Wilhelm tampaknya khawatir tentang Victoria, aku masih perlu tahu apa yang dia rencanakan untuk dia...",
  ui_story_5084_50840502_77_dialog_content = "Studi ini... Apakah salah satu peninggalan <color=#FFB400>Osten Varaki</color> masih ada di sini?",
  ui_story_5084_50840502_78_dialog_content = "Atau mungkin... Dia?",
  ui_story_5084_50840502_79_dialog_content = "Beritahu aku! Menawarkan Victoria sebagai korban... Apakah ini keinginanmu?",
  ui_story_5084_50840502_80_dialog_content = "\"Dia\"?",
  ui_story_5084_50840502_81_dialog_content = "Siapa yang bicara padamu barusan?! Katakan padaku!",
  ui_story_5084_50840502_82_dialog_content = "Tuan ku...!",
  ui_story_5084_50840502_83_dialog_content = "... Uraaagh! <size=45>Hancurkan cincin terkutuk ini!!!</size>",
  ui_story_5084_50840502_84_dialog_content = "Bunuh aku, Tuanku... Bebaskan aku dari penderitaanku!!!",
  ui_story_5084_50840502_85_dialog_content = "Lihatlah keadaanmu yang terdistorsi... Menyedihkan.",
  ui_story_5084_50840502_86_dialog_content = "Argh... Aaaaahhh!",
  ui_story_5084_50840502_87_dialog_content = "Ahahahaha—! Aku adalah pemimpin yang sah dari True Order! Aku!!!",
  ui_story_5084_50840502_88_dialog_content = "(Cincin itu kembali menyerang pikiran Wilhelm... Apa yang harus kulakukan?)",
  ui_story_5084_50840502_89_dialog_content = "Wilhelm, kau bodoh yang tak punya harapan. Seperti yang sudah kukatakan sebelumnya, kau harus mati agar bisa hidup.",
  ui_story_5084_50840502_90_dialog_content = "Aku tidak takut mati... Tapi Victoria... Bagaimana dengan dia?!?",
  ui_story_5084_50840502_91_dialog_content = "Lord of Truth...",
  ui_story_5084_50840502_92_dialog_content = "Beritahu aku apa yang akan terjadi pada Victoria setelah hari ini...!!!",
  ui_story_5084_50840502_93_dialog_content = "Dia telah benar-benar kehilangan kendali! Dia tidak akan bertahan jika ini terus berlanjut!",
  ui_story_5084_50840502_94_dialog_content = "Sepertinya kamu bisa membuat kontak dengan dia menggunakan kekuatanmu, PlayerName. Kenapa tidak mencoba itu?",
  ui_story_5084_50840502_95_dialog_content = "Tapi, jika saya melakukan itu, itu mungkin akan mempengaruhi masa lalu! Kita akan berada dalam masalah besar jika itu terjadi...",
  ui_story_5084_50840502_96_dialog_content = "Kamu percaya pada Lord of Truth, kan May? Apa yang bisa membuatmu merasa tenang dalam situasi seperti ini tanpa menimbulkan kecurigaan?",
  ui_story_5084_50840502_97_dialog_content = "Aku tidak tahu, sesuatu yang sederhana seperti \"May Semoga Truth memberkatimu,\" atau \"Ikuti petunjuknya,\" kira-kira begitu?",
  ui_story_5084_50840502_98_dialog_content = "Benarkah...? Sepertinya patut dicoba...",
  ui_story_5084_50840502_99_option_content = "Mindlink—",
  ui_story_5084_50840502_100_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840502_101_dialog_content = "...",
  ui_story_5084_50840502_102_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50840502_103_dialog_content = "M-May Semoga Truth memberkatimu...",
  ui_story_5084_50840502_104_dialog_content = "K-kamu... Siapa sebenarnya kamu...?",
  ui_story_5084_50840502_105_dialog_content = "(Sepertinya berhasil, tapi sebaiknya aku hati-hati untuk tidak mengatakan hal yang salah...)",
  ui_story_5084_50840502_106_dialog_content = "Maaf, tetapi saya tidak bisa lagi percaya pada tuhan yang memanipulasi hati orang-orang. Kebenaran di hati saya tidak akan menyesatkan saya.",
  ui_story_5084_50840502_107_dialog_content = "True Order tidak bisa terus ada seperti ini, setidaknya tidak di masa depan Victoria.",
  ui_story_5084_50840502_108_dialog_content = "Jika kamu juga percaya pada Lord of Truth, kamu akan mengerti kata-kataku.",
  ui_story_5084_50840502_109_dialog_content = "Untuk kamu muncul di hadapanku sekarang, pasti berarti kamu memiliki sesuatu untuk dikatakan padaku... Benar, 'kan?",
  ui_story_5084_50840502_110_dialog_content = "... Ikuti bimbingannya.",
  ui_story_5084_50840502_111_dialog_content = "... Jadi kamu percaya bahwa aku harus menerima kenyataan, dan membiarkan diriku dikonsumsi oleh kepala keluarga kita...",
  ui_story_5084_50840502_112_dialog_content = "Jadi Victoria bisa terus menanggung kutukan dari rakyat kita, dan pada akhirnya menemui ajalnya di tangan vampir itu?",
  ui_story_5084_50840502_113_dialog_content = "(Tidak, itu tidak benar... Bagaimana aku bisa memperburuk keadaan...?)",
  ui_story_5084_50840502_114_dialog_content = "... Tidak! Sama sekali tidak!",
  ui_story_5084_50840502_115_dialog_content = "Meski ditinggalkan oleh keluargaku, aku telah sampai sejauh ini, dan semua berkat Kebenaran dalam hatiku! Kebenaran itu tidak akan pernah menyesatkan aku!",
  ui_story_5084_50840502_116_dialog_content = "Inilah \"wahyu\" yang disebut-sebut itu yang telah membuat True Order jatuh begitu rendah...",
  ui_story_5084_50840502_117_dialog_content = "Aku harus... Menghilangkan kutukan ini.",
  ui_story_5084_50840502_118_dialog_content = "Tapi bagaimana...",
  ui_story_5084_50840502_119_dialog_content = "... Satu-satunya relik sakral yang belum tercemar oleh seorang pemimpin... Adalah <color=#FFB400>itu</color>.",
  ui_story_5084_50840502_120_dialog_content = "Bulan berdarah... Ketika tanaman merambatnya berubah menjadi bentuk hidup, seorang guardian akan menunggu tuan dari kripta di pintu masuknya.",
  ui_story_5084_50840502_121_dialog_content = "Tapi selain mengangkut peti mati leluhur kita masuk dan keluar dari makam... Satu-satunya cara untuk masuk adalah dengan <color=#FFB400>kunci</color>, atau dengan persetujuan dari kepala keluarga...",
  ui_story_5084_50840502_122_dialog_content = "Hah! Wilhelm, kau bajingan... Masih memikirkan aturan bahkan ketika kau akan dimakan? Kau pantas untuk ditertawakan...",
  ui_story_5084_50840502_123_dialog_content = "Meskipun Clavis menolak memberiku kunci, para Vinekeeper telah melayani Varaki selama beberapa generasi...",
  ui_story_5084_50840502_124_dialog_content = "Tentunya dia akan mengizinkan saya untuk masuk ke ruang bawah tanah sekarang setelah saya memperoleh pengetahuan ini?",
  ui_story_5084_50840502_125_dialog_content = "Aku harus masuk sebelum prosesi dimulai!",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>Fwoosh!</color>",
  ui_story_5084_50840502_127_dialog_content = "Bertahanlah, May!",
  ui_story_5084_50840502_128_dialog_content = "Kali ini kita mau ke mana?!",
  ui_story_5084_50840502_129_dialog_content = "Makam Varaki!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>Di pintu masuk toko penjahit di Varaki Town</color>",
  ui_story_5084_50840601_2_dialog_content = "May Truth memberkatimu, seorang penjahit yang terampil.",
  ui_story_5084_50840601_3_dialog_content = "Dan semoga Truth memberkatimu juga, tuan yang baik. Dengan penampilan yang begitu saleh, kamu pasti akan dipilih sebagai Inisiator tahun ini.",
  ui_story_5084_50840601_4_dialog_content = "Aku berdoa semoga begitu, sayangku. Aku harus pergi sekarang; sampai kita bertemu di jamuan malam ini. Jangan terlambat.",
  ui_story_5084_50840601_5_dialog_content = "Aku jamin aku tidak akan.",
  ui_story_5084_50840601_6_dialog_content = "Apa ini... Bagaimana kita bisa berakhir di sini?",
  ui_story_5084_50840601_7_dialog_content = "Apakah Anda di sini untuk jubah upacara, Tuan?",
  ui_story_5084_50840601_8_dialog_content = "Jubah seremonial...?",
  ui_story_5084_50840601_9_dialog_content = "Ah, kamu pasti pelanggan orang lain.",
  ui_story_5084_50840601_10_dialog_content = "Kamu harus tahu, keluarga kami yang merupakan penjahit telah berbisnis paling lama di sini di Varaki Town. Selama setiap Advent of Truth, toko kami juga menangani pesanan jubah terbanyak.",
  ui_story_5084_50840601_11_dialog_content = "Bahkan orang-orang yang tinggal di pinggiran kota kami akan datang untuk membeli jubah kami pada malam perayaan itu.",
  ui_story_5084_50840601_12_dialog_content = "Jadi, mengapa tidak memesan dari kami? Saya jamin harganya akan sesuai dengan keinginan Anda.",
  ui_story_5084_50840601_13_dialog_content = "...",
  ui_story_5084_50840601_14_dialog_content = "Lihat, teman! Bulan darah telah muncul.",
  ui_story_5084_50840601_15_dialog_content = "Bulan berdarah... Kedatangan Kebenaran adalah malam ini...",
  ui_story_5084_50840601_16_dialog_content = "Mentorku mengatakan dia akan memilihku sebagai Inisiator tahun ini, yang berarti aku harus berpakaian dengan penuh kesalehan untuk acara tersebut.",
  ui_story_5084_50840601_17_dialog_content = "Inisiat? Apakah saya mendengarnya dengan benar...?",
  ui_story_5084_50840601_18_dialog_content = "Tapi satu-satunya orang yang bisa mengumumkan Initiate adalah Lord Wilhelm Varaki! Mengapa dia memilihmu, dari semua orang?",
  ui_story_5084_50840601_19_dialog_content = "Ya, itu nama mentor saya. Kami bertemu di kripta keluarganya.",
  ui_story_5084_50840601_20_dialog_content = "Makam Varaki...?! Aku mengerti... Katakan padaku, bagaimana kamu bisa mendekati Truth begitu dekat?",
  ui_story_5084_50840601_21_dialog_content = "... Aku mengaku dosa-dosaku dan mencari penebusan setiap hari, namun setiap orang masih menghindariku. Setiap orang... Kecuali mentorku.",
  ui_story_5084_50840601_22_dialog_content = "Penantian... Kedatangan Truth... Dan bulan berdarah... Ya, aku rasa aku mengerti sekarang...",
  ui_story_5084_50840601_23_dialog_content = "Terima kasih telah memberikan pengetahuan tentang Truth ini kepada saya, Initiate yang terhormat...",
  ui_story_5084_50840601_24_dialog_content = "Aku telah menerima uang dari orang-orang yang beriman atas nama Kedatangan Truth... Dan jadi Truth telah menghindariku...",
  ui_story_5084_50840601_25_dialog_content = "Berbahagialah kamu, Inisiator... Berbahagialah kamu telah menunjukkan kesalahan jalan hidupku.",
  ui_story_5084_50840601_26_dialog_content = "Apakah Anda keberatan memberkati kami dengan kehadiran Anda sedikit lebih lama? Ibu saya, putri saya, dan saya akan merasa terhormat untuk membuatkan Anda setelan jubah dengan segera!",
  ui_story_5084_50840601_27_dialog_content = "Itu-Itu tidak perlu... Aku hanya lewat mencari mentorku.",
  ui_story_5084_50840601_28_dialog_content = "Ini bukan kebetulan, Tuan; The Truth pasti telah membimbing Anda ke sini hari ini! Mohon maafkan saya karena bersikap kasar tadi—",
  ui_story_5084_50840601_29_dialog_content = "Lagi, itu benar-benar tidak perlu...",
  ui_story_5084_50840601_30_dialog_content = "Ibu? Apa yang masih Anda lakukan di sini?! Pelanggan kita sudah lelah menunggu!",
  ui_story_5084_50840601_31_dialog_content = "Beritahu mereka kami akan mengantarkan jubah mereka gratis hari ini!",
  ui_story_5084_50840601_32_dialog_content = "Ha?",
  ui_story_5084_50840601_33_dialog_content = "Setelah itu, kita akan segera membuat setelan jubah untuk pemuda ini! Dia adalah Inisiat!",
  ui_story_5084_50840601_34_dialog_content = "Maksudmu sekarang?",
  ui_story_5084_50840601_35_dialog_content = "Ya, Sayang!",
  ui_story_5084_50840601_36_dialog_content = "Nenek tidak akan senang tentang ini...",
  ui_story_5084_50840601_37_dialog_content = "Lakukan saja seperti kataku, untuk saat ini, Anak Kecil. Saya akan menjelaskan semuanya kepada Nenekmu.",
  ui_story_5084_50840601_38_dialog_content = "Baiklah…",
  ui_story_5084_50840601_39_dialog_content = "Ah... Maafkan aku, Lord of Truth! Sepertinya aku telah membuat kesalahan lain lagi...",
  ui_story_5084_50840601_40_dialog_content = "Syukurlah... Saya masih punya sedikit uang... Saya hanya berdoa semoga itu bisa menutupi sebagian kerugian mereka hari ini...",
  ui_story_5084_50840601_41_dialog_content = "Tapi aku tidak boleh membebani penjahit seperti ini atau keluarganya lagi...",
  ui_story_5084_50840601_42_dialog_content = "Wilhelm.",
  ui_story_5084_50840601_43_dialog_content = "Siapa yang berani menyebut namaku dan menghalangi jalanku?! Menyingkir! Kedatangan Kebenaran membutuhkan kehadiranku!",
  ui_story_5084_50840601_44_dialog_content = "Kamu telah kehilangan pandangan tentang Truth, dan pandanganmu malah kabur oleh realitas.",
  ui_story_5084_50840601_45_dialog_content = "Tanggung jawab ini terlalu besar untuk kamu tanggung. Izinkan aku menggantikan tempatmu...",
  ui_story_5084_50840601_46_dialog_content = "Apakah kamu dikirim oleh kepala keluarga lainnya? Datanglah padaku!",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>Lilin berkedip dan sekeliling mereka berubah sekali lagi—Tiba-tiba, sebuah makam dengan asal-usul yang jelas kuno muncul di depan mereka.</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>Angin dingin meniup debu dan puing yang telah menetap di tanaman merambatnya selama berabad-abad.</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>Dengan terkejut, sulur mulai meronta dan membuka diri, membebaskan orang yang terperangkap di dalamnya...</color>",
  ui_story_5084_50840601_50_dialog_content = "Kita sudah sampai... Tunggu, apakah itu...?",
  ui_story_5084_50840601_51_dialog_content = "A-Apa yang kulakukan di sini...?",
  ui_story_5084_50840601_52_dialog_content = "Apakah orang itu yang saya temui sebelumnya? Dia pasti telah menggunakan semacam trik untuk membawa saya ke sini... Dan sekarang dia telah mengambil tempat saya dalam upacara...",
  ui_story_5084_50840601_53_dialog_content = "Bulan berdarah telah tersembunyi... Jam berapa sekarang? Apakah saya telah melewatkan Advent of Truth?",
  ui_story_5084_50840601_54_dialog_content = "Kamu telah diberkati dengan kebijaksanaan Truth.",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>Tanaman merambat di pintu masuk kripta bertemu dan membentuk sosok pria berwajah pucat dengan mata yang tumpul dan tak bersemangat.</color>",
  ui_story_5084_50840601_56_dialog_content = "Tuanku, makam leluhur Anda terbuka untuk Anda.",
  ui_story_5084_50840601_57_dialog_content = "Tapi... Bagaimana?",
  ui_story_5084_50840601_58_dialog_content = "<color=#FFB400>Kunci</color> itu di dekat sini... Aku bisa merasakan nyala apinya.",
  ui_story_5084_50840601_59_dialog_content = "Apa nyala api? Satu-satunya api yang saya lihat di sekitar sini... Ada di kandil di tanganmu.",
  ui_story_5084_50840601_60_dialog_content = "Bisakah semua ini... Karena aku? Pertama aku membimbingnya kesini dengan suaraku, dan sekarang aku telah membuka pintu makam untuknya?",
  ui_story_5084_50840601_61_dialog_content = "Apa sebenarnya yang telah saya ubah di sini?",
  ui_story_5084_50840601_62_dialog_content = "Tunggu, aku tidak...",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>Tanpa menunggu Wilhelm selesai berbicara, Vinekeeper kembali ke tanah yang ditumbuhi lumut dan melanjutkan penjagaannya dalam diam.</color>",
  ui_story_5084_50840601_64_dialog_content = "Crypt sudah terbuka, dan Guardian-nya telah memberi saya izin masuk...",
  ui_story_5084_50840601_65_dialog_content = "Namun aku belum melakukan apa pun. Apakah ini ulah \"The Truth\"?",
  ui_story_5084_50840601_66_dialog_content = "Takdir telah membimbingku ke sini, yang berarti Lord of Truth menginginkan aku untuk menjalankan kehendak ilahinya.",
  ui_story_5084_50840601_67_dialog_content = "Aku harus masuk ke dalam.",
  ui_story_5084_50840601_68_dialog_content = "Apa yang dia lakukan sekarang...? Ayo, May!",
  ui_story_5084_50840601_69_dialog_content = "Mungkin leluhur Varaki bisa memberikan petunjuk lebih banyak...",
  ui_story_5084_50840601_70_dialog_content = "Ke-Kemana peti mati leluhur?! Seharusnya sudah dikembalikan setelah upacara selesai...",
  ui_story_5084_50840601_71_dialog_content = "Siapa yang berani mengganggu tempat peristirahatan terakhir Varaki?! Tidak...",
  ui_story_5084_50840601_72_dialog_content = "Peti mati leluhur, dan bahkan Bloody Bible... Keduanya hilang...",
  ui_story_5084_50840601_73_dialog_content = "Apakah kepala keluarga sudah mulai mewujudkan rencananya?",
  ui_story_5084_50840601_74_dialog_content = "Victoria... Dia sedang dalam bahaya!",
  ui_story_5084_50840601_75_dialog_content = "Pria Musim Dingin! Bawa aku kembali ke kuil!",
  ui_story_5084_50840601_76_dialog_content = "Sebuah kuda hitam yang tampak keren... Tidak, tunggu, kita perlu mengejarnya!",
  ui_story_5084_50840601_77_dialog_content = "Murid-murid yang sudah mati? Kenapa mereka berkeliaran di sini?!",
  ui_story_5084_50840601_78_dialog_content = "Lebih banyak mayat... Apa yang sebenarnya terjadi di kota ini?!",
  ui_story_5084_50840601_79_dialog_content = "Makhluk kotor! Beraninya kamu menyerang tempat ini dan menyakiti orang-orang yang beriman!",
  ui_story_5084_50840601_80_dialog_content = "Makhluk sengsara ini tidak memiliki pikiran sendiri. Tuan mereka pasti telah membiarkan mereka lepas di kota.",
  ui_story_5084_50840601_81_dialog_content = "Aku akan membersihkan dunia dari keberadaan mereka!",
  ui_story_5084_50840602_1_dialog_content = "Ah, Lord Wilhelm Varaki... Figur yang kuat dan menawan!",
  ui_story_5084_50840602_2_dialog_content = "Melalui kebijaksanaannya, aku diberikan sekilas melalui pintu Truth.",
  ui_story_5084_50840602_3_dialog_content = "Sepertinya orang-orang yang beriman sama sekali tidak sadar akan ancaman monster yang mengancam kota...",
  ui_story_5084_50840602_4_dialog_content = "Upacara Advent of Truth telah berakhir, tetapi kepala keluarga seharusnya masih berada di kuil...",
  ui_story_5084_50840602_5_dialog_content = "Huff, huff... K-Kita akhirnya... Bisa menyusul...",
  ui_story_5084_50840602_6_dialog_content = "Lihat, May! Itu kedua murid yang kamu coba berdakwah sebelumnya! Kita kembali ke waktu ini lagi!",
  ui_story_5084_50840602_7_dialog_content = "Yang berarti kita seharusnya berada di kuil sekarang juga!",
  ui_story_5084_50840602_8_dialog_content = "Setelah murid-murid pergi, saya pikir upacara telah selesai. Saya tidak berharap menemukan Anda menunggu saya di sini.",
  ui_story_5084_50840602_9_dialog_content = "Nails! Apa yang kamu lakukan di sini?!",
  ui_story_5084_50840602_10_dialog_content = "Dan pakaian apa sebenarnya yang kamu kenakan...?",
  ui_story_5084_50840602_11_dialog_content = "Seorang penjahit yang baik hati dan keluarganya membuat jubah ini khusus untuk saya. Saya sangat berterima kasih atas kebaikan hati mereka.",
  ui_story_5084_50840602_12_dialog_content = "Saya juga berterima kasih kepada mentor saya karena telah membiarkan saya berada di sini hari ini.",
  ui_story_5084_50840602_13_dialog_content = "Kamu...",
  ui_story_5084_50840602_14_dialog_content = "Hah? Tentang apa kamu bicara, Nails?",
  ui_story_5084_50840602_15_dialog_content = "Sejujurnya, aku juga tidak benar-benar mengerti apa yang dia katakan setengah waktu...",
  ui_story_5084_50840602_16_dialog_content = "Ini adalah kehormatan besar bagi saya untuk menjadi korban dalam Perayaan Kedatangan Truth ini.",
  ui_story_5084_50840602_17_dialog_content = "Maafkan aku, tetapi aku sama sekali tidak tahu apa yang kamu bicarakan.",
  ui_story_5084_50840602_18_dialog_content = "Porfirio! Di mana Bloody Bible?!",
  ui_story_5084_50840602_19_dialog_content = "Aku juga memiliki pertanyaan, Wilhelm. Apa itu angin hitam tadi? Dan di mana Victoria pergi?!",
  ui_story_5084_50840602_20_dialog_content = "Victoria?",
  ui_story_5084_50840602_21_dialog_content = "Even after offering your own niece, the Lord of Truth did not grace you with any revelations. Has your own failure finally driven you mad?",
  ui_story_5084_50840602_22_dialog_content = "It matters not. I've long since grown tired of your games, Wilhelm.",
  ui_story_5084_50840602_23_dialog_content = "The Bloody Bible is mine now! The Truth is within my reach!",
  ui_story_5084_50840602_24_dialog_content = "Namun... Sekarang ritual tahun ini telah selesai, saya percaya kita memiliki sesuatu untuk dibicarakan.",
  ui_story_5084_50840602_25_dialog_content = "Persis seperti yang kulihat dalam ramalan... Heheh—Tidak ada lagi yang perlu dibicarakan. Aku tahu kau berniat menyerangku, Porfirio!",
  ui_story_5084_50840602_26_dialog_content = "Tidak ada gunanya berpura-pura tidak tahu; Aku sudah membersihkan kota dari pelayanmu, yang kau lepaskan pada orang-orang yang tidak bersalah dan beriman!",
  ui_story_5084_50840602_27_dialog_content = "Jadi, akhirnya sampai di sini...",
  ui_story_5084_50840602_28_dialog_content = "Tampaknya Wilhelm Varaki tidak berniat untuk menyerah kepada kita... Truth masih memiliki banyak hal untuk diceritakan kepada saya, jadi saya harus mengucapkan selamat tinggal kepada kalian berdua.",
  ui_story_5084_50840602_29_dialog_content = "Bukan langkah lain, Porfirio!",
  ui_story_5084_50840602_30_dialog_content = "Tidak ada gunanya melawan, Wilhelm. Dengan Bloody Bible di tangan saya, takdir kini berpihak pada saya...",
  ui_story_5084_50840602_31_dialog_content = "Ini waktunya bekerja, teman lama.",
  ui_story_5084_50840602_32_dialog_content = "Apa yang kamu rencanakan untuk mentor saya? Saya adalah Inisiat, bukan dia.",
  ui_story_5084_50840602_33_dialog_content = "Dan dari mana asalmu, orang asing?",
  ui_story_5084_50840602_34_dialog_content = "Bahkan pengikut Wilhelm pun tidak akan terhindar.",
  ui_story_5084_50840602_35_dialog_content = "Sebagai pemimpin True Order, saya tidak akan membiarkan kamu menyakiti lebih banyak lagi orang-orang yang setia!",
  ui_story_5084_50840602_36_dialog_content = "Kamu harus khawatir tentang diri sendiri dulu, bodoh! Hahahaha!",
  ui_story_5084_50840602_37_dialog_content = "Wilhelm...!",
  ui_story_5084_50840602_38_dialog_content = "Tuanku, berikan aku rasa sakitmu dan izinkan aku menderita di tempatmu. Telanlah, buanglah, dan biarkan Truth menang atas kejahatan...",
  ui_story_5084_50840602_39_dialog_content = "Tidak, Pak Nails! Kamu harus lari—",
  ui_story_5084_50840602_40_dialog_content = "Berhenti, May! Kita tidak diperbolehkan untuk mengganggu... Ingat apa yang Sikare katakan kepada kita!",
  ui_story_5084_50840602_41_dialog_content = "Ini semua salah ku. Semua ini tidak akan terjadi jika saya hanya diam... Kita perlu memikirkan cara lain untuk membantu mereka. Kita masih memiliki lilin, jadi pasti ada sesuatu yang bisa kita lakukan.",
  ui_story_5084_50840602_42_dialog_content = "Hmph, sungguh mengejutkan. Tulangmu tampaknya sekuat imanmu.",
  ui_story_5084_50840602_43_dialog_content = "Matilah!",
  ui_story_5084_50840602_44_dialog_content = "Tuhan Kebenaran, ritualmu sangat kejam tak tertahankan. Bisakah pengikutmu benar-benar bertahan? Jika ya, bagaimana mereka bisa bertahan dari rasa sakit yang begitu hebat?",
  ui_story_5084_50840602_45_dialog_content = "Aku akan menahannya! Aku akan menelan penderitaan ini dan membersihkan tubuhku dari dosa-dosanya. Aku akan menerima kutukan rasa sakit ini dan membakar luka di jiwaku—",
  ui_story_5084_50840602_46_dialog_content = "Izinkan saya menanggung rasa sakit ini sendirian, sehingga tidak ada orang lain yang harus merasakannya! Datang dan hapus dosa-dosa saya melalui penderitaan!",
  ui_story_5084_50840602_47_dialog_content = "Sebuah kehidupan penuh penderitaan sebagai ganti penebusan mereka!",
  ui_story_5084_50840602_48_dialog_content = "(Dengan keadaan seperti ini, Nails benar-benar akan mati di tangan mereka! Ayo, lilin... Bawa aku ke tempat di mana aku bisa membuat perbedaan...!)",
  ui_story_5084_50840602_49_dialog_content = "Bodoh kau!",
  ui_story_5084_50840602_50_dialog_content = "Ini bukan ritual, dan mereka tidak membantu kamu membersihkan jiwa! Tidak bisakah kamu melihat bahwa mereka mencoba membunuhmu?!",
  ui_story_5084_50840602_51_dialog_content = "Apakah Anda menganggap diri Anda seorang pertapa? Jika ya, Anda harus bertahan dan mengabdikan sisa hidup Anda untuk mencari Kebenaran!",
  ui_story_5084_50840602_52_dialog_content = "Tuanku?",
  ui_story_5084_50840602_53_dialog_content = "Hiduplah, bodoh!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>Wilhelm meraih Nails dan melemparkannya dengan kekuatan yang mengejutkan. Dia menabrak pintu kuil, melemparkannya terbuka lebar dan membiarkan angin hitam masuk.</color>",
  ui_story_5084_50840602_55_dialog_content = "Ah! Lilinnya padam!",
  ui_story_5084_50840602_56_dialog_content = "Wilhelm Varaki tidak akan dipaksa berlutut begitu saja! Sekarang apa lagi yang kau siapkan untukku?!",
  ui_story_5084_50840602_57_dialog_content = "Kalian setan-setan pengkhianat akan merasakan pedangku sebelum malam tiba!",
  ui_story_5084_50840602_58_dialog_content = "Bangkitlah, <color=#FF0000>Crimson Stream</color>! Pedang iblis ku, yang meminum darahku sebagai ganti memotong musuh-musuhku!",
  ui_story_5084_50840602_59_dialog_content = "Apa yang terjadi? Apakah mereka akan bertarung...?",
  ui_story_5084_50840602_60_dialog_content = "Aku tidak tahu! Aku tidak bisa melihat apa-apa!",
  ui_story_5084_50840602_61_dialog_content = "Dunia mulai bergeser di sekitar kita lagi, tapi aku harus melihat ini sampai akhir! Aku tidak bisa membiarkan diriku... Diteleportasi pergi—",
  ui_story_5084_50840602_62_dialog_content = "Berpeganganlah padaku dan pergilah sejauh yang kamu bisa, May!",
  ui_story_5084_50840602_63_dialog_content = "Sial, aku tidak bisa melihat apa-apa di sini.",
  ui_story_5084_50840602_64_dialog_content = "Meski begitu, dia tidak akan bertahan lama sendirian.",
  ui_story_5084_50840602_65_dialog_content = "Ah!",
  ui_story_5084_50840602_66_dialog_content = "Siapa di antara kalian yang akan menjadi korban berikutnya?",
  ui_story_5084_50840602_67_dialog_content = "Datang dan berdiri di sisiku, Clavis! Kita bisa mengalahkan mereka bersama-sama!",
  ui_story_5084_50840602_68_dialog_content = "...",
  ui_story_5084_50840602_69_dialog_content = "Tidak ada gunanya, Wilhelm. Bahkan jika kau memenggal kepalaku, aku tak akan mati.",
  ui_story_5084_50840602_70_dialog_content = "Lalu aku akan terus memotongmu sampai kau tak bisa tahan rasa sakit lagi!",
  ui_story_5084_50840602_71_dialog_content = "Luar biasa... Meski dia bertarung melawan begitu banyak orang dalam kegelapan... Dia sama sekali tidak dalam posisi yang merugikan.",
  ui_story_5084_50840602_72_dialog_content = "Menyedihkan... Apakah kamu benar-benar mencoba untuk membunuhnya?",
  ui_story_5084_50840602_73_dialog_content = "Lebih mudah diucapkan daripada dilakukan...",
  ui_story_5084_50840602_74_dialog_content = "Masih mengandalkan orang lain, Porfirio? Akhirmu sudah dekat, dan tidak ada yang akan menyelamatkanmu dari itu!",
  ui_story_5084_50840602_75_dialog_content = "Kamu ingat kesepakatan kita... Bukan?",
  ui_story_5084_50840602_76_dialog_content = "...",
  ui_story_5084_50840602_77_dialog_content = "<size=45>Ah-!!!</size>",
  ui_story_5084_50840602_78_dialog_content = "Apa yang terjadi? Aku tidak bisa merasakan napasnya lagi! Apakah dia...",
  ui_story_5084_50840602_79_dialog_content = "Tetap bertahan! Kita... Kita akan segera dipindahkan ke tempat lain!",
  ui_story_5084_50840602_80_dialog_content = "Kenapa... Kenapa harus seperti ini?",
  ui_story_5084_50840602_81_dialog_content = "(Jika dia benar-benar mati... Apa yang akan terjadi pada Victoria?)",
  ui_story_5084_50840602_82_dialog_content = "Hei, PlayerName? Lord Wilhelm tampaknya bukan pembunuh berdarah dingin sama sekali, bukan? Apakah kamu benar-benar berpikir dia mengorbankan Lady... Victoria...?",
  ui_story_5084_50840602_83_dialog_content = "Aku juga ragu sekarang... Sejak lilin pertama kali memindahkan kita, Wilhelm yang kita lihat sama sekali tidak seperti Wilhelm yang kita lihat di upacara Advent of Truth...",
  ui_story_5084_50840602_84_dialog_content = "Apakah kata-kataku benar-benar menyebabkan semua perubahan ini terjadi...?",
  ui_story_5084_50840602_85_dialog_content = "Atau apakah ada sesuatu yang lain yang terjadi di antara Wilhelms yang telah kita lihat...?",
  ui_story_5084_50840602_86_dialog_content = "Aku bertanya-tanya di mana Lady Victoria sekarang...",
  ui_story_5084_50840602_87_dialog_content = "Selama upacara, Victoria menyebutkan sesuatu tentang Wilhelm yang hilang. Mungkin dia mencoba mencari jawaban di balik hilangnya dia?",
  ui_story_5084_50840602_88_dialog_content = "Sesuatu memberitahu saya bahwa upacara pengorbanan ini tidak sesederhana yang tampaknya... Jika dia bersedia mengunjungi kembali semua ini, itu berarti dia sedang mencari sesuatu.",
  ui_story_5084_50840602_89_dialog_content = "Sepertinya dia dan Wilhelm salah paham satu sama lain untuk waktu yang lama... Mereka masih memiliki lebih banyak hal untuk diceritakan satu sama lain.",
  ui_story_5084_50840700_1_dialog_content = "Wow, lihat semua lilin dan bunga ini, PlayerName! Tunggu... Apakah itu peti mati?!",
  ui_story_5084_50840700_2_dialog_content = "Sepertinya begitu…",
  ui_story_5084_50840700_3_dialog_content = "Bertanya-tanya di mana kita sekarang?",
  ui_story_5084_50840700_4_dialog_content = "Di luar juga gelap dan suram. Biarkan aku melihat...",
  ui_story_5084_50840700_5_dialog_content = "Kita berada di sebuah kastil kuno yang menghadap tebing! Siapa yang akan membangun rumah mereka di tempat seperti ini...?",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>Tak-tuk, tak-tuk—</color>",
  ui_story_5084_50840700_7_dialog_content = "Ah—Ini Lady Victoria!",
  ui_story_5084_50840700_8_dialog_content = "Tapi bagaimana...? Apakah karena aku baru saja memikirkannya?",
  ui_story_5084_50840700_9_dialog_content = "Tunggu, ada orang lain.",
  ui_story_5084_50840700_10_dialog_content = "Jadi kamu juga datang mencari Wilhelm?",
  ui_story_5084_50840700_11_dialog_content = "Selain keluarga, tampaknya hanya musuhnya saja yang datang ke rumahnya.",
  ui_story_5084_50840700_12_dialog_content = "Apa Anda tahu di mana dia?",
  ui_story_5084_50840700_13_dialog_content = "Sayangnya, saya tidak tahu. Dia tidak meninggalkan petunjuk apa pun tentang keberadaannya sebelum dia menghilang.",
  ui_story_5084_50840700_14_dialog_content = "Sungguh malu. Saya pikir dia setidaknya akan memiliki satu atau dua orang kepercayaan.",
  ui_story_5084_50840700_15_dialog_content = "Ya, kita pernah sebegitu dekatnya.",
  ui_story_5084_50840700_16_dialog_content = "Kalau saja Wilhelm tidak begitu ceroboh... Semuanya bisa tetap seperti itu.",
  ui_story_5084_50840700_17_dialog_content = "Kamu tidak pernah benar-benar mengerti pamanmu... Benarkah, Victoria?",
  ui_story_5084_50840700_18_dialog_content = "Saya tidak tertarik untuk mengenal orang seperti dia, apalagi memahaminya.",
  ui_story_5084_50840700_19_dialog_content = "Sebelum ayahmu menjadi pemimpin True Order, pamanmu Wilhelm lebih menginginkan peran itu daripada apa pun.",
  ui_story_5084_50840700_20_dialog_content = "Dibutakan oleh prospek kekayaan dan kemuliaan, dia dengan semangat mengejar keyakinan paling radikal dan mengajukannya sebagai Kebenaran.",
  ui_story_5084_50840700_21_dialog_content = "Karena hal ini, dia berulang kali kehilangan kendali setiap kali mencoba mewarisi kekuatan leluhur kami... Meski dia sudah dianggap sebagai orang buangan, dia menolak untuk menerima kekalahan.",
  ui_story_5084_50840700_22_dialog_content = "Penolakan itu, pada gilirannya, menjadikannya boneka dari ambisi orang lain, yang pada akhirnya mengakibatkan pengusirannya dari keluarga.",
  ui_story_5084_50840700_23_dialog_content = "... Aku tak peduli untuk mengetahui ceritanya.",
  ui_story_5084_50840700_24_dialog_content = "Sebenarnya, saya cukup puas untuk bebas dari kendalinya.",
  ui_story_5084_50840700_25_dialog_content = "Selama perjalanan ku, Lord of Truth telah menunjukkan sesuatu kepadaku... Itulah sebabnya aku datang untuk mengucapkan selamat tinggal.",
  ui_story_5084_50840700_26_dialog_content = "Aku akan pergi ke tempat yang telah ditunjukkan kepada ku, di mana aku akan menunggu kedatangan mulia Lord of Truth.",
  ui_story_5084_50840700_27_dialog_content = "Kamu adalah penerus garis keturunan Varaki. Kamu bebas membuat keputusan sesuai yang kamu anggap tepat.",
  ui_story_5084_50840700_28_dialog_content = "Tapi sebelum saya pergi, bolehkah saya bertanya tentang sesuatu? Hari itu, saat kami mengunjungi rumahmu... Apa yang ingin Wilhelm pinjam darimu?",
  ui_story_5084_50840700_29_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840700_30_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840700_31_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840700_32_dialog_content = "...! Ini adalah kunci untuk semua pintu... Tapi mereka yang membakar dengan ambisi hanya akan tertelan olehnya.",
  ui_story_5084_50840700_33_dialog_content = "... Hati-hati, Victoria Varaki. Kamu membawa beban yang besar dan berat, dan jalan menuju Truth panjang dan berat.",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>Victoria mengawasi Clavis pergi. Setelah dia tidak terlihat, dia berbalik dan masuk ke kamar Wilhelm.</color>",
  ui_story_5084_50840700_35_dialog_content = "Ke mana kamu pergi, pria yang tak bisa dimengerti?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>Dia mengamati sekeliling ruangan sebelum akhirnya membuka peti mati mewah Wilhelm dan berbaring di dalamnya.</color>",
  ui_story_5084_50840700_37_dialog_content = "Jika aku melihat hal-hal seperti yang pernah dilakukan orang tuaku... Akankah aku bisa memahami ambisimu?",
  ui_story_5084_50840700_38_dialog_content = "(Perasaan ini... Dia sedang mencoba mengingat sesuatu...)",
  ui_story_5084_50840700_39_dialog_content = "Kami berkumpul di sini hari ini untuk menghormati kepala Varaki Family saat kami meletakkan tubuh mereka untuk beristirahat.",
  ui_story_5084_50840700_40_dialog_content = "Saat mereka mengikuti jejak leluhur noble kami, mereka ditinggalkan oleh putri tercinta mereka—Victoria Varaki.",
  ui_story_5084_50840700_41_dialog_content = "Datanglah, anak kecil; letakkan cincin ini di makam ayahmu dengan tanganmu sendiri. Ini adalah simbol kehormatannya, dan harus diperlakukan demikian pada saat ini.",
  ui_story_5084_50840700_42_dialog_content = "Ayah... Ibu...",
  ui_story_5084_50840700_43_dialog_content = "Ambillah waktumu, sayangku. Kami mengerti bahwa kamu masih dilanda oleh kesedihan dan kebingungan.",
  ui_story_5084_50840700_44_dialog_content = "Tapi jangan takut, gadisku, karena kami akan tetap di sisimu saat kamu mengarungi jam tergelap ini—Ah, tapi di mana sopanku? Namaku David Porfirio.",
  ui_story_5084_50840700_45_dialog_content = "Ayahmu pernah membantuku menaklukkan kekacauan dalam darahku, dan memulihkan Sanity yang sangat berharga bagi ku.",
  ui_story_5084_50840700_46_dialog_content = "Dan saya adalah Clavis Ibrahim. Saya tidak pernah melupakan kebaikan yang ditunjukkan kepada saya oleh Keluarga Varaki.",
  ui_story_5084_50840700_47_dialog_content = "Jika suatu saat kamu membutuhkan bantuan dengan apapun, kamu hanya perlu memintanya.",
  ui_story_5084_50840700_48_dialog_content = "Lady Varaki... Kamu tidak perlu tahu namaku. Aku hanyalah seorang pelayan rendah hati, jadi tolong panggil aku seperti itu.",
  ui_story_5084_50840700_49_dialog_content = "Ayahku... Apa yang dia panggil kamu?",
  ui_story_5084_50840700_50_dialog_content = "Graves, gadisku...",
  ui_story_5084_50840700_51_dialog_content = "Berjalannya waktu bisa sangat kejam, sampai-sampai aku hampir lupa namaku... Setiap orang memanggilku <color=#FFB400>Adder</color>, jadi silakan lakukan hal yang sama.",
  ui_story_5084_50840700_52_dialog_content = "Ritual telah selesai, dan para pemimpin Keluarga Varaki kini telah diberikan istirahat terakhir. Sekarang saatnya bagi kita untuk membahas masa depan.",
  ui_story_5084_50840700_53_dialog_content = "Kamu masih cukup muda, Lady Victoria. Aku khawatir kamu belum siap untuk menanggung kekuatan cincin ini.",
  ui_story_5084_50840700_54_dialog_content = "Dengan senang hati aku akan mengawasinya untukmu—Jangan takut, karena ini hanyalah cincin biasa di tangan seseorang yang bukan bagian dari Varaki.",
  ui_story_5084_50840700_55_dialog_content = "Begitu? Lalu kenapa kamu bersikeras menyimpannya untuk dirimu sendiri, Porfirio?",
  ui_story_5084_50840700_56_dialog_content = "Wilhelm Varaki?!",
  ui_story_5084_50840700_57_dialog_content = "Hmph, jangan lupa bahwa masih ada anggota Varaki lainnya yang hidup, dan hanya Varaki yang bisa menjadi pemimpin True Order.",
  ui_story_5084_50840700_58_dialog_content = "...",
  ui_story_5084_50840700_59_dialog_content = "Berani-beraninya kamu bicara hal gila di depan Lady Victoria! Apakah kamu lupa bahwa kamu telah diusir dari Keluarga Varaki?!",
  ui_story_5084_50840700_60_dialog_content = "Hah! Saksikan aku mewarisi kebijaksanaan dan kekuatan dari leluhur kita!",
  ui_story_5084_50840700_61_dialog_content = "Argh…",
  ui_story_5084_50840700_62_dialog_content = "Hahahaha! Kenapa tampang kecewa begitu, Porfirio? Apakah prospek melihat Varaki lainnya memakai cincin itu begitu menyiksa dirimu?",
  ui_story_5084_50840700_63_dialog_content = "Lihatlah! Aku, Wilhelm Varaki, kini menara di atas kalian semua!",
  ui_story_5084_50840700_64_dialog_content = "Leluhur kita telah menganggap saya layak menjadi kepala baru dari Keluarga Varaki!",
  ui_story_5084_50840700_65_dialog_content = "Wilhelm... Sepertinya ambisimu belum padam.",
  ui_story_5084_50840700_66_dialog_content = "Heh... Hahahaha! Sayang Victoria, sepertinya pamanmu tidak mau memberikan apa yang seharusnya menjadi milikmu.",
  ui_story_5084_50840700_67_dialog_content = "Kami tidak memiliki hak untuk ikut campur dalam urusan Varaki. Mari kita pergi.",
  ui_story_5084_50840700_68_dialog_content = "Wilhelm Varaki... Paman saya...",
  ui_story_5084_50840700_69_dialog_content = "Kemana kamu ingin pergi?",
  ui_story_5084_50840700_70_dialog_content = "Tentu saja, saya ingin meninggalkan kota ini dan pergi ke tempat yang telah saya warisi secara sah.",
  ui_story_5084_50840700_71_dialog_content = "Victoria Varaki... Mulai hari ini, aku akan menjadi walimu. Selama aku adalah kepala keluarga, kamu harus melakukan persis seperti yang aku katakan.",
  ui_story_5084_50840700_72_dialog_content = "... Cincin itu milik ayahku, yang berarti seharusnya sekarang menjadi milikku. Ketika Kebenaran berbicara padaku dan membangkitkan kekuatanku, aku akan mengambilnya kembali.",
  ui_story_5084_50840700_73_dialog_content = "Sesuai keinginanmu. Tapi untuk saat ini, itu tetap di tangan saya.",
  ui_story_5084_50840700_74_dialog_content = "The honor of hearing The Truth... I dearly wish to hear the thoughts of one as precocious as you, Victoria Varaki. What, in your definition, is The Truth?",
  ui_story_5084_50840700_75_dialog_content = "The Truth... is knowledge.",
  ui_story_5084_50840700_76_dialog_content = "Humph, Victoria Varaki... Though we share the same bloodline, in terms of strength, wisdom, capability, and even beauty... I stand far above you.",
  ui_story_5084_50840700_77_dialog_content = "So what makes you think this ring is rightfully yours?",
  ui_story_5084_50840700_78_dialog_content = "I am a true Varaki, and the leader of the True Order!",
  ui_story_5084_50840700_79_dialog_content = "As for you... You must first demonstrate that you are worthy of our family name. Do not disappoint me.",
  ui_story_5084_50840700_80_dialog_content = "(Wilhelm mengatakan hal-hal yang mengerikan, dan kepada seorang anak yang baru saja kehilangan orang tuanya, tidak kurang... Dia tidak serius, bukan?)",
  ui_story_5084_50840700_81_dialog_content = "(Lagi pula, anak kecil itu masih Victoria... Ini sangat aneh! Wilhelm yang telah kita lihat tidak hampir seperti ini...)",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>Sebuah kilat menyambar melintasi langit di luar saat Victoria muda membuka peti mati orang tuanya dan merangkak ke dalam.</color>",
  ui_story_5084_50840700_83_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_84_dialog_content = "Berikan aku bimbinganmu... Katakan apa yang harus kulakukan...",
  ui_story_5084_50840700_85_dialog_content = "Apakah aku... Di rumah? Tapi bagaimana?",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>Kresek, kresek-</color>",
  ui_story_5084_50840700_87_dialog_content = "Siapa yang berani mengganggu rumah Varaki—",
  ui_story_5084_50840700_88_dialog_content = "... Apa yang kamu lakukan di sini? Dan di mana hambaku?",
  ui_story_5084_50840700_89_dialog_content = "Hilang. Mulai saat ini, waktu akan menjadi pelayan abadi kita.",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>Wilhelm Varaki, pria yang tiba-tiba menerobos masuk ke Victoria, ada di sana untuk tinggal dan mengawasinya sebagai pamannya.</color>",
  ui_story_5084_50840700_91_dialog_content = "Sayangku Victoria, penderitaanmu sangat membebani hati kami, dan benar-benar begitu... Tapi kami tidak berdaya untuk mengubahnya. Mohon maafkan kami, anak kecil.",
  ui_story_5084_50840700_92_dialog_content = "Selama Wilhelm menjadi kepala Varaki, kita harus menaatinya. Sebenarnya, dialah yang menjaga kita tetap di jarak arm's length...",
  ui_story_5084_50840700_93_dialog_content = "Berharap tidak ada yang salah, saya bergegas ke sini secepat mungkin... Saya lega melihat bahwa Anda memang baik-baik saja.",
  ui_story_5084_50840700_94_dialog_content = "Dia hanya berhati-hati terhadapku. Dia takut bahwa aku akan bersekongkol denganmu dan yang lainnya untuk menjatuhkannya.",
  ui_story_5084_50840700_95_dialog_content = "Ya, ini adalah apa yang ditakuti Wilhelm... Karena dia tahu bahwa ayahmu adalah pemimpin yang jauh lebih mampu. Dia tidak lebih dari seorang buangan dan oportunis.",
  ui_story_5084_50840700_96_dialog_content = "Lady Victoria, saya harus bertanya... Bakat Anda seharusnya sama mengagumkannya dengan Ayah Anda. Katakan padaku, apakah kamu bisa beresonansi dengan bejana suci leluhur?",
  ui_story_5084_50840700_97_dialog_content = "Jika begitu, bagaimana rasanya?",
  ui_story_5084_50840700_98_dialog_content = "Rasanya seperti... Seseorang telah masuk ke pikiranku untuk memberitahuku tentang nektar yang pernah ada di dalamnya.",
  ui_story_5084_50840700_99_dialog_content = "Beberapa ceritanya diceritakan dengan tenang, seolah-olah ingin mengatakan...",
  ui_story_5084_50840700_100_dialog_content = "Porfirio! Siapa yang memberimu izin masuk ke wilayahku?!",
  ui_story_5084_50840700_101_dialog_content = "Heheh, aku hanya datang untuk melihat bagaimana Lady Victoria berada, Wilhelm. Aku akan pergi sekarang.",
  ui_story_5084_50840700_102_dialog_content = "Dia baik-baik saja. Jika kamu mengharapkan darah segar, saya sarankan kamu segera membuang pikiran itu.",
  ui_story_5084_50840700_103_dialog_content = "Jangan mempengaruhi tindakannya dengan ambisi liar Anda!",
  ui_story_5084_50840700_104_dialog_content = "Saya bebas berbicara dengan siapa pun yang saya inginkan, Wilhelm.",
  ui_story_5084_50840700_105_dialog_content = "Kamu masih terlalu naif, Victoria. Kamu tidak akan belajar tentang dunia dengan tenggelam dalam teks kuno; kamu hanya akan menjauhkan diri darinya.",
  ui_story_5084_50840700_106_dialog_content = "Kamu tahu tentang Bloody Bible yang berada di dalam makam leluhur kita, bukan? Kebijaksanaan yang diberikannya tidak akan pernah bisa ditemukan di halaman buku lainnya.",
  ui_story_5084_50840700_107_dialog_content = "Sejak orang tua Anda dimakamkan, tidak pernah sekali pun Anda mengunjungi makam tersebut.",
  ui_story_5084_50840700_108_dialog_content = "Tetapi itu tidak masalah. Saya tidak menyalahkan Anda karena membenci True Order, tetapi emosi Anda bukan alasan yang cukup untuk melakukannya.",
  ui_story_5084_50840700_109_dialog_content = "Jika tidak, Anda tidak lebih baik dari anak kecil yang rewel.",
  ui_story_5084_50840700_110_dialog_content = "Aku harus menjadi lebih kuat, sehingga tak ada orang yang bisa mengendalikanku lagi.",
  ui_story_5084_50840700_111_dialog_content = "Untuk itu, saya mencari Kebenaran dengan mencoba beresonansi dengan beberapa relik melalui ritual kuno...",
  ui_story_5084_50840700_112_dialog_content = "Dimana itu? Dimana teks kuno itu bisa berada...?",
  ui_story_5084_50840700_113_dialog_content = "Tuhan Kebenaran muncul dalam mimpiku, memanggilku untuk menemukan teks sakral-Nya sebelum Wilhelm Varaki menyadari bahwa aku hilang...",
  ui_story_5084_50840700_114_dialog_content = "Ah!",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>Bintang-bintang</color>... Itu melahap <color=#FFB400>bintang-bintang</color>... Tidak ada waktu! Tidak ada waktu sama sekali... Sebuah <color=#FFB400>awal baru</color> ada di tangan...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>Akhir yang sebenarnya terletak dalam kegelapan itu—!</size>",
  ui_story_5084_50840700_117_dialog_content = "Lepaskan itu segera, kau bodoh! Berani-beraninya kamu mencoba beresonansi dengan relik kuno itu!",
  ui_story_5084_50840700_118_dialog_content = "Kebijaksanaan dari zaman dahulu, wahyu dari seorang gila—Aku, Wilhelm Varaki, perintahkan kamu untuk menjauh darinya!",
  ui_story_5084_50840700_119_dialog_content = "... Ah!",
  ui_story_5084_50840700_120_dialog_content = "... Kembali ke tidur abadi Anda.",
  ui_story_5084_50840700_121_dialog_content = "K-Kamu menyelamatkanku? Tapi bagaimana kamu tahu aku...",
  ui_story_5084_50840700_122_dialog_content = "Belajarlah untuk membedakan antara karakteristik relik yang berbeda, atau mayatmu lah yang akan aku ambil selanjutnya.",
  ui_story_5084_50840700_123_dialog_content = "Dan jangan salah paham tentang niatku. Sebagai pemimpin True Order, hal terakhir yang aku butuhkan adalah dituduh oleh orang-orang yang setia kepada saya telah menyakiti putri almarhum saudaraku.",
  ui_story_5084_50840700_124_dialog_content = "Menjaga agar kamu tetap hidup hanya membantu untuk memastikan stabilitas posisiku.",
  ui_story_5084_50840700_125_dialog_content = "Lebih jauh lagi, daripada menyelamatkan seseorang yang berada di ambang kematian, keluarga darah lebih memilih untuk menguras setiap tetes darah terakhir dari tubuh mereka.",
  ui_story_5084_50840700_126_dialog_content = "Wilhelm Varaki...!",
  ui_story_5084_50840700_127_dialog_content = "Pria itu yang sombong, arogan, dan menjijikkan... Dia telah merampas hidup dan kebebasanku, dan alasannya selalu begitu aneh.",
  ui_story_5084_50840700_128_dialog_content = "Tapi dibandingkan dengan paman yang saya benci, yang lain hampir tidak ada yang lebih baik.",
  ui_story_5084_50840700_129_dialog_content = "Kepala keluarga adalah orang-orang tolol berhati hitam, semuanya. Orang-orang yang mereka pimpin seperti cacing atau mayat hidup, berjalan-jalan di kota tanpa tujuan atau kesadaran.",
  ui_story_5084_50840700_130_dialog_content = "Khotbah mereka penuh dengan kejahatan dan kebodohan, dan tidak memberikan petunjuk bagi orang-orang setia pada Kebenaran. Orang-orang seperti itu tidak layak untuk menjadi gembala bagi yang tersesat.",
  ui_story_5084_50840700_131_dialog_content = "Aku harus berhati-hati terhadap mereka... Aku tidak bisa membiarkan diriku menjadi korban dari kecenderungan buruk True Order.",
  ui_story_5084_50840700_132_dialog_content = "Untuk mematuhi kehendak Lord of Truth, dan untuk menyelesaikan \"akhir\" yang telah ditunjukkan padaku.",
  ui_story_5084_50840700_133_dialog_content = "Akhir-akhir ini, kau terus mengurung diri di rumah. Akhirnya kau kehilangan minat pada relik-relik itu?",
  ui_story_5084_50840700_134_dialog_content = "Pada saat kami seumuran denganmu, ayahmu dan saya telah lama membangkitkan kekuatan garis keturunan kami, dan hati kami tak pernah puas akan kebijaksanaan The Truth.",
  ui_story_5084_50840700_135_dialog_content = "Bisakah jadi kamu masih sama bodohnya seperti sebelumnya? Apakah kamu masih tidak mampu menjawab pertanyaanku tentang Kebenaran?",
  ui_story_5084_50840700_136_dialog_content = "... Saya telah memutuskan untuk keliling dunia dalam pencarian Truth.",
  ui_story_5084_50840700_137_dialog_content = "Lakukan sesukamu.",
  ui_story_5084_50840700_138_dialog_content = "Dan begitu saya memulai perjalanan saya, dan mencari petunjuk dari Truth untuk diri saya sendiri.",
  ui_story_5084_50840700_139_dialog_content = "Saat aku melangkahkan kaki keluar dari rumahku, aku mulai mendapatkan pengetahuan yang lebih dalam tentang dunia.",
  ui_story_5084_50840700_140_dialog_content = "Dan seiring pemahaman saya tentang The Truth semakin kuat, kekuatan garis keturunan saya mulai bangkit secara bertahap... Meski begitu, saya menolak untuk bergabung dengan True Order.",
  ui_story_5084_50840700_141_dialog_content = "Ketika saya akhirnya menemukan jawaban yang dia minta, saya kembali ke Varaki Town untuk memberi tahu dia... Hanya untuk menemukan bahwa dia tidak lagi mengharapkannya dari saya.",
  ui_story_5084_50840700_142_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840700_143_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840700_144_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840700_145_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840700_146_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840700_147_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840700_148_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840700_149_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840700_150_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840700_151_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840700_152_dialog_content = "...",
  ui_story_5084_50840700_153_dialog_content = "Sampai saat ini, aku masih belum mengerti dia.",
  ui_story_5084_50840700_154_dialog_content = "Aku takut bahwa aku juga telah melewatkan kesempatan terakhirku untuk melakukannya.",
  ui_story_5084_50840700_155_dialog_content = "Wilhelm Varaki: paman yang arogan, menjijikkan, dan tidak bisa dimengerti, juga kerabat terakhirku yang masih hidup... Kemana kau pergi?",
  ui_story_5084_50840700_156_dialog_content = "(Jadi begitulah Victoria melihat Wilhelm dalam ingatannya...)",
  ui_story_5084_50840700_157_dialog_content = "(Tapi dari perspektif Wilhelm, dia selalu menjaganya...)",
  ui_story_5084_50840700_158_dialog_content = "(Dia menderita kehilangan kendali atas dirinya sendiri, dan menolak untuk minum darah orang beriman seperti kepala keluarga lainnya. Dia memikirkan orang lain hingga akhir, dan bahkan berhasil menyelamatkan Nails...)",
  ui_story_5084_50840700_159_dialog_content = "(Selama bertahun-tahun... Mereka tidak pernah berhasil memahami satu sama lain... Bahkan ketika Wilhelm diserang...)",
  ui_story_5084_50840700_160_dialog_content = "(Aku bertanya-tanya apakah Victoria dapat melihat apa yang telah aku lihat...)",
  ui_story_5084_50840801_1_dialog_content = "Lilin itu mulai berkelip-kelip lagi—Kali ini akan membawa kita ke mana?",
  ui_story_5084_50840801_2_dialog_content = "Ini Victoria... Dan kepala keluarga lainnya. Apa yang mereka semua lakukan di sini?",
  ui_story_5084_50840801_3_dialog_content = "Hah? Apakah itu Faust yang berdiri di sampingnya? Dan saya pikir dia sedang melihat kita!",
  ui_story_5084_50840801_4_dialog_content = "Mungkinkah ini...?",
  ui_story_5084_50840801_5_option_content = "Mindlink",
  ui_story_5084_50840801_6_dialog_content = "Faust! Bisakah kamu mendengar suaraku?",
  ui_story_5084_50840801_7_dialog_content = "Tentu saja, dan saya sepenuhnya menyadari keraguan Anda saat ini.",
  ui_story_5084_50840801_8_dialog_content = "Orang yang kamu lihat di sini adalah Lady Victoria, orang yang sangat kamu kenal.",
  ui_story_5084_50840801_9_dialog_content = "Tapi jika ini Victoria dari zaman kita... Kenapa dia berdiri di depan orang-orang ini...?",
  ui_story_5084_50840801_10_dialog_content = "Wilhelm telah hilang selama tiga tahun sekarang. Satu-satunya keturunan Varaki yang tersisa adalah anak Ibrahim dan Victoria, keponakan Wilhelm.",
  ui_story_5084_50840801_11_dialog_content = "(Tiga tahun... Wilhelm diserang pada tahun 1915, yang berarti sekarang kita harus berada di tahun 1918, bukan?)",
  ui_story_5084_50840801_12_dialog_content = "Namun, Clavis Ibrahim tidak bersedia membiarkan anaknya masuk ke True Order, yang berarti dia tidak memiliki hak atas kepemimpinannya.",
  ui_story_5084_50840801_13_dialog_content = "Sejauh ini, posisi tersebut masih kosong dan cincin keluarga tidak ditemukan di mana pun. Kami menduga bahwa itu menghilang bersama dengan Wilhelm Varaki.",
  ui_story_5084_50840801_14_dialog_content = "Dan sejak Victoria tidak lagi memiliki hak waris atas kebijaksanaan leluhur kita...",
  ui_story_5084_50840801_15_dialog_content = "Oh? Apakah kalian semua berkumpul di sini hari ini hanya untuk memberitahuku ini?",
  ui_story_5084_50840801_16_dialog_content = "Saya diberitahu bahwa kamu lebih suka mencari Truth dengan menjelajahi dunia luar. Kami menghargai pilihanmu.",
  ui_story_5084_50840801_17_dialog_content = "Anda bebas untuk meninggalkan tempat ini, atau tinggal dan menjadi bagian dari Keluarga Porfirio. Dalam hal apapun, Anda tidak lagi memenuhi syarat untuk memimpin True Order.",
  ui_story_5084_50840801_18_dialog_content = "Dengan kedatangan Advent of Truth yang berlangsung malam ini, kepemimpinan True Order harus jatuh kepada...",
  ui_story_5084_50840801_19_dialog_content = "Apakah pertemuan Order benar-benar menjadi begitu sepi dan terpuruk tanpa kehadiran Wilhelm?",
  ui_story_5084_50840801_20_dialog_content = "Bahkan keluarga darah sekalipun harus membayar harga yang mahal untuk meminum darah yang seharusnya tidak dikonsumsi.",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>Victoria menuangkan segelas anggur merah darah di meja di depannya. Di dasar gelas terletak cincin yang pernah dipakai Wilhelm.</color>",
  ui_story_5084_50840801_22_dialog_content = "…?",
  ui_story_5084_50840801_23_dialog_content = "... Cincin Wilhelm.",
  ui_story_5084_50840801_24_dialog_content = "Dia mempercayakannya kepada saya tepat sebelum meninggalkan tempat ini. Kata-kata leluhur kita telah lama membimbing langkah-langkahku.",
  ui_story_5084_50840801_25_dialog_content = "Sekarang katakan padaku, apa lagi yang bisa kamu katakan tentang kepemimpinan True Order?",
  ui_story_5084_50840801_26_dialog_content = "Tak mungkin!",
  ui_story_5084_50840801_27_dialog_content = "Rencana harus diubah...",
  ui_story_5084_50840801_28_dialog_content = "Sepertinya setiap satu dari kalian mengetahui beberapa jenis skema.",
  ui_story_5084_50840801_29_dialog_content = "Ini adalah pengetahuan yang dinyatakan kepadaku selama Advent of Truth tiga tahun lalu.",
  ui_story_5084_50840801_30_dialog_content = "Tiga tahun yang lalu...",
  ui_story_5084_50840801_31_dialog_content = "Tidak, ini tidak mungkin!",
  ui_story_5084_50840801_32_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840801_33_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840801_34_dialog_content = "...",
  ui_story_5084_50840801_35_dialog_content = "<size=45>Ah-!!!</size>",
  ui_story_5084_50840801_36_dialog_content = "Ditakdirkan untuk mati secara terhina di kampung halamanmu sendiri... Betapa saya merasa kasihan padamu, Wilhelm Varaki.",
  ui_story_5084_50840801_37_dialog_content = "...",
  ui_story_5084_50840801_38_dialog_content = "Dan tanpa keturunan untuk diceritakan, cincin Varaki telah kehilangan semua maknanya.",
  ui_story_5084_50840801_39_dialog_content = "Apa yang telah kau lakukan? Dengan menghancurkan cincin itu, kau telah...",
  ui_story_5084_50840801_40_dialog_content = "Sekarang tidak ada gunanya untukmu atau aku. Biarkan puing-puing itu beristirahat dengan Wilhelm dalam damai.",
  ui_story_5084_50840801_41_dialog_content = "Mulai hari ini, itu tidak bisa digunakan untuk mengancam kami lagi.",
  ui_story_5084_50840801_42_dialog_content = "Belenggu yang merupakan kepala Varaki ada di masa lalu!",
  ui_story_5084_50840801_43_dialog_content = "Cincin itu... Seharusnya sudah terbakar menjadi abu, bersama dengan Wilhelm...",
  ui_story_5084_50840801_44_dialog_content = "Sepertinya kamu telah mengungkap kebenaran.",
  ui_story_5084_50840801_45_dialog_content = "Oh? Apakah itu seharusnya tetap menjadi rahasia?",
  ui_story_5084_50840801_46_dialog_content = "... Tapi apakah kamu benar-benar sudah memakainya? Apakah benar-benar telah memberikan kebijaksanaannya padamu?",
  ui_story_5084_50840801_47_dialog_content = "Kecuali dianggap layak oleh leluhur kita, kamu tidak akan pernah berhasil Wilhelm!",
  ui_story_5084_50840801_48_dialog_content = "Nama Varaki diberikan kepada saya oleh leluhur kita, dan cincin yang telah lama hilang ini adalah simbol persetujuan mereka. Sekarang saya akan memakainya agar semua orang bisa melihat.",
  ui_story_5084_50840801_49_dialog_content = "PlayerName Cincin itu akan membuat Lady Victoria kehilangan kendali!",
  ui_story_5084_50840801_50_dialog_content = "Jangan khawatir May, aku mulai menyadari mengapa aku di sini sekarang. Aku tahu persis apa yang harus kulakukan!",
  ui_story_5084_50840801_51_option_content = "Mindlink—",
  ui_story_5084_50840801_52_dialog_content = "Urgh... Jangan lagi...",
  ui_story_5084_50840801_53_dialog_content = "Suara-suara... Wahyu-wahyu kuno...",
  ui_story_5084_50840801_54_dialog_content = "Jangan khawatir Victoria, aku akan membantu kamu menekannya!",
  ui_story_5084_50840801_55_dialog_content = "? Oh, begitu... Ini pasti kehendak Tuhan Kebenaran. Kalau begitu, kuserahkan padamu.",
  ui_story_5084_50840801_56_dialog_content = "Dia memakainya... Dia benar-benar memakainya...",
  ui_story_5084_50840801_57_dialog_content = "Mengapa kalian semua begitu khawatir? Seorang Varaki sejati seharusnya tidak memiliki masalah untuk menahan suara dari leluhur kita, setelah semua.",
  ui_story_5084_50840801_58_dialog_content = "Heheh... Hahahaha—",
  ui_story_5084_50840801_59_dialog_content = "Tawa itu...",
  ui_story_5084_50840801_60_dialog_content = "Behold! I, Wilhelm Varaki, now tower over all of you!",
  ui_story_5084_50840801_61_dialog_content = "Our ancestor has deemed me worthy of becoming the new head of the Varaki Family!",
  ui_story_5084_50840801_62_dialog_content = "Varaki...!",
  ui_story_5084_50840801_63_dialog_content = "Lihatlah, penerus dari Keluarga Varaki!",
  ui_story_5084_50840802_1_dialog_content = "Aku akan membersihkan dunia dari keberadaanmu!",
  ui_story_5084_50840802_2_dialog_content = "Apa yang kulihat...?",
  ui_story_5084_50840802_3_dialog_content = "Saya berusaha sebaik mungkin untuk menahan suara-suara itu, tetapi visi-visi ini masih berhasil lolos dari cincin.",
  ui_story_5084_50840802_4_dialog_content = "Mereka tampaknya tidak terhubung dengan suara-suara itu. Jika ada, saya pikir mereka berasal dari tingkat kesadaran yang lebih tinggi.",
  ui_story_5084_50840802_5_dialog_content = "Mereka tampaknya tidak berbahaya. Izinkan saya untuk melihat mereka.",
  ui_story_5084_50840802_6_dialog_content = "<size=45>Ah-!!!</size>",
  ui_story_5084_50840802_7_dialog_content = "Darahmu dan otoritas yang diberikannya kini adalah milikku, Wilhelm Varaki!",
  ui_story_5084_50840802_8_dialog_content = "Kamu akan berfungsi sebagai <color=#FFB400>kunci</color>ku dan membuka kebijaksanaan leluhur kita untukku! Hahahaha!",
  ui_story_5084_50840802_9_dialog_content = "Wilhelm Varaki... Dia...!",
  ui_story_5084_50840802_10_dialog_content = "Wilhelm... Ketika kamu memberitahuku tentang rencanamu untuk pergi, aku berasumsi bahwa kamu telah menemukan tempat perlindungan yang aman untuk Victoria dan dirimu sendiri.",
  ui_story_5084_50840802_11_dialog_content = "Jadi mengapa... Mengapa kau kembali ke tempat ini, kau bodoh...",
  ui_story_5084_50840802_12_dialog_content = "Heheh... Meskipun saya rasa saya juga bodoh karena begitu mudah mempercayai <color=#FFB400>pria itu</color>.",
  ui_story_5084_50840802_13_dialog_content = "Leluhur, aku memohon kepada kalian untuk menerima Wilhelm Varaki ke dalam lingkungan kalian. Meskipun ambisi yang tidak murni membakar di dalam urat nadinya, dia telah lebih dari layak atas nama bangsawan Varaki.",
  ui_story_5084_50840802_14_dialog_content = "Sekarang setelah dia telah dikhianati oleh seorang pendosa seperti saya, bebaskan dia dari kejahatannya dan berikanlah kepada saya.",
  ui_story_5084_50840802_15_dialog_content = "Meski jiwa saya akan segera dikutuk, saya dengan rendah hati berdoa agar istri saya dan Charon dapat menemukan cara untuk meninggalkan tempat ini...",
  ui_story_5084_50840802_16_dialog_content = "Wilhelm Varaki, teman lama saya... May semoga kamu menemukan kedamaian abadi di dalam peti mati ini.",
  ui_story_5084_50840802_17_dialog_content = "Apakah dia... Benar-benar mati? Wilhelm Varaki... Dia sudah mati selama ini...",
  ui_story_5084_50840802_18_dialog_content = "Apakah ini kebenaran yang ingin ditunjukkan cincin ini kepadaku?",
  ui_story_5084_50840802_19_dialog_content = "Pria yang memberikannya padaku tiga tahun lalu... Apakah dia benar-benar sudah pergi?",
  ui_story_5084_50840802_20_dialog_content = "... Apa yang akan kamu lakukan sekarang?",
  ui_story_5084_50840802_21_dialog_content = "Aku bisa merasakan bahwa aku semakin dekat dengan Truth.",
  ui_story_5084_50840802_22_dialog_content = "Sebagai pemimpin saat ini dari True Order, aku berpikir bahwa Lord of Truth membimbingku ke sini hanya untuk menyaksikan momen ini sekali lagi.",
  ui_story_5084_50840802_23_dialog_content = "Namun, kehadiranmu dan pengorbanan sebelumnya telah menunjukkan padaku bahwa aku harus berpartisipasi. Selain berkat dari tuanku, aku juga membawa kebencian yang tak terbantahkan di hatiku.",
  ui_story_5084_50840802_24_dialog_content = "Ini adalah sesuatu yang hanya bisa aku lakukan, dan hanya dengan cukup kendali atas kekuatan dan pikiranku.",
  ui_story_5084_50840802_25_dialog_content = "Diberkatilah Lord of Truth karena telah menghilangkan keraguan saya dan memberi saya kenikmatan pembalasan.",
  ui_story_5084_50840802_26_dialog_content = "Malam ini adalah kedatangan Truth. Rasa dendam kita muncul dari dahaga akan kebijaksanaan leluhur kita; biarkan mereka menyaksikan saat kita mengakhiri semuanya.",
  ui_story_5084_50840802_27_dialog_content = "Penduduk Varaki Town, mohon maafkan saya telah membuat kalian semua menunggu.",
  ui_story_5084_50840802_28_dialog_content = "Setelah menerima petunjuk dari Lord of Truth, sekarang aku mengerti tujuanku.",
  ui_story_5084_50840802_29_dialog_content = "Bukankah dering itu membawa rasa sakit yang sangat besar padamu?",
  ui_story_5084_50840802_30_dialog_content = "Bahkan Wilhelm pun tidak bisa mengenakannya dengan mudah.",
  ui_story_5084_50840802_31_dialog_content = "Wahyu apa yang kamu terima?",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>Victoria berdiri dan berjalan ke kepala meja.</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>Untuk membersihkan pesanan.</color>",
  ui_story_5084_50840802_34_dialog_content = "Apa?!",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>Angin hitam menerjang masuk ke dalam kuil, mengguncang pintu dan jendela dengan keras. Memegang kekuatan jauh melampaui zamannya, penerus Varaki tampaknya mengeluarkan ultimatum kepada kepala-kepala rumah tangga.</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>Menghancurkan—</color>",
  ui_story_5084_50840802_37_dialog_content = "Menjatuhkan gelas Anda karena terkejut? Betapa sangat memalukan.",
  ui_story_5084_50840802_38_dialog_content = "...",
  ui_story_5084_50840802_39_dialog_content = "Cincin itu... Ceritakan apa yang ditunjukkannya padamu!",
  ui_story_5084_50840802_40_dialog_content = "Berhenti, David! Apakah kamu lupa bahwa kita berada di Temple of Truth?!",
  ui_story_5084_50840802_41_dialog_content = "…!",
  ui_story_5084_50840802_42_dialog_content = "Mengingat segalanya dimulai dengan festival leluhur kita, sangatlah pantas jika segalanya harus berakhir malam ini.",
  ui_story_5084_50840802_43_dialog_content = "Sekarang, jika Anda memaafkan saya, sebagai kepala baru Varaki, saya harus mempersiapkan diri untuk Kedatangan Truth.",
  ui_story_5084_50840802_44_dialog_content = "Ketika bulan berdarah menggantung di langit dan lorong-lorong kuil bergema dengan suara lonceng, kita harus berkumpul sekali lagi untuk menyaksikan akhir dari malam yang panjang ini.",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>Di bawah cahaya lentera yang redup, David Porfirio berdiri di genangan darah. Selain pengikutnya yang gila, satu-satunya orang lain di ruangan itu adalah Clavis Ibrahim, yang tubuhnya telah disiksa hingga tak bisa dikenali lagi.</color>",
  ui_story_5084_50840900_2_dialog_content = "Beritahu saya... Apakah Wilhelm masih hidup?!",
  ui_story_5084_50840900_3_dialog_content = "Bicara... Sekarang...!",
  ui_story_5084_50840900_4_dialog_content = "Aku sudah memberitahumu semua yang aku tahu... Tidak ada gunanya menyiksaku lebih lama lagi...",
  ui_story_5084_50840900_5_dialog_content = "Aku meletakkan tubuhnya yang tak bernyawa di peti mati itu dengan kedua tanganku sendiri... Tidak ada yang bisa menyangkal kematiannya...",
  ui_story_5084_50840900_6_dialog_content = "Selama Advent of Truth tiga tahun lalu, Wilhelm membantu Victoria melarikan diri dari peti mati.",
  ui_story_5084_50840900_7_dialog_content = "Tidak mampu lagi menahan tiraninya, kami akhirnya bangkit melawannya dan menghancurkan cincin yang mengikat kami bersama-sama.",
  ui_story_5084_50840900_8_dialog_content = "Jadi mengapa, setelah tiga tahun, Victoria muncul dengan cincin yang sama persis di tangannya?!",
  ui_story_5084_50840900_9_dialog_content = "Mereka berdua pasti merencanakan sesuatu.",
  ui_story_5084_50840900_10_dialog_content = "Bloody Bible tidak memiliki teks tertulis. Itu tidak akan menunjukkan kepada kamu kata-kata ilahi yang sangat kamu cari.",
  ui_story_5084_50840900_11_dialog_content = "Gadis Varaki, di sisi lain, telah membuktikan dirinya sangat mirip dengan ayahnya.",
  ui_story_5084_50840900_12_dialog_content = "Heh... Heheheh... Hahahaha—",
  ui_story_5084_50840900_13_dialog_content = "Apa yang menurutmu sangat lucu?",
  ui_story_5084_50840900_14_dialog_content = "Kami adalah orang bodoh yang gentar karena ancaman kosong Wilhelm, dan sekarang kami tidak punya pilihan lain.",
  ui_story_5084_50840900_15_dialog_content = "Kita seharusnya telah membunuhnya dan Victoria pada hari orang tua nya meninggal.",
  ui_story_5084_50840900_16_dialog_content = "Kekuatan Wilhelm masih belum terbangun pada saat itu, dan Victoria hampir tidak menjadi ancaman.",
  ui_story_5084_50840900_17_dialog_content = "Setelah lama membungkuk kepada Varaki, tampaknya kita hampir lupa... Bahwa yang disebut \"Truth\" hanyalah sisa-sisa dari keyakinan luar.",
  ui_story_5084_50840900_18_dialog_content = "Memang. Mengonsumsi darah segar dan menarik kekuatan darinya adalah satu-satunya cara bagi orang-orang kita untuk bertahan hidup!",
  ui_story_5084_50840900_19_dialog_content = "Tanpa kekuatan sejati kami, kami terpaksa mempertahankan keyakinan kami pada <color=#FFB400>Tuhan Kebenaran</color> melalui pengesahan, pengulangan, pengekangan, dan doa. Ini tidak lebih dari bidah!",
  ui_story_5084_50840900_20_dialog_content = "Sudah terlambat sekarang, Porfirio... Dengan kekuatan cincin di tangan dia, dia sedang bersiap untuk menghancurkan kita saat ini juga.",
  ui_story_5084_50840900_21_dialog_content = "Tidak peduli seberapa kita mempersiapkan diri, kita memiliki kurang dari setengah hari sebelum kita semua...",
  ui_story_5084_50840900_22_dialog_content = "Diam! Wilhelm juga pernah memakai cincin itu di masa lalu, dan kami masih bisa menguras habis darahnya!",
  ui_story_5084_50840900_23_dialog_content = "Penyesalan satu-satunya adalah minum darahnya tidak memungkinkan saya untuk membentuk pact dengan Bloody Bible. Untuk memulai, sepertinya dia tidak pernah menjadi penerus Varaki.",
  ui_story_5084_50840900_24_dialog_content = "Tapi berkat pasokan tak terbatas dari para pengikutku, aku telah secara bertahap mendapatkan kembali kekuatanku... Dan sekarang aku akhirnya bisa mendengar panggilan lembut dari Bloody Bible!",
  ui_story_5084_50840900_25_dialog_content = "Sedikit lagi... Dan sebentar lagi pengetahuannya akan terungkap padaku!",
  ui_story_5084_50840900_26_dialog_content = "Varaki-lah yang harus disalahkan karena menekan garis keturunan kami dan mencegah kami mencapai keunggulan sejati!",
  ui_story_5084_50840900_27_dialog_content = "Kami dilahirkan untuk mengonsumsi darah yang hidup, namun Varaki berusaha untuk membatasi kecenderungan alami kami... Mungkin karena mereka takut akan kekuatan kami.",
  ui_story_5084_50840900_28_dialog_content = "Apa yang kamu berniat lakukan...?",
  ui_story_5084_50840900_29_dialog_content = "Sama seperti yang telah kita rencanakan sejak awal... Aku akan muncul di hadapan orang-orang yang setia dalam ritual malam ini, dan menunjukkan bahwa Bloody Bible telah mengakui saya.",
  ui_story_5084_50840900_30_dialog_content = "Tanpa kekuatan maupun dukungan, Victoria tidak memiliki cara untuk menghentikanku.",
  ui_story_5084_50840900_31_dialog_content = "Makam keluarga mereka dan penjaga yang lemah adalah satu-satunya hal yang mereka andalkan. Goblin, Viper, Undine... Aku meninggalkan Vinekeepers kepada kalian bertiga.",
  ui_story_5084_50840900_32_dialog_content = "Aku mengerti.",
  ui_story_5084_50840900_33_dialog_content = "Jika aku bisa membunuh Wilhelm, maka Victoria seharusnya tidak menjadi masalah.",
  ui_story_5084_50840900_34_dialog_content = "Aku hanya perlu mengisi kembali kekuatanku dan melihat trik apa yang dia simpan untuk malam ini.",
  ui_story_5084_50840900_35_dialog_content = "Nng... David...",
  ui_story_5084_50840900_36_dialog_content = "... Dan itu sekitar semua yang kita ketahui. Setelah bepergian bolak-balik melalui waktu begitu banyak kali, kita hampir tidak tahu di mana kita berada.",
  ui_story_5084_50840900_37_dialog_content = "Meski penampakan Truth bisa saja samar, rencananya tidak tanpa makna.",
  ui_story_5084_50840900_38_dialog_content = "Tiga tahun yang lalu, di masa sekarang kita—tahun 1915—saya terakhir melihat Wilhelm. Itu adalah saat Advent of Truth ketika dia memerintahkan saya masuk ke peti mati leluhur.",
  ui_story_5084_50840900_39_dialog_content = "Aku ingat melihatnya memutar cincin di jarinya saat itu, yang merupakan sesuatu yang belum pernah aku lihat sebelumnya. Saat itulah aku tahu...",
  ui_story_5084_50840900_40_dialog_content = "Dia mencoba memberitahuku sesuatu. Itulah mengapa aku memutuskan untuk berpartisipasi dalam ritual tersebut.",
  ui_story_5084_50840900_41_dialog_content = "Tapi saat aku tersadar, aku mendapati diriku berada di \"saat ini.\"",
  ui_story_5084_50840900_42_dialog_content = "Tiga tahun telah berlalu, dan aku terbangun di tempat tidurku dengan cincin keluarga kami di tangan.",
  ui_story_5084_50840900_43_dialog_content = "Wilhelm memberikannya kepada saya di akhir ritual itu.",
  ui_story_5084_50840900_44_dialog_content = "Dan ketika saya terbangun, saya menemukan diri saya di rumah besar itu tepat ketika seseorang datang dengan sebuah surat. Dia mempercayakan saya untuk mengantarkannya kepada Lady Victoria sebelum dia pergi.",
  ui_story_5084_50840900_45_dialog_content = "Tepat ketika saya mulai bertanya-tanya tentang situasi saya, Lady Victoria muncul dari ruangan terdekat.",
  ui_story_5084_50840900_46_dialog_content = "Surat itu hanya meminta saya untuk menghadiri pertemuan kepala keluarga sebelum Kedatangan Kebenaran. Tetapi jelas, mereka tidak mengantisipasi kehadiran saya.",
  ui_story_5084_50840900_47_dialog_content = "Siapa pun yang datang untuk mengantarkan surat itu tahu saya ada di sini. Bukan hanya itu, mereka tahu itu adalah saya yang sekarang, bukan Victoria, yang berada di titik ini.",
  ui_story_5084_50840900_48_dialog_content = "Itu mengingatkanku, Lady Victoria... Kami bertemu dengan Nails tadi tapi... Dia bertingkah sangat aneh...",
  ui_story_5084_50840900_49_dialog_content = "Dia berterima kasih kepada Wilhelm karena memberinya kesempatan untuk berada di sana, meskipun Wilhelm tidak tahu siapa dia.",
  ui_story_5084_50840900_50_dialog_content = "Mungkinkah orang yang mengatur semua ini adalah Wilhelm dari Advent of Truth tiga tahun lalu?",
  ui_story_5084_50840900_51_dialog_content = "Dia sudah mati dalam penglihatan yang kita lihat sebelumnya, namun entah bagaimana dia masih ada di masa lalu.",
  ui_story_5084_50840900_52_dialog_content = "Dia pasti telah melakukan sesuatu selama Advent of Truth tiga tahun lalu, sesuatu yang masih berada di luar pemahaman kita.",
  ui_story_5084_50840900_53_dialog_content = "Meski begitu, aku bisa merasakan bahwa kita semakin mendekati Kebenaran.",
  ui_story_5084_50840900_54_dialog_content = "Lady Victoria, aku harus bertanya... Di mana tepatnya kamu saat Advent of Truth pada tahun 1918?",
  ui_story_5084_50840900_55_dialog_content = "Jika aku ingat dengan benar... Aku masih dalam perjalanan selama Advent of Truth tahun itu. Oleh karena itu, aku tidak memiliki cara untuk hadir di pertemuan itu.",
  ui_story_5084_50840900_56_dialog_content = "Tetapi malam itu juga, saya tertidur di kota Vortex ketika The Truth memerintahkan saya untuk kembali demi Bloody Bible.",
  ui_story_5084_50840900_57_dialog_content = "Ketika saya terbangun, saya menemukan diri saya di dalam <color=#FFB400>peti mati</color> yang terletak jauh di dalam makam Varaki, Bloody Bible erat di genggaman tangan saya.",
  ui_story_5084_50840900_58_dialog_content = "Setelah itu, terungkap kepada saya bahwa Vortex telah diakui, dan bahwa saya ditunjuk untuk menjadi Pemimpin dari True Order.",
  ui_story_5084_50840900_59_dialog_content = "Ini adalah kenangan yang ditunjukkan kepadaku oleh cincin sebelum kita berangkat dalam pencarian kita.",
  ui_story_5084_50840900_60_dialog_content = "Apakah kamu bilang... Sebuah <color=#FFB400>peti mati</color> di makam Varaki? Tapi mengapa itu sebuah <color=#FFB400>peti mati</color>?",
  ui_story_5084_50840900_61_dialog_content = "Mungkin karena... Aku juga memiliki kebiasaan tidur di dalamnya.",
  ui_story_5084_50840900_62_dialog_content = "(Itu benar... Dia melakukan itu di peti mati orang tuanya... Wilhelm juga...)",
  ui_story_5084_50840900_63_dialog_content = "Mungkin peti mati di makam Keluarga Varaki memiliki semacam kekuatan yang tidak diketahui?",
  ui_story_5084_50840900_64_dialog_content = "Seperti kekuatan untuk bepergian ke waktu yang berbeda?",
  ui_story_5084_50840900_65_dialog_content = "Mirip seperti kandel Caelestite, mungkin mereka juga dapat membawa Anda ke berbagai titik waktu.",
  ui_story_5084_50840900_66_dialog_content = "Ini juga membantu Wilhelm membuka pintu ke kripta selama Advent of Truth tiga tahun lalu...",
  ui_story_5084_50840900_67_dialog_content = "Sikare... Berapa banyak sebenarnya dia memiliki ini?!",
  ui_story_5084_50840900_68_dialog_content = "Keluarga Sikare selalu melindungi \"ruang bawah tanah\" dan menjaga Lady Victoria agar tidak mengintip ke dalam.",
  ui_story_5084_50840900_69_dialog_content = "Setiap kali kami bertanya, Sikare hanya akan mengatakan bahwa ini belum waktunya... Jadi mengapa ini adalah waktu yang tepat?",
  ui_story_5084_50840900_70_dialog_content = "Mungkin ada makna yang lebih dalam di balik hilangnya Wilhelm, bahkan kematiannya.",
  ui_story_5084_50840900_71_dialog_content = "Tampaknya dia telah menyadari bahaya yang dia hadapi pada hari itu dalam waktu yang lama, dan dia hanya menunggu kami muncul.",
  ui_story_5084_50840900_72_dialog_content = "Dia pernah menuntut agar aku memberinya penjelasan tentang Kebenaran. Dia hampir tak kenal lelah tentang hal itu... Tapi sekarang aku menyadari bahwa dia tidak pernah mengharapkan jawaban yang \"benar\" dariku.",
  ui_story_5084_50840900_73_dialog_content = "Karena \"The Truth\" tidak memiliki jawaban yang benar, dan tidak akan pernah ada.",
  ui_story_5084_50840900_74_dialog_content = "Ini adalah keyakinan yang tidak goyah yang berusaha memberikan jawaban tak terbatas.",
  ui_story_5084_50840900_75_dialog_content = "Dan sekarang setelah aku memahami kekuatan dari jawaban-jawaban ini, aku tidak lagi merasa takut atau ragu. Tujuanku jelas: Aku harus membersihkan kepala keluarga dari True Order.",
  ui_story_5084_50840900_76_dialog_content = "Andai saja dia bisa berbicara jujur dengan saya tiga tahun lalu dan memahami pencarian saya...",
  ui_story_5084_50840900_77_dialog_content = "(Dua orang itu sudah keras kepala selama ini... Apakah benar tidak ada cara bagi mereka untuk berdamai setelah semua ini?)",
  ui_story_5084_50840900_78_dialog_content = "Dalam hal apapun, aku tidak akan berhenti... Sampai aku menemukan makna di balik cincin ini muncul kembali dalam kepemilikanku.",
  ui_story_5084_50840900_79_dialog_content = "(Setelah melompat bolak-balik melalui waktu begitu banyak kali... Aku juga ingin jawaban yang pasti...)",
  ui_story_5084_50840900_80_dialog_content = "(Mengapa Victoria dan aku melihat Wilhelm dengan cara yang berbeda? Dari apa yang telah aku lihat, dia benar-benar peduli padanya, tapi dia tidak terlihat seperti itu dalam ingatannya.)",
  ui_story_5084_50840900_81_dialog_content = "(Sesuatu masih hilang... Apapun itu, aku yakin segalanya akan jauh lebih jelas setelah kita menemukannya. Victoria bahkan mungkin memiliki kesempatan untuk memberikan jawabannya kepada Wilhelm...)",
  ui_story_5084_50840900_82_dialog_content = "(... Apa masalahnya, lilin? Kamu selalu membimbingku ke jawaban setiap kali aku memiliki pertanyaan, jadi kenapa kamu tidak bekerja kali ini?)",
  ui_story_5084_50840900_83_dialog_content = "(Ah... Kurasa aku akhirnya mengerti darimana asal keyakinan tak tergoyahkan True Order...)",
  ui_story_5084_50840900_84_dialog_content = "Malam telah tiba, dan Kedatangan Kebenaran hampir menimpa kita. Waktu kita tidak banyak tersisa.",
  ui_story_5084_50840900_85_dialog_content = "Waktu... Itu mengingatkanku, saya hanya memiliki sekitar sepertiga dari kandil saya tersisa.",
  ui_story_5084_50840900_86_dialog_content = "Jangan khawatir, aku tahu apa yang harus dilakukan sekarang.",
  ui_story_5084_50840900_87_dialog_content = "Ancaman saya selama pertemuan membuat mereka ketakutan, yang hanya memicu keinginan mereka untuk lebih berkuasa. Mereka tidak akan berhenti sampai berhasil mengalahkan saya.",
  ui_story_5084_50840900_88_dialog_content = "Tapi bagaimana jika mereka mencoba untuk lari? Kamu bisa menjadi cukup menakutkan saat kamu ingin, Victoria.",
  ui_story_5084_50840900_89_dialog_content = "Ambisi David Porfirio tidak akan membiarkannya lari. Dia tidak akan pernah puas kecuali dia mencapai tujuannya.",
  ui_story_5084_50840900_90_dialog_content = "Tampaknya dia memiliki Bloody Bible dari waktu ini dalam kepemilikannya.",
  ui_story_5084_50840900_91_dialog_content = "Untuk mewujudkan aspirasinya menjadi pemimpin True Order, dia akan tinggal dan melakukan segala yang ada dalam kekuasaannya untuk memimpin ritual malam ini.",
  ui_story_5084_50840900_92_dialog_content = "Ambisi bisa menjadi binatang yang menakutkan. Sama seperti itu menelan Wilhelm, begitu pula itu akan menelan David.",
  ui_story_5084_50840900_93_dialog_content = "Jadi, kemana kita harus pergi?",
  ui_story_5084_50840900_94_dialog_content = "Ke makam leluhurku—Ada sesuatu yang perlu aku konfirmasi di sana. Jika segalanya berjalan sesuai rencana, David juga akan mengirim seseorang ke sana.",
  ui_story_5084_50840900_95_dialog_content = "Tunggu, Lady Victoria... Apa yang harus kita lakukan tentang Mr. Nails?",
  ui_story_5084_50840900_96_dialog_content = "Dia masih ada di suatu tempat di kota ini.",
  ui_story_5084_50840900_97_dialog_content = "Tidak perlu khawatir untuknya. Tuhan kita telah memberkatinya dengan perlindungan, dan Truth akan membimbingnya ke tempat yang dia butuhkan.",
  ui_story_5084_50840900_98_dialog_content = "Tapi Lady Victoria, aku melihat kepala keluarga menyakitinya dengan kedua mataku sendiri...",
  ui_story_5084_50840900_99_dialog_content = "Aku masih khawatir tentang dia, dan selama ini aku ingin mencarinya. Aku hanya tidak yakin jika itu akan menimbulkan lebih banyak masalah untuk setiap orang.",
  ui_story_5084_50840900_100_dialog_content = "Merasa bingung bukanlah alasan untuk khawatir, dan kekhawatiran untuk orang lain adalah kualitas yang mulia. Lakukan apa yang hatimu katakan, May.",
  ui_story_5084_50840900_101_dialog_content = "Faust, tolong tinggal dengan May dan jaga Nails.",
  ui_story_5084_50840900_102_dialog_content = "Caelestite dan aku akan bertemu denganmu di kuil malam ini.",
  ui_story_5084_50841001_1_dialog_content = "Rambatan di pintu masuk dipenuhi darah, dan peti mati telah dipaksa terbuka... Apakah kepala keluarga selangkah di depan kami?",
  ui_story_5084_50841001_2_dialog_content = "Mengganggu sisa-sisa leluhur kami... Pengabaian mereka terhadap doktrin kami tidak mengenal batas.",
  ui_story_5084_50841001_3_dialog_content = "Saya pikir ini adalah tempat yang kita lihat sebelumnya!",
  ui_story_5084_50841001_4_dialog_content = "Ini adalah tempat di mana Clavis meletakkan Wilhelm di peti mati itu...",
  ui_story_5084_50841001_5_dialog_content = "Namun peti matinya tidak terlihat.",
  ui_story_5084_50841001_6_dialog_content = "Nyonya ku... Lady Victoria... Apakah itu kamu?",
  ui_story_5084_50841001_7_dialog_content = "Kuburan? Syukurlah kamu masih hidup. Ketika saya melihat tanaman merambat di luar, saya khawatir yang terburuk...",
  ui_story_5084_50841001_8_dialog_content = "Tiga tahun, Lady... Selama tiga tahun, tidak ada kepala keluarga Varaki untuk mempertahankan tempat ini, dan akhirnya jatuh ke dalam kekacauan.",
  ui_story_5084_50841001_9_dialog_content = "Dengan kematian Wilhelm dan keberadaanmu yang tidak diketahui, kepala keluarga cabang merampok relik dari makam ini tanpa hukuman apa pun.",
  ui_story_5084_50841001_10_dialog_content = "Mereka merenggut keluargaku dan menyiksanya... Menyiksaku...",
  ui_story_5084_50841001_11_dialog_content = "Itu adalah David Porfirio... Dia berusaha untuk mengambil segalanya, termasuk kekuatanku sebagai pelayan Varaki...",
  ui_story_5084_50841001_12_dialog_content = "... Maafkan aku. Aku tidak tahu bahwa ketidakhadiranku akan membawa malapetaka yang tak terkatakan kepada kamu dan keluargamu.",
  ui_story_5084_50841001_13_dialog_content = "Kuburan... Apakah Wilhelm benar-benar sudah mati?",
  ui_story_5084_50841001_14_dialog_content = "Clavis... Apa yang telah kau lakukan?",
  ui_story_5084_50841001_15_dialog_content = "... Saya hanya datang untuk menempatkan mayat lain di bawah perawatan Anda.",
  ui_story_5084_50841001_16_dialog_content = "Tolong awasi sahabat bodohku ini.",
  ui_story_5084_50841001_17_dialog_content = "Clavis... Clavis...",
  ui_story_5084_50841001_18_dialog_content = "Aku melihatnya dengan mata kepala sendiri, Lady. Wilhelm sudah mati... Dan Clavis Ibrahim menggunakan kunci itu untuk memasuki makam dan menaruhnya untuk beristirahat.",
  ui_story_5084_50841001_19_dialog_content = "... Ayo kita masuk, Caelestite.",
  ui_story_5084_50841001_20_dialog_content = "Kamu punya janjiku, Graves: Aku akan menghentikan semua perselisihan ini malam ini.",
  ui_story_5084_50841001_21_dialog_content = "Tolong hati-hati... Gadisku...",
  ui_story_5084_50841001_22_dialog_content = "Di ujung terjauh dari ruang bawah tanah... Mereka terus mengganggu orang mati... Dalam pencarian sesuatu...",
  ui_story_5084_50841001_23_dialog_content = "Lihat, siapa ini.",
  ui_story_5084_50841001_24_dialog_content = "Wanita muda dari Varaki itu sendiri.",
  ui_story_5084_50841001_25_dialog_content = "... Wanitaku!",
  ui_story_5084_50841001_26_dialog_content = "Saya terkejut kau bisa selamat, Vinekeeper...",
  ui_story_5084_50841001_27_dialog_content = "Porfirio ingin membuang wanita Varaki itu, 'kan?",
  ui_story_5084_50841001_28_dialog_content = "Sekarang adalah kesempatan kita.",
  ui_story_5084_50841001_29_dialog_content = "Minion-minion bodoh...!",
  ui_story_5084_50841001_30_dialog_content = "Beraninya kamu menerobos ke dalam makam Varaki dan mengganggu leluhur kami yang sedang tidur!",
  ui_story_5084_50841001_31_dialog_content = "Saya berniat untuk menghukum setiap satu dari Anda selama ritual malam ini, tetapi tampaknya Anda telah membawa pertarungan kepada saya.",
  ui_story_5084_50841002_1_dialog_content = "Victoria... Yang disebut Undine menggali tanah dan melarikan diri...",
  ui_story_5084_50841002_2_dialog_content = "Hmph, hanya tersisa mereka berdua. Siap menerima takdir kalian?",
  ui_story_5084_50841002_3_dialog_content = "Tunggu, Lady Victoria... Sebagai seorang dewasa dan anggota terhormat dari Varaki, mungkin sebaiknya kamu bicara dengan Porfirio sebelum melakukan sesuatu yang tergesa-gesa?",
  ui_story_5084_50841002_4_dialog_content = "Tidak mungkin! Kau hanya pergi selama tiga tahun... Darimana kau mendapatkan kekuatan seperti itu?!",
  ui_story_5084_50841002_5_dialog_content = "Tiga tahun, kata Anda? Sepertinya Anda telah terjebak dalam dunia Anda sendiri yang stagnan selama ini sehingga Anda tidak dapat lagi memahami perubahan drastis.",
  ui_story_5084_50841002_6_dialog_content = "Saya telah mengumpulkan kekuatan ini jauh lebih lama dari tiga tahun... Tapi saya tidak berniat untuk mengungkapkan rahasia saya kepada kamu.",
  ui_story_5084_50841002_7_dialog_content = "Karena membiarkan keinginanmu menuntunmu menjauh dari Kebenaran, hidupmu harus dihaturkan sebagai pembukaan untuk Kedatangan Kebenaran!",
  ui_story_5084_50841002_8_dialog_content = "(Sikare mengatakan kepada kami untuk tidak mengubah apa pun, tetapi Victoria membunuh mereka berdua... Bukankah itu dihitung sebagai mengubah masa lalu?!)",
  ui_story_5084_50841002_9_dialog_content = "(Atau bisa jadi... apakah tindakan Victoria telah ditulis di halaman sejarah jauh-jauh hari?)",
  ui_story_5084_50841002_10_dialog_content = "Hmm?",
  ui_story_5084_50841002_11_dialog_content = "Sepertinya kamu juga tidak mengerti... rahasia dari ular kobra.",
  ui_story_5084_50841002_12_dialog_content = "Bahkan jika kamu memotong kepalaku, aku akan mengelupas kulitku dan dilahirkan kembali...",
  ui_story_5084_50841002_13_dialog_content = "Maka aku akan memutuskannya sebanyak yang dibutuhkan!",
  ui_story_5084_50841002_14_dialog_content = "T-Tunggu! Kau tidak bisa membunuhku seperti ini!",
  ui_story_5084_50841002_15_dialog_content = "Ini bukanlah niatku untuk melakukannya. Aku hanya penasaran seberapa lama lagi kamu bisa bertahan dari rasa sakit saat kepalamu dipotong.",
  ui_story_5084_50841002_16_dialog_content = "Sekarang berteriaklah! Mohon ampun! <size=45>Mohon padaku untuk mengakhiri penderitaanmu—!</size>",
  ui_story_5084_50841002_17_dialog_content = "(Astaga, Victoria... Aku tak menyadari dia bisa sekejam ini...)",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>Tiba-tiba, salah satu peti mati di dalam kripta meledak terbuka dengan kekuatan yang ganas, dan seseorang melangkah keluar darinya—</color>",
  ui_story_5084_50841002_19_dialog_content = "Tidak perlu membuang-buang tenaga pada orang sepertinya.",
  ui_story_5084_50841002_20_dialog_content = "?!",
  ui_story_5084_50841002_21_dialog_content = "... W-Wilhelm?!?",
  ui_story_5084_50841002_22_dialog_content = "Mustahil! Seharusnya kamu sudah mati sejak lama!",
  ui_story_5084_50841002_23_dialog_content = "... Jadi kamu masih hidup setelah semua ini.",
  ui_story_5084_50841002_24_dialog_content = "Tidak sepenuhnya. Setelah kematianku, aku menghabiskan banyak tahun melintasi aliran waktu yang tak berujung, dan sekarang aku akhirnya memiliki sedikit pemahaman tentang kehendak tuan kita.",
  ui_story_5084_50841002_25_dialog_content = "Kedatangan Truth tiga tahun lalu... Itu adalah kamu.",
  ui_story_5084_50841002_26_dialog_content = "Tiga tahun... Sekejap mata dalam skema besar keberadaan. Itulah takdir yang membimbingku ke sini, dan tampaknya ini adalah pemberhentian terakhirku.",
  ui_story_5084_50841002_27_dialog_content = "…?!",
  ui_story_5084_50841002_28_dialog_content = "(Aku tahu itu! Memang benar ada dua Wilhelm sejak awal!)",
  ui_story_5084_50841002_29_dialog_content = "(Jadi orang yang mengorbankan Victoria dan mengatur semua ini... Apakah Wilhelm setelah kematiannya sendiri?)",
  ui_story_5084_50841002_30_dialog_content = "Ambillah ini. Ini adalah lambang keinginan takdir untuk mengikutimu—",
  ui_story_5084_50841002_31_dialog_content = "... Bloody Bible?",
  ui_story_5084_50841002_32_dialog_content = "Tidak... Ini sama sekali tidak seperti relik yang telah aku kenal selama bertahun-tahun.",
  ui_story_5084_50841002_33_dialog_content = "Sebuah Bloody Bible baru, ditujukan untuk orang yang akan membimbing masa depan.",
  ui_story_5084_50841002_34_dialog_content = "Ambillah, karena hanya kamulah yang bisa mengendalikan kekuatannya.",
  ui_story_5084_50841002_35_dialog_content = "Gunakanlah untuk mengalahkan pengkhianat bodoh yang berdiri di depanmu.",
  ui_story_5084_50841002_36_dialog_content = "... Aku menolak.",
  ui_story_5084_50841002_37_dialog_content = "…?!",
  ui_story_5084_50841002_38_dialog_content = "Aku tidak memerlukan kekuatanmu—Mereka lah yang membunuhmu, jadi balas dendammu adalah urusanmu sendiri.",
  ui_story_5084_50841002_39_dialog_content = "Apa maksud dari ini? Mengapa kita tidak berdaya melawannya?!",
  ui_story_5084_50841002_40_dialog_content = "Pria itu bukanlah pria yang sama yang pernah kita bunuh di masa lalu.",
  ui_story_5084_50841002_41_dialog_content = "Kutuklah kamu, Wilhelm! Apa yang sebenarnya terjadi padamu setelah kamu mati?! Kamu harus memberi tahu kami... Setidaknya bagikan Kebenaran ini dengan kami!",
  ui_story_5084_50841002_42_dialog_content = "... Diam, para pengkhianat!",
  ui_story_5084_50841002_43_dialog_content = "Truth tidak memerlukan pemahamanmu!",
  ui_story_5084_50841002_44_dialog_content = "Ini hanya menuntut darahmu sebagai ganti kejahatanmu terhadap leluhur Varaki!",
  ui_story_5084_50841002_45_dialog_content = "Va... raki...",
  ui_story_5084_50841002_46_dialog_content = "(Wilhelm menghancurkan mereka berdua dengan satu serangan saja...!)",
  ui_story_5084_50841002_47_dialog_content = "Wilhelm Varaki... Peti mati ini seharusnya berisi sisa-sisa leluhur kita. Apa sebenarnya yang terjadi padamu?",
  ui_story_5084_50841002_48_dialog_content = "Mengapa kamu menghilang? Dan apa yang membuatmu muncul kembali di depan kami hari ini?",
  ui_story_5084_50841002_49_dialog_content = "Apakah kamu sudah terlahir kembali? Atau sekarang kamu hanya phantom?",
  ui_story_5084_50841002_50_dialog_content = "Kamu masih seperti yang aku ingat, Victoria: selalu penuh dengan pertanyaan.",
  ui_story_5084_50841002_51_dialog_content = "Sayangnya, tidak ada gunanya lagi membahas hal-hal ini. Waktu telah meluncur melewati kita, dan kita sudah lama meninggal.",
  ui_story_5084_50841002_52_dialog_content = "Selamat tinggal, Victoria.",
  ui_story_5084_50841002_53_dialog_content = "(Dia pergi begitu saja...? Mereka akhirnya memiliki kesempatan untuk bertemu lagi dan jelas peduli satu sama lain... Jadi mengapa mereka tidak mengatakan apa-apa?)",
  ui_story_5084_50841002_54_dialog_content = "P-Tolong tunggu, Tn. Wilhelm!",
  ui_story_5084_50841002_55_dialog_content = "Caelestite…",
  ui_story_5084_50841002_56_dialog_content = "Siapa kamu...?",
  ui_story_5084_50841002_57_dialog_content = "Tunggu, suara itu...",
  ui_story_5084_50841002_58_dialog_content = "Ah... Sekarang aku paham...",
  ui_story_5084_50841002_59_dialog_content = "Ini pasti takdir...",
  ui_story_5084_50841002_60_dialog_content = "Heheh... Sangat menghibur...",
  ui_story_5084_50841002_61_dialog_content = "Tuan Wilhelm! Kamu mungkin menyebutnya \"takdir\"—",
  ui_story_5084_50841002_62_dialog_content = "Tetapi ketika kamu mendengar kata-katanya, kamu masih memutuskan untuk mengejar The Truth di dalam hatimu. Kamu pergi ke kripta karena kamu khawatir tentang Victoria!",
  ui_story_5084_50841002_63_dialog_content = "Dan daripada menerima takdir yang telah ditentukan untuknya, Victoria memilih untuk memakai cincin dan menahan suara-suara itu demi menemukanmu...",
  ui_story_5084_50841002_64_dialog_content = "Kamu sudah berhasil melakukan hal yang tak terbayangkan dengan melakukan perjalanan bolak-balik melalui waktu; apakah benar-benar tidak masuk akal jika kalian berdua memiliki percakapan normal?",
  ui_story_5084_50841002_65_dialog_content = "Ketika kamu bertarung bahu-membahu melawan kepala keluarga... Aku bisa melihat emosi yang mendorong tindakanmu.",
  ui_story_5084_50841002_66_dialog_content = "Maaf... Aku tidak tahu apakah aku mengubah sejarah dengan mengatakan sesuatu yang seharusnya tidak kukatakan...",
  ui_story_5084_50841002_67_dialog_content = "Tapi dari lubuk hatiku, aku percaya pada semua yang akan aku katakan—",
  ui_story_5084_50841002_68_dialog_content = "Saya selalu berpikir bahwa kata-kata adalah cara terbaik untuk menyimpan rahasia... Jika kamu tidak saling membuka diri sekarang, kamu mungkin tidak akan pernah memiliki kesempatan untuk saling memahami lagi.",
  ui_story_5084_50841002_69_dialog_content = "...",
  ui_story_5084_50841002_70_dialog_content = "...",
  ui_story_5084_50841002_71_dialog_content = "Pertanyaan, jawaban... Tidak ada yang benar-benar penting lagi. Yang penting adalah kalian berdua ada di sini sekarang.",
  ui_story_5084_50841002_72_dialog_content = "Terlepas dari apakah \"takdir\" yang menentukannya atau tidak, setiap keputusan Anda harus berasal dari hati.",
  ui_story_5084_50841002_73_dialog_content = "Caelestite... Kamu...",
  ui_story_5084_50841002_74_dialog_content = "Heheh, andai saja seluruh dunia bisa sejujur kamu... Mungkin mereka tidak akan mudah tersesat.",
  ui_story_5084_50841002_75_dialog_content = "Kesungguhan yang begitu murni adalah salah satu harta terbesar yang dimiliki oleh Caelestite muda.",
  ui_story_5084_50841002_76_dialog_content = "Sekarang... Mulai dari mana, ya?",
  ui_story_5084_50841002_77_dialog_content = "Aku telah melayang melintasi waktu selama berabad-abad sekarang... Dan aku belum pernah merindukan akhir lebih dari sekarang.",
  ui_story_5084_50841002_78_dialog_content = "Victoria... Akhirnya aku mengerti keinginan abangku untuk tidur abadi, dan aku percaya kamu juga mengerti.",
  ui_story_5084_50841002_79_dialog_content = "Pilihan yang dibuat oleh hati kita lebih banyak daripada bintang di langit.",
  ui_story_5084_50841002_80_dialog_content = "Aku harus berterima kasih padamu, Victoria... Kamu akan membebaskan Varaki dari kutukan darah mereka suatu hari nanti, dan aku akhirnya akan bisa beristirahat dengan tenang.",
  ui_story_5084_50841002_81_dialog_content = "Sangat tidak mungkin kamu bisa mengungkapkan rasa syukur... Akankah aku benar-benar menjadi orang yang akan menghilangkan kutukan keluarga kita...?",
  ui_story_5084_50841002_82_dialog_content = "Seperti yang dikatakan Caelestite, pertanyaan dan jawaban kita...",
  ui_story_5084_50841002_83_dialog_content = "Tidak penting sekarang!",
  ui_story_5084_50841002_84_dialog_content = "Truth berbeda dari orang ke orang. Tidak ada jawaban final atau mutlak; hanya keyakinan yang harus terus dikejar.",
  ui_story_5084_50841002_85_dialog_content = "... Kamu boleh mengutarakan pikiranmu sekarang.",
  ui_story_5084_50841002_86_dialog_content = "Dunia kita ditandai oleh penderitaan dan perbedaan. Mereka yang diberkati dengan keabadian dikonsumsi oleh keinginan mereka akan kematian, sementara rekan-rekan fana mereka merindukan masa depan yang lebih panjang.",
  ui_story_5084_50841002_87_dialog_content = "Apakah benar ada penyelamat di <color=#FFB400>Eoria</color>?",
  ui_story_5084_50841002_88_dialog_content = "Dalam visiku, aku telah melihat penderitaan yang tak terhitung jumlahnya, dan namun keyakinanku dalam <color=#FFB400>keselamatan</color> hanya semakin kuat karena itu.",
  ui_story_5084_50841002_89_dialog_content = "Oleh karena itu, Kebenaran yang aku cari harus membawa kepada <color=#FFB400>keselamatan</color> dunia, dan penghapusan setiap benih yang jatuh.",
  ui_story_5084_50841002_90_dialog_content = "Dengan melampaui batasan kesadaran dan fisikal, Aurorian akan mencapai evolusi akhir mereka dan mendekati bintang-bintang, di mana Kebenaran tertinggi menunggu kedatangan mereka.",
  ui_story_5084_50841002_91_dialog_content = "... Kamu memang telah tumbuh dan menjadi pemimpin yang layak, Victoria. Ini sama seperti yang The Truth ungkapkan kepadaku.",
  ui_story_5084_50841002_92_dialog_content = "Kamu menyebutkan tentang bintang-bintang... Di saat kejatuhan saya, saya melihat sebuah sungai dalam kegelapan.",
  ui_story_5084_50841002_93_dialog_content = "Di dalamnya, sebab akibat dari semua eksistensi mengalir tanpa henti. Bahkan gangguan terkecil bisa mengakibatkan bencana yang tak terduga.",
  ui_story_5084_50841002_94_dialog_content = "Sebagai anggota dari keluarga abadi darah, kami telah menghabiskan banyak waktu untuk mengejar sesuatu yang hanyalah sebutir pasir di sungai ini.",
  ui_story_5084_50841002_95_dialog_content = "Meski begitu, obsesi tak kenal lelahku membawaku ke sungai itu.",
  ui_story_5084_50841002_96_dialog_content = "Sejak itu, saya telah memperkuat Kebenaran dalam hati saya—Dan meskipun perjalanan saya telah menjadi satu penuh kesulitan dan penderitaan, saya yakin bahwa keinginan saya akan akhirnya mempengaruhi aliran kausalitas.",
  ui_story_5084_50841002_97_dialog_content = "Apakah kamu percaya bahwa keyakinanmu cukup kuat untuk melampaui belenggu takdir?",
  ui_story_5084_50841002_98_dialog_content = "Ya. Aku akan menaatinya, mempraktekkannya, dan pada akhirnya... Aku akan menemukan cara untuk melihat desain takdir dan membentuknya kembali dengan tanganku sendiri.",
  ui_story_5084_50841002_99_dialog_content = "... Sekarang pergilah, Victoria. Tempuh jalan Truthmu, dan singkirkan segala halangan yang menghadangmu.",
  ui_story_5084_50841002_100_dialog_content = "Seperti yang pasti akan saya lakukan.",
  ui_story_5084_50841002_101_dialog_content = "Maka aku serahkan David padamu. Hentikan dia sebelum dia mengubah kota kita menjadi tempat kematian.",
  ui_story_5084_50841002_102_dialog_content = "Kau mau pergi ke mana sekarang?",
  ui_story_5084_50841002_103_dialog_content = "Saya sudah menjadi makhluk yang ada di luar aliran waktu. Saya hanya bisa mengubah peristiwa sejarah jika takdir mengizinkan...",
  ui_story_5084_50841002_104_dialog_content = "... Aku tidak pernah menyangka akan memiliki diskusi terakhir ini denganmu, paman.",
  ui_story_5084_50841002_105_dialog_content = "Kamu benar-benar telah dewasa, Victoria... Sungguh menenangkan.",
  ui_story_5084_50841002_106_dialog_content = "Sekarang, ambil Bloody Bible ini di tanganmu. Kamu akan membutuhkannya.",
  ui_story_5084_50841002_107_dialog_content = "Saya sudah memiliki kekuatan yang saya butuhkan untuk mengejar Truth. Tidak ada alasan bagi saya untuk mengambilnya.",
  ui_story_5084_50841002_108_dialog_content = "... Meski begitu, takdir akan membimbingmu ke sana suatu hari nanti.",
  ui_story_5084_50841002_109_dialog_content = "Selamat tinggal, Victoria Varaki.",
  ui_story_5084_50841002_110_dialog_content = "Muridmu, yang disebut Nails... Dia bisa diajarkan banyak hal.",
  ui_story_5084_50841002_111_dialog_content = "Aku meninggalkan masa depan True Order di tanganmu.",
  ui_story_5084_50841002_112_dialog_content = "... Apakah kita akan pernah bertemu lagi?",
  ui_story_5084_50841002_113_dialog_content = "Saya sudah menyelesaikan tugas yang diberikan oleh tuan kita. Sekarang, saatnya bagi saya untuk mengurus urusan saya sendiri.",
  ui_story_5084_50841002_114_dialog_content = "Kalau semua hal sudah berakhir, carilah aku di sini.",
  ui_story_5084_50841002_115_dialog_content = "Dan untukmu, Caelestite masa depan... Terima kasih telah membimbingku dengan kejujuranmu.",
  ui_story_5084_50841101_1_dialog_content = "Ini semua salah nenek... Dia bersikeras membuatku mendengarkan doanya kepada Tuhan Kebenaran sebelum membiarkanku pergi...",
  ui_story_5084_50841101_2_dialog_content = "Sekarang aku terjebak di belakang kerumunan tanpa bisa melihat prosesi!",
  ui_story_5084_50841101_3_dialog_content = "Nenekmu sudah terlalu tua untuk berpartisipasi dalam Advent of Truth lagi, sayang.",
  ui_story_5084_50841101_4_dialog_content = "Tetapi setelah menghabiskan seluruh hidupnya membuat pakaian untuk orang-orang yang beriman, dia masih menginginkan seseorang untuk menyampaikan keinginannya kepada Tuhan Kebenaran. Itulah sebabnya dia mempercayakan mereka kepada kamu.",
  ui_story_5084_50841101_5_dialog_content = "Aku akan menggendongmu untuk melihat prosesi—Tapi kamu harus ingat kata-kata Nenek. Ini adalah acara yang tulus, dan kamu harus memperlakukannya seperti itu.",
  ui_story_5084_50841101_6_dialog_content = "... Aku mengerti.",
  ui_story_5084_50841101_7_dialog_content = "Jalan ini cukup familier. Ini adalah tempat aku bertemu dengan PlayerName sebelumnya.",
  ui_story_5084_50841101_8_dialog_content = "Tapi bagaimana kita bisa menemukan Nails di kerumunan besar seperti ini?",
  ui_story_5084_50841101_9_dialog_content = "May... Apakah kamu ingat melihat orang-orang berpakaian aneh ini sebelumnya?",
  ui_story_5084_50841101_10_dialog_content = "B-Biarkan aku memikirkannya...",
  ui_story_5084_50841101_11_dialog_content = "Ah—!!!",
  ui_story_5084_50841101_12_dialog_content = "Apa itu? Mari kita pergi menyelidiki, May!",
  ui_story_5084_50841101_13_dialog_content = "... Itu undead! Mereka berjalan di antara kita—!",
  ui_story_5084_50841101_14_dialog_content = "Tuhan yang maha kuasa... Ini pasti hukuman untukku karena membaca buku harian rahasia adikku dan membuka kepura-puraannya di depan umum...",
  ui_story_5084_50841101_15_dialog_content = "Tetapi para pemimpin True Order mengklaim bahwa saya sakit, dan bahwa kamu tidak akan pernah memilih darah saya.",
  ui_story_5084_50841101_16_dialog_content = "Aku harus bertobat dengan dagingku...!",
  ui_story_5084_50841101_17_dialog_content = "Ibu...?",
  ui_story_5084_50841101_18_dialog_content = "Tapi aku mohon, ampunilah putriku, tuan. Dia hanyalah seorang anak kecil yang tak bersalah...",
  ui_story_5084_50841101_19_dialog_content = "Ya, Lord of Truth!",
  ui_story_5084_50841101_20_dialog_content = "Apakah ini pelayan-pelayanmu? Apakah mereka datang... Untuk menghukumku atas dosa-dosaku?",
  ui_story_5084_50841101_21_dialog_content = "Aku mengerti, dan aku tunduk pada kehendak ilahi Anda! Lakukan apa yang harus Anda lakukan padaku!",
  ui_story_5084_50841101_22_dialog_content = "—!",
  ui_story_5084_50841101_23_dialog_content = "Ibu—!",
  ui_story_5084_50841101_24_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_25_dialog_content = "L-Lari, anak kecil—!",
  ui_story_5084_50841101_26_dialog_content = "Darah mengalir di jalanan. Monster-monster berjubah ini... Mereka menyerang penduduk kota!",
  ui_story_5084_50841101_27_dialog_content = "May! Bersiaplah untuk bertempur!",
  ui_story_5084_50841101_28_dialog_content = "Seperti yang aku pikirkan... Sekarang bahwa Lady Victoria telah bertindak, takdir memperbolehkan kita untuk ikut campur.",
  ui_story_5084_50841101_29_dialog_content = "Terdengar bagus untukku! Saatnya menghukum beberapa anak-anak nakal!",
  ui_story_5084_50841101_30_dialog_content = "... Aku tidak merasakan sakit!",
  ui_story_5084_50841101_31_dialog_content = "Masih ada begitu banyak dari mereka...!",
  ui_story_5084_50841101_32_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_33_dialog_content = "Ibu—!!!!",
  ui_story_5084_50841101_34_dialog_content = "Jangan takut, domba kecilku yang tersesat... Darah Suci akan segera mengental dan membentuk...",
  ui_story_5084_50841101_35_dialog_content = "Ini kamu... Sang Inisiat! Tapi kenapa kamu menyakiti dirimu sendiri?!",
  ui_story_5084_50841101_36_dialog_content = "Anak kecil yang bodoh... Ini bukan kekuatanku, dan aku bukan yang disebut \"Inisiat\". Aku adalah Nails...",
  ui_story_5084_50841101_37_dialog_content = "Lord of Truth memberitahuku untuk tidak merasa kasihan atau penyesalan.",
  ui_story_5084_50841101_38_dialog_content = "Meski ibumu adalah seorang pendosa seperti diriku...",
  ui_story_5084_50841101_39_dialog_content = "Aku harus bertanggung jawab untuk semua orang berdosa!",
  ui_story_5084_50841101_40_dialog_content = "Apa... Apa ini...?",
  ui_story_5084_50841101_41_dialog_content = "Ini adalah dosa... Dan juga berkat...",
  ui_story_5084_50841101_42_dialog_content = "Ini adalah kekuatan dari Darah Suci... Kekuatan yang disebutkan oleh mentorku!",
  ui_story_5084_50841101_43_dialog_content = "Ini mendidih dengan kehidupan saat mengalir melalui pembuluh darahku, membakarku dengan kehangatan tak terbatas dari tuhan kita!",
  ui_story_5084_50841101_44_dialog_content = "Lihatlah, domba kecilku yang tersesat—",
  ui_story_5084_50841101_45_dialog_content = "Lord of Truth akan mengampuni dosa-dosa kita!",
  ui_story_5084_50841101_46_dialog_content = "…!",
  ui_story_5084_50841101_47_dialog_content = "Ini kamu... Inisiator dari sebelumnya hari ini! Kamu telah naik dan menjadi salah satu santo suci tuhan kita!",
  ui_story_5084_50841101_48_dialog_content = "Tidak... Tolong jangan sebut aku dengan cara itu... Aku hanya—",
  ui_story_5084_50841101_49_dialog_content = "Jubah yang kamu kenakan... Itu adalah jubah yang dibuat oleh ibu dan nenekku khusus untukmu.",
  ui_story_5084_50841101_50_dialog_content = "Berkat kamu dan keluargamu, saya bisa menjadi orang yang saya sekarang.",
  ui_story_5084_50841101_51_dialog_content = "Lord Wilhelm pasti memiliki alasan sendiri waktu itu... Tapi kamu pasti akan dipilih sebagai Inisiator tahun ini!",
  ui_story_5084_50841101_52_dialog_content = "Mentor saya telah menunjukkan kepada saya banyak kebenaran mulia, untuk itu saya sangat berterima kasih selamanya.",
  ui_story_5084_50841101_53_dialog_content = "Sekarang, tolong tinggalkan tempat ini sebelum bahaya kembali. Semua akan baik-baik saja, saya jamin.",
  ui_story_5084_50841101_54_dialog_content = "Sangat baik. May Semoga Truth memberkatimu sekarang dan selamanya, Santo Nails!",
  ui_story_5084_50841101_55_dialog_content = "May Semoga Truth memberkatimu, Saint Nails!",
  ui_story_5084_50841101_56_dialog_content = "May Semoga Truth memberkatimu juga.",
  ui_story_5084_50841101_57_dialog_content = "\"Santo Nails,\" huh?",
  ui_story_5084_50841101_58_dialog_content = "Kami melihatmu mengalahkan monster-monster itu dari kejauhan.",
  ui_story_5084_50841101_59_dialog_content = "Oh? May, Faust... Sudah cukup lama, bukan?",
  ui_story_5084_50841101_60_dialog_content = "Aku... Aku hanya senang kau baik-baik saja!",
  ui_story_5084_50841101_61_dialog_content = "PlayerName dan saya sangat khawatir tentang kamu!",
  ui_story_5084_50841101_62_dialog_content = "Ini salahku karena terlalu menilai kemampuanku... Aku membuatmu khawatir tanpa alasan... Dan untuk itu aku harus bertobat...",
  ui_story_5084_50841101_63_dialog_content = "Kekuatanmu barusan itu luar biasa! Apakah ini ada hubungannya dengan jubah ini?",
  ui_story_5084_50841101_64_dialog_content = "Mungkin... Selama tiga tahun terakhir, saya telah mengenakan jubah yang dibuat untuk saya oleh keluarga penjahit itu.",
  ui_story_5084_50841101_65_dialog_content = "Y-Kamu maksudnya kamu tidak pernah pergi ke tempat lain? Dengan kata lain... Kamu sudah duduk-duduk di Kota Varaki selama tiga tahun penuh?!",
  ui_story_5084_50841101_66_dialog_content = "Bukan hanya duduk-duduk saja, May, tapi berlatih di bawah bimbingan mentorku... Dia membawaku ke banyak tempat yang berbeda... Bukan hanya di kota saja.",
  ui_story_5084_50841101_67_dialog_content = "Mentor Anda...",
  ui_story_5084_50841101_68_dialog_content = "Apakah karena pelatihannya sehingga sekarang kamu bisa mengkondensasi dan membentuk ulang darahmu seperti ini?",
  ui_story_5084_50841101_69_dialog_content = "Memang... Mentor saya mengatakan bahwa Rare Blood saya sama sekali bukan kutukan...",
  ui_story_5084_50841101_70_dialog_content = "\"Di mana kamu kehilangan, di sini kamu mendapatkan. Di mana kamu menebus, di sini kamu diberkati.\"",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>Tiga tahun yang lalu...</color>",
  ui_story_5084_50841102_2_dialog_content = "O Lord of Truth, hamba rendah hati Nails memohon kepada-Mu untuk membebaskannya dari penderitaannya sekali lagi...",
  ui_story_5084_50841102_3_dialog_content = "Energi jahat meresap dalam darahku... Aku sudah lama siap untuk akhir...",
  ui_story_5084_50841102_4_dialog_content = "Apa ini...?",
  ui_story_5084_50841102_5_dialog_content = "Meski Lady Victoria pernah mengatakan bahwa ketakwaanku akan membimbingku... Aku merindukan pengorbanan...",
  ui_story_5084_50841102_6_dialog_content = "Aku akan...",
  ui_story_5084_50841102_7_dialog_content = "...",
  ui_story_5084_50841102_8_dialog_content = "... Tuanku?",
  ui_story_5084_50841102_9_dialog_content = "Kamu rupanya! Lord of Truth yang maha kuasa!",
  ui_story_5084_50841102_10_dialog_content = "Apakah kamu baru saja mengatakan... Lady Victoria?",
  ui_story_5084_50841102_11_dialog_content = "Aku hanyalah seorang pendosa yang tak tahu malu... Tapi kesalahanku tidak menyangkut Lady Victoria.",
  ui_story_5084_50841102_12_dialog_content = "Dia menerima dan memberkatiku dengan persahabatan dari True Order... Namun aku membalas kebaikannya dengan membiarkan darahku yang tercemar mencemari dunia ini.",
  ui_story_5084_50841102_13_dialog_content = "Jadi, Lady Victoria ini adalah pemimpin dari True Order, dan kamu adalah salah satu anggotanya?",
  ui_story_5084_50841102_14_dialog_content = "Ya, tuan ku... Nama saya adalah Nails.",
  ui_story_5084_50841102_15_dialog_content = "Apakah Anda satu-satunya di kripta ini?",
  ui_story_5084_50841102_16_dialog_content = "Tidak, tuanku. Saya ditemani oleh Lady Victoria, Faust, May, dan si Caelestite... Kami memasuki crypt bersama, tetapi segera terpisah setelahnya.",
  ui_story_5084_50841102_17_dialog_content = "Mereka berani, baik hati, dan penuh cahaya... Saya yakin Anda telah membimbing mereka ke tempat yang mereka butuhkan, tuanku...",
  ui_story_5084_50841102_18_dialog_content = "\"Untuk berfungsi sebagai pemandu bagi Truth...\"",
  ui_story_5084_50841102_19_dialog_content = "Kamu mengikuti jalanmu sendiri... Aku terkejut bahwa seorang Caelestite telah bergabung dengan True Order...",
  ui_story_5084_50841102_20_dialog_content = "\"Kebenaran telah menampakkan dirinya di hatinya dan memberkati dia. Dia adalah agen perubahan dalam True Order.\"",
  ui_story_5084_50841102_21_dialog_content = "Untuk diberkati oleh Truth...",
  ui_story_5084_50841102_22_dialog_content = "Apakah kamu ingin mengaku sesuatu kepada Lord of Truth?",
  ui_story_5084_50841102_23_dialog_content = "Aku mengaku... Bahwa aku telah berdosa sejak saat aku dilahirkan. Lihatlah sendiri, tuanku...",
  ui_story_5084_50841102_24_dialog_content = "Hanya makhluk berdosa seperti diriku ini yang akan dikutuk dengan darah yang begitu kotor...",
  ui_story_5084_50841102_25_dialog_content = "Sungguh kata-kata bodoh...",
  ui_story_5084_50841102_26_dialog_content = "T-Tuanku...?",
  ui_story_5084_50841102_27_dialog_content = "Matahari masih menyinari tanah ini. Saya punya waktu untuk mendengar masa lalu berdosa Anda.",
  ui_story_5084_50841102_28_dialog_content = "Tak perlu kau khawatirkan tindakanku, sekarang bicara.",
  ui_story_5084_50841102_29_dialog_content = "Aku hanya meminta agar kau menyimpan paku itu. Ini adalah makam Varaki, dan aku tidak akan membiarkanmu menumpahkan darahmu di dalamnya.",
  ui_story_5084_50841102_30_dialog_content = "Baik, Lord of Truth!",
  ui_story_5084_50841102_31_dialog_content = "Selain itu, aku bukan Lord of Truth.",
  ui_story_5084_50841102_32_dialog_content = "Tidak? Lalu siapa Anda—?",
  ui_story_5084_50841102_33_dialog_content = "Namaku Wilhelm Varaki, meskipun nama belakang itu hampir tidak cocok untuk seorang pria seperti saya.",
  ui_story_5084_50841102_34_dialog_content = "... \"Varaki\"?! Kamu berbagi nama belakang yang sama dengan Lady Victoria!",
  ui_story_5084_50841102_35_dialog_content = "\"Glorious,\" katamu? Heheh, itu tidak lebih dari nama yang digunakan untuk mengintimidasi orang lain.",
  ui_story_5084_50841102_36_dialog_content = "Orang yang kamu lihat di depanmu adalah seseorang dengan ikatan rumit dengan True Order, sebuah makhluk yang ada di luar aliran waktu.",
  ui_story_5084_50841102_37_dialog_content = "Sekarang katakan padaku, siapa yang melihatmu sebagai monster?",
  ui_story_5084_50841102_38_dialog_content = "Kakakku... Orang tuaku... Seluruh keluargaku...",
  ui_story_5084_50841102_39_dialog_content = "Dan ini semua karena \"Darah Langka\" yang disebut-sebut mengalir di pembuluh darahmu?",
  ui_story_5084_50841102_40_dialog_content = "Ya... Tapi juga karena keberadaan saya sendiri membawa malapetaka kepada kakak saya, dan memalukan keluarga saya.",
  ui_story_5084_50841102_41_dialog_content = "Saudaraku pernah menjadi anggota Ordo yang baik dan berani, sangat mirip dengan teman-temanku...",
  ui_story_5084_50841102_42_dialog_content = "Di masa lalu, tampaknya saya berada di jalan menuju kekayaan dan kemuliaan karena kekuatan saya, yang memungkinkan saya untuk mengalahkan banyak ksatria lain dalam duel.",
  ui_story_5084_50841102_43_dialog_content = "Namun, kakakku tidak begitu beruntung...",
  ui_story_5084_50841102_44_dialog_content = "Ketika putra dari keluarga saingan menyerangnya, saya mencoba melindunginya tanpa menyadari sejauh mana kekuatan saya sendiri...",
  ui_story_5084_50841102_45_dialog_content = "Dan akibatnya...!",
  ui_story_5084_50841102_46_dialog_content = "Kakakku yang malang... Dia tahu betapa memalukannya itu bagi keluarga kami... Jika seorang pendosa seperti aku terus hidup di kota yang murni dan mulia itu.",
  ui_story_5084_50841102_47_dialog_content = "Jadi dia memutuskan untuk membebaskan saya, membiarkan \"darah langka\" saya muncul dan kemudian... mengusir saya dari Lumopolis.",
  ui_story_5084_50841102_48_dialog_content = "Di mana saya pernah melihat itu sebelumnya...",
  ui_story_5084_50841102_49_dialog_content = "Lalu kamu berpindah-pindah sebelum Victoria merekrutmu ke dalam True Order?",
  ui_story_5084_50841102_50_dialog_content = "Ya, meski aku berharap untuk mati dalam perang antara Aurorian dan Eclipsite.",
  ui_story_5084_50841102_51_dialog_content = "Tapi Tuhan pasti menganggapku sebagai seorang pendosa, karena Rare Blood terus menarikku keluar dari koma berulang kali untuk mengingatkanku...",
  ui_story_5084_50841102_52_dialog_content = "Aku belum bertobat... Aku masih belum bisa kembali kepada Lord of Truth.",
  ui_story_5084_50841102_53_dialog_content = "...",
  ui_story_5084_50841102_54_dialog_content = "Apakah kamu sudah mengatakan terlalu banyak? Maaf, Pak Wilhelm, saya pikir, agak naif, bahwa saya telah dimaafkan dan kembali dalam rahmat baik Tuhan.",
  ui_story_5084_50841102_55_dialog_content = "Ceritamu terdengar seperti kamu lahir dari keluarga bangsawan dan sangat berbakat bagi saya.",
  ui_story_5084_50841102_56_dialog_content = "Tapi saudara lelakimu yang tidak cakap itu memiliki dendam terhadapmu dan ingin menjadi patriark, sehingga merencanakan untuk mengeliminasimu.",
  ui_story_5084_50841102_57_dialog_content = "Dia telah mengambil alih sebagai kepala keluarga sekarang, bukan?",
  ui_story_5084_50841102_58_dialog_content = "Oh, dia pantas mendapatkannya, dan ini bukan \"rencana untuk menghapus\".",
  ui_story_5084_50841102_59_dialog_content = "Nah, aku punya keraguan... Anak Kecil dari Lumopolis, baik hati, berani, optimis?",
  ui_story_5084_50841102_60_dialog_content = "Kepala kedua belas dari True Order adalah seorang bidah yang dijauhi oleh Lumopolis.",
  ui_story_5084_50841102_61_dialog_content = "Tanpa orang sesat itu, tidak akan ada True Order seperti sekarang.",
  ui_story_5084_50841102_62_dialog_content = "Memang, aku adalah orang sesat yang dijauhi oleh Lumopolis, tetapi saudaraku...",
  ui_story_5084_50841102_63_dialog_content = "Beritahu saya, emosi apa yang dia tunjukkan saat kamu pergi?",
  ui_story_5084_50841102_64_dialog_content = "...",
  ui_story_5084_50841102_65_dialog_content = "Saya yakin kamu tidak akan pernah lupa bagaimana dia melihatmu, orang yang dia usahakan untuk hancurkan, pergi ke pengasingan.",
  ui_story_5084_50841102_66_dialog_content = "Dia tersenyum dan mendoakan yang terbaik untukku.",
  ui_story_5084_50841102_67_dialog_content = "Heh, mereka selalu bisa menemukan sesuatu untuk menyalahkanmu, ketika mereka ingin menggertak atau menindasmu.",
  ui_story_5084_50841102_68_dialog_content = "Oleh karena itu, kamu berpikir bahwa kamu tidak dapat ditebus dan bergabung dengan True Order, sambil memegang rasa bersalah dan penyiksaan diri sendiri.",
  ui_story_5084_50841102_69_dialog_content = "Akar dari pertobatanmu adalah kebencian terhadap diri sendiri. Kamu membenci <color=#FFB400>Rare Blood</color>!",
  ui_story_5084_50841102_70_dialog_content = "Dan akar dari kebencianku adalah harapan yang kamu miliki untuk para pelaku kejahatan itu, yang telah berbicara buruk tentangmu namun kamu menganggap itu sebagai kebenaran.",
  ui_story_5084_50841102_71_dialog_content = "Biarkan aku katakan, Rare Blood bukanlah kutukan tetapi berkah dari Tuhan Truth.",
  ui_story_5084_50841102_72_dialog_content = "Fakta bahwa mereka membantu kamu membunuh Eclipsite adalah bukti. Jangan ragu tentang itu. Kamu tidak memiliki alasan untuk membenci diri sendiri.",
  ui_story_5084_50841102_73_dialog_content = "Dia tidak pantas menjadi saudaramu, Nails. Tapi yang menyedihkan adalah kamu adalah seorang saudara yang baik.",
  ui_story_5084_50841102_74_dialog_content = "Saudara mengkhianati dan berpisah satu sama lain... Takdir menentukan kita bertemu di sini, Wilhelm Varaki.",
  ui_story_5084_50841102_75_dialog_content = "Kamu benar-benar memastikan untuk mengejekku lagi!",
  ui_story_5084_50841102_76_dialog_content = "Dengarkan dengan saksama, Nails. Kamu baik dan berani, tetapi sedikit kurang manis. Bagaimana dengan Hails? Itu mirip dengan namamu.",
  ui_story_5084_50841102_77_dialog_content = "Kamu akan merasakan keselamatan sejati jika kamu memilih untuk melindungi orang lain dengan Rare Blood-mu.",
  ui_story_5084_50841102_78_dialog_content = "Kamu sangat berani merasa seperti itu, tapi aku...",
  ui_story_5084_50841102_79_dialog_content = "Kamu bisa mengatasinya—",
  ui_story_5084_50841102_80_dialog_content = "...",
  ui_story_5084_50841102_81_dialog_content = "Tuhan tidak memihak siapa pun. Jika Anda tidak bisa memaafkan diri sendiri, bagaimana Dia bisa menebus Anda?",
  ui_story_5084_50841102_82_dialog_content = "Ingat, hanya ketika kamu mengakui dirimu sendiri, Tuhan akan mengakui kamu.",
  ui_story_5084_50841102_83_dialog_content = "Mengapa kamu mengatakan semua ini kepadaku, Pak Wilhelm?",
  ui_story_5084_50841102_84_dialog_content = "Karena saya tahu pertemuan kita di sini telah mengubah sesuatu untuk selamanya.",
  ui_story_5084_50841102_85_dialog_content = "Saya yakin teguh itu adalah Tuan yang mengirimkanmu ke sini.",
  ui_story_5084_50841102_86_dialog_content = "Jadi ini bukan akhir bagi kamu, Nails, tapi awal dari pengabdianmu. Maukah kamu belajar bersamaku?",
  ui_story_5084_50841102_87_dialog_content = "Aku akan melakukan apa saja untuk membersihkan diri dari dosa-dosa.",
  ui_story_5084_50841102_88_dialog_content = "Bagus. Mari kita mulai. Kita memiliki banyak yang harus dilakukan, tetapi tidak di sini.",
  ui_story_5084_50841102_89_dialog_content = "Inilah di mana masa lalu berakhir, dan tiga tahun penanamanmu dimulai dari kedatangan Kebenaran saat kedatanganmu.",
  ui_story_5084_50841102_90_dialog_content = "Pemimpinmu telah kembali ke sana. Berbaringlah di dalam peti di belakangku dan kenanglah Advent of Truth di Varaki, di mana kamu akan menemukan rekan-rekanmu.",
  ui_story_5084_50841102_91_dialog_content = "Ketika kamu membuka mata lagi, temui aku di Advent of Truth. Aku akan memastikan kamu diinisiasi dan menerima berkat dari Truth.",
  ui_story_5084_50841102_92_dialog_content = "Bagaimana cara saya bisa ke sana?",
  ui_story_5084_50841102_93_dialog_content = "Melalui imanmu, Nails.",
  ui_story_5084_50841102_94_dialog_content = "Ini imanmu yang membawamu ke sini. Rasakan saja dengan tubuhmu.",
  ui_story_5084_50841102_95_dialog_content = "Ketika kamu terlahir kembali dengan berkah atau perayaan apapun, kamu telah menemukan Truth.",
  ui_story_5084_50841102_96_dialog_content = "Apakah kamu merujuk pada keyakinan...?",
  ui_story_5084_50841102_97_dialog_content = "Ya. Mulai sekarang, saya adalah mentor Anda.",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>At the entrance to a tailor's shop in Varaki Town</color>",
  ui_story_5084_50841102_99_dialog_content = "Bagaimana aku bisa ada di sini?",
  ui_story_5084_50841102_100_dialog_content = "Are you here for the ceremonial robe, sir?",
  ui_story_5084_50841102_101_dialog_content = "Ceremonial robe...?",
  ui_story_5084_50841102_102_dialog_content = "Tak heran kau berbicara dalam kata-kata yang tak kami mengerti... Kau sudah lama mengenal Mr. Wilhelm, ya, aku lihat.",
  ui_story_5084_50841102_103_dialog_content = "Dan yang lebih misterius lagi.",
  ui_story_5084_50841102_104_dialog_content = "Aku tidak percaya aku benar-benar berpikir aku dipilih untuk inisiasi... dan benar-benar masuk ke aula dengan ide itu.",
  ui_story_5084_50841102_105_dialog_content = "Aku masih tidak bisa percaya semua yang terjadi padaku. Aku bahkan tidak tahu kapan pertama kali aku melihat mentorku.",
  ui_story_5084_50841102_106_dialog_content = "Tapi ketika dia mengirimku kembali ke Advent of Truth, pria itu tidak mengenali saya...",
  ui_story_5084_50841102_107_dialog_content = "Lalu apa, Nails? Apa yang terjadi setelah Wilhelm mengusirmu dari gereja?",
  ui_story_5084_50841102_108_dialog_content = "...",
  ui_story_5084_50841102_109_dialog_content = "Oh, semoga semua darah berdosa mengalir keluar dari diriku... Aku tidak akan pernah berdoa untuk penebusan dari Tuhan lagi...",
  ui_story_5084_50841102_110_dialog_content = "Aku adalah pendosa... Dosa-dosa yang tak bisa diampuni...",
  ui_story_5084_50841102_111_dialog_content = "Aku adalah monster yang membawa malapetaka untuk semua, bahkan di sini.",
  ui_story_5084_50841102_112_dialog_content = "Dalam buru-buru saya menuju Advent of Truth, saya mengecewakan penjahit dan putrinya.",
  ui_story_5084_50841102_113_dialog_content = "Mereka kehilangan kesempatan untuk mencari nafkah karena bertemu denganku...",
  ui_story_5084_50841102_114_dialog_content = "Orang-orang itu melihat jelas melaluiku, tidak menyetujui inisiasiku dan malah ingin membunuhku...",
  ui_story_5084_50841102_115_dialog_content = "Saya bukan seorang pemula... Saya yang harus disalahkan atas masalah antara mentor saya dan Ordo.",
  ui_story_5084_50841102_116_dialog_content = "Kemanapun aku pergi, aku selalu dihindari...",
  ui_story_5084_50841102_117_dialog_content = "Ahhhh!",
  ui_story_5084_50841102_118_dialog_content = "Tangan dan kakiku mulai mati rasa... Dingin yang baru saja kurasakan kini menjadi kehangatan yang selama ini kucari...",
  ui_story_5084_50841102_119_dialog_content = "Mungkin juga...",
  ui_story_5084_50841102_120_dialog_content = "Aku akan mati dalam diam dengan dosa-dosaku. Tidak ada lagi masalah untuk dunia.",
  ui_story_5084_50841102_121_dialog_content = "Aku…",
  ui_story_5084_50841102_122_dialog_content = "Saya sedang merenung apakah saya tidak membuat diri saya jelas.",
  ui_story_5084_50841102_123_dialog_content = "…?",
  ui_story_5084_50841102_124_dialog_content = "Mengapa Anda sangat membenci hadiah luar biasa seperti Rare Blood?",
  ui_story_5084_50841102_125_dialog_content = "Mentor? Mentor saya! Kamu baik-baik saja!",
  ui_story_5084_50841102_126_dialog_content = "Jangan bergerak. Mari kita lihat lukamu.",
  ui_story_5084_50841102_127_dialog_content = "Itu aku yang kamu temui, tapi bukan aku yang asli atau aku saat ini.",
  ui_story_5084_50841102_128_dialog_content = "Aku telah mengamati kejadian-kejadian sepanjang waktu dan masih tidak bisa menentukan apa yang membuatmu bersalah.",
  ui_story_5084_50841102_129_dialog_content = "Aku yakin kamu bisa melihat bahwa ada monster di dalam diriku...",
  ui_story_5084_50841102_130_dialog_content = "Monster? Bahkan diriku di masa lalu bisa mengakui betapa sangat kuatnya kamu dan bahwa kamu ditakdirkan untuk bersama dengan True Order.",
  ui_story_5084_50841102_131_dialog_content = "Kamu harus tahu bahwa masa depan yang saya lihat untuk Ordo adalah kumpulan orang-orang yang eksentrik namun anggun, masuk akal namun bijaksana.",
  ui_story_5084_50841102_132_dialog_content = "Selama kamu terus mengungkap keunikan dirimu sendiri, waktu akan membawamu ke tempat yang tepat dan orang-orang yang tepat.",
  ui_story_5084_50841102_133_dialog_content = "Aku sudah bilang, kamu belajar bersamaku. Semua yang telah kamu alami juga merupakan bagian dari proses itu.",
  ui_story_5084_50841102_134_dialog_content = "Saya melihat kamu tidak menganggap saya serius dan mencoba bunuh diri karena rasa bersalah.",
  ui_story_5084_50841102_135_dialog_content = "Hukum aku, tolong... Aku tidak menepati janji yang aku buat padamu, mentorku...",
  ui_story_5084_50841102_136_dialog_content = "Tidak apa-apa. Kamu telah dihina, yang membuatmu tersesat dari jalur. Bukan salahmu.",
  ui_story_5084_50841102_137_dialog_content = "Tapi sekarang setelah kamu berada di tempat yang tepat, kamu harus bersinar dengan kemampuan unikmu.",
  ui_story_5084_50841102_138_dialog_content = "Aku...?",
  ui_story_5084_50841102_139_dialog_content = "Pikirkan dengan baik. Mengesampingkan semua orang lain, apakah Rare Blood pernah mencoba menyakiti kamu di waktu apa pun?",
  ui_story_5084_50841102_140_dialog_content = "...",
  ui_story_5084_50841102_141_dialog_content = "Kemakmuran yang membuat orang beruntung jatuh dari anugerah mungkin adalah apa yang akan menyelamatkan orang yang tergusur.",
  ui_story_5084_50841102_142_dialog_content = "Kaulah yang telah merusak jiwamu dengan dosa-dosa orang lain, sehingga mengabaikan hal yang mencoba menyelamatkanmu dan mereka.",
  ui_story_5084_50841102_143_dialog_content = "Mengapa kamu tidak percaya Rare Blood bisa membunuh monster dan menyelamatkan orang lain?",
  ui_story_5084_50841102_144_dialog_content = "Mereka akan menghindariku... membenci...",
  ui_story_5084_50841102_145_dialog_content = "Mereka lagi... Dengar, gagasan itu milik masa lalu. Jangan tertipu oleh itu lagi.",
  ui_story_5084_50841102_146_dialog_content = "Mengutip kata-katamu, \"Aku akan melakukan apa saja untuk membersihkan diriku dari dosa.\" Maka langkah pertama adalah percaya bahwa kamu tidak memiliki dosa.",
  ui_story_5084_50841102_147_dialog_content = "Bisa kamu lakukan itu?",
  ui_story_5084_50841102_148_dialog_content = "Wilhelm...",
  ui_story_5084_50841102_149_dialog_content = "Ya, aku tahu kamu pasti cukup pintar untuk mendapatkan itu.",
  ui_story_5084_50841102_150_dialog_content = "Ikuti saya kembali ke tempat tinggal saya. Tempatnya benar-benar terpencil.",
  ui_story_5084_50841102_151_dialog_content = "Dari sana, kamu bisa mencapai banyak kota untuk mencari dan membantu domba yang tersesat.",
  ui_story_5084_50841102_152_dialog_content = "Selamatkan mereka dengan kekuatanmu. Bimbing mereka untuk pujian mereka terhadap Rare Blood.",
  ui_story_5084_50841102_153_dialog_content = "Darah Langka diberkati oleh The Truth. Seiring waktu, kamu akan dapat memahaminya melalui meditasi.",
  ui_story_5084_50841102_154_dialog_content = "Aku paham…",
  ui_story_5084_50841102_155_dialog_content = "Jadi, selama tiga tahun terakhir ini, aku telah berkeliaran, menahan amarahku dan mendengarkan apa yang dikatakan orang lain.",
  ui_story_5084_50841102_156_dialog_content = "Saya menyadari Rare Blood saya perlahan berubah setelah menyembuhkan rasa sakit orang lain.",
  ui_story_5084_50841102_157_dialog_content = "Tetapi baru setelah saya membantu penjahit dan putrinya beberapa saat yang lalu, saya menyadari bahwa tiga tahun itu dihabiskan dengan baik.",
  ui_story_5084_50841102_158_dialog_content = "Dalam semua tahun ini bersama True Order, aku tidak akan mendengarkan dan hanya mengulangi pertobatanku.",
  ui_story_5084_50841102_159_dialog_content = "Aku adalah mentorku yang menemukan akar dosa-dosaku. Aku terlalu sibuk berbicara untuk mendengar The Truth.",
  ui_story_5084_50841102_160_dialog_content = "Kata-kata negatifku membentuk pikiranku dan memperdalam rasa bersalahku...",
  ui_story_5084_50841102_161_dialog_content = "Aku tidak tahu apa sebenarnya \"The Truth\". Itulah sebabnya ia menolak untuk muncul dalam diriku.",
  ui_story_5084_50841102_162_dialog_content = "Sekarang aku menyadari bahwa Truth telah menjadi bagian dari keyakinanku sejak awal.",
  ui_story_5084_50841102_163_dialog_content = "Seperti rasa sakit, Truth tidak pernah menunjukkan prasangka terhadap siapa pun.",
  ui_story_5084_50841102_164_dialog_content = "Apa pun yang saya hilangkan, saya seharusnya kehilangan. Apa pun yang saya peroleh, saya seharusnya mendapatkan.",
  ui_story_5084_50841102_165_dialog_content = "Seseorang harus melakukan dosa untuk bertobat. Berkat dari murid-murid memungkinkan saya untuk diurapi oleh Darah Suci.",
  ui_story_5084_50841102_166_dialog_content = "Sejujurnya, saya tidak mengerti setengah dari apa yang Anda katakan, Pak Nails...",
  ui_story_5084_50841102_167_dialog_content = "Tapi aku merasa diberi kenyamanan oleh sikapmu seolah-olah aku baru saja mandi air hangat.",
  ui_story_5084_50841102_168_dialog_content = "Mentorku lah yang membuatku percaya bahwa Rare Blood bukanlah dosa melainkan suci, karena Tuhan dari Truth selalu bersamaku setiap saat.",
  ui_story_5084_50841102_169_dialog_content = "Lady Victoria akan senang mengetahui perubahan dalam dirimu.",
  ui_story_5084_50841102_170_dialog_content = "Tapi aku tidak tahu bagaimana keadaan dia sekarang.",
  ui_story_5084_50841102_171_dialog_content = "Aku percaya pada Lady Victoria! Lebih penting lagi, aku percaya aku bisa sangat membantu dia!",
  ui_story_5084_50841102_172_dialog_content = "Mentorku telah menunda pelatihanku. Aku perlu melakukan sesuatu yang penting untuk True Order dengan kekuatanku.",
  ui_story_5084_50841102_173_dialog_content = "Ayo, aku ingin membawa kegembiraanku kepada Lady Victoria serta lebih banyak murid lagi.",
  ui_story_5084_50841201_1_dialog_content = "Bahkan jika tidak ada orang lain yang naik kereta api saya lagi, saya berjanji akan meyakinkan Ayah untuk membawa Anda dalam perjalanan ke Astra.",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>Ciprat, ciprat....</color>",
  ui_story_5084_50841201_3_dialog_content = "Tunggu sebentar, biar aku menutup jendela.",
  ui_story_5084_50841201_4_dialog_content = "Woah!",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5084_50841201_6_dialog_content = "Itu aneh. Cacing-cacing menjijikkan ini akhir-akhir ini sering terlihat di sini...",
  ui_story_5084_50841201_7_dialog_content = "Tapi Ayah hanya menyuruhku menutup jendela dan tidak ada yang lain. Aku bahkan tidak tahu di mana dia sekarang.",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>Bulan berdarah menggantung tinggi di atas Kota Varaki seperti jam abadi, berdentang untuk Kedatangan Kebenaran pada tengah malam.</color>",
  ui_story_5084_50841201_9_dialog_content = "Ini benar-benar tidak nyata. Mengapa ini tidak bisa terjadi setiap hari dalam hidupku...?",
  ui_story_5084_50841201_10_dialog_content = "Apakah kamu merujuk pada pengangkatan pemimpin baru untuk True Order? Ada sebutan tentang seseorang yang dibunuh tidak lama yang lalu.",
  ui_story_5084_50841201_11_dialog_content = "Bukan hal yang tidak biasa bagi kepemimpinan untuk berubah. Tetapi saya lebih khawatir tentang bagaimana mereka yang berkuasa selalu mengecualikan setiap orang yang bukan keturunan Varaki.",
  ui_story_5084_50841201_12_dialog_content = "Mungkin cahaya bulan berdarah ini hanya bersinar pada garis keturunan itu.",
  ui_story_5084_50841201_13_dialog_content = "Tidak pernah menjadi tugas kita untuk sampai ke peti mati di Balai Kebenaran dan mendengarkan ceramah Tuhan.",
  ui_story_5084_50841201_14_dialog_content = "Jangan terjebak dalam teori konspirasi garis keturunan. Sang Lord menolak putri tertua dari Varakis tiga tahun lalu.",
  ui_story_5084_50841201_15_dialog_content = "Dan memilih pengikut lain dalam kesendirian. Dia sekarang adalah seorang santo dan menebus orang lain melalui kekuatan Tuhan.",
  ui_story_5084_50841201_16_dialog_content = "Dikatakan dia bukan dari sini. Mungkin The Truth bisa berkembang di luar Kota Varaki.",
  ui_story_5084_50841201_17_dialog_content = "Ini memang memotivasi. Kepala kota tampaknya juga menghadapi reformasi.",
  ui_story_5084_50841201_18_dialog_content = "Jika malam ini adalah Porfirio, True Order akan menghadapi kesulitan ke depan...",
  ui_story_5084_50841201_19_dialog_content = "Dunia sedang berubah, dan begitu juga dengan Truth. May semoga memberkati rumah kita.",
  ui_story_5084_50841201_20_dialog_content = "Masih tidak ada tanda-tanda dari Lady Victoria dan PlayerName... Saya harap tidak ada yang terjadi pada mereka.",
  ui_story_5084_50841201_21_dialog_content = "Lady Victoria tidak pernah ingkar janji. Mungkin sekarang terlalu ramai, dan dia akan menunjukkannya setelah murid-muridnya bubar.",
  ui_story_5084_50841201_22_dialog_content = "Tidak. Melihat situasinya, saya tidak berpikir dia punya alasan untuk bersembunyi.",
  ui_story_5084_50841201_23_dialog_content = "PlayerName juga hadir, dan harus menonjol di kerumunan.",
  ui_story_5084_50841201_24_dialog_content = "Tuan Faust benar! Firasatku mengatakan kalau aku akan menyaksikan keajaiban True Order malam ini!",
  ui_story_5084_50841201_25_dialog_content = "Apa cerita yang akan saya miliki untuk Lenore!",
  ui_story_5084_50841201_26_dialog_content = "Meskipun ada pembunuhan berantai baru-baru ini di kota, para pengikut masih datang untuk acara tersebut.",
  ui_story_5084_50841201_27_dialog_content = "Saya rasa itu adalah tradisi Ordo Sejati yang berlanjut hingga Kalender Pagi 2000 untukmu.",
  ui_story_5084_50841201_28_dialog_content = "Saya akan tetap waspada dan memastikan semua murid tetap aman sepanjang upacara.",
  ui_story_5084_50841201_29_dialog_content = "Sudah cukup lama, dan Lady Victoria masih belum ada di sini.",
  ui_story_5084_50841201_30_dialog_content = "Apakah kamu melihat gadis Varaki itu ada di upacara?",
  ui_story_5084_50841201_31_dialog_content = "Ya, dan mengenakan pakaian mewah juga... Itu melanggar aturan True Order!",
  ui_story_5084_50841201_32_dialog_content = "(Apakah dia kembali dan berubah? Di mana dia?)",
  ui_story_5084_50841201_33_dialog_content = "Selalu ada masalah antara dia dan pamannya. Sangat normal baginya untuk tidak mengikuti aturan.",
  ui_story_5084_50841201_34_dialog_content = "Apakah Varakis akan mengganti pemimpin?",
  ui_story_5084_50841201_35_dialog_content = "Tidak mungkin... Saya dengar Lady Victoria kembali khusus untuk memimpin True Order.",
  ui_story_5084_50841201_36_dialog_content = "Benarkah? Tapi dalam Perayaan Kebenaran tiga tahun yang lalu, bukankah dia...",
  ui_story_5084_50841201_37_dialog_content = "Siapa yang tahu? Dia lah yang masuk ke dalam peti mati, bukan kita.",
  ui_story_5084_50841201_38_dialog_content = "Aku tidak bisa menjelaskan ini, tapi sudah ratusan tahun dan aku lebih nyaman dengan Varaki yang memimpin True Order.",
  ui_story_5084_50841201_39_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_5084_50841201_40_dialog_content = "Wow... Apakah kamu sengaja berganti pakaian menjadi sesuatu yang sesuai dengan acara ini?",
  ui_story_5084_50841201_41_dialog_content = "Tidak sepenuhnya. Gaun ini adalah hadiah dari mereka yang masih merindukan Varakis dan tahu saya ada di kota.",
  ui_story_5084_50841201_42_dialog_content = "Sesuatu yang sebaik ini tidak bisa dikerjakan oleh satu atau dua orang dalam waktu yang singkat.",
  ui_story_5084_50841201_43_dialog_content = "Mungkin pihak yang terlibat mencoba menyuarakan penolakan mereka terhadap kabal pemimpin yang kuat melalui ini.",
  ui_story_5084_50841201_44_dialog_content = "Jadi, untuk menghargai usaha mereka dan menunjukkan bahwa kamu memiliki apa yang dibutuhkan untuk memimpin Order...",
  ui_story_5084_50841201_45_dialog_content = "Haruskah kamu memakai ini untuk upacara malam ini?",
  ui_story_5084_50841201_46_dialog_content = "Otoritas tidak ada hubungannya dengan pakaian. Saya bisa menunjukkan kekuatan saya dalam kostum apa pun, tua atau baru.",
  ui_story_5084_50841201_47_dialog_content = "Tapi perubahan-perubahan yang menarik juga persis apa yang telah hilang dari kota bersejarah ini.",
  ui_story_5084_50841201_48_dialog_content = "Seperti Bloody Bible, cincin, dan bulan darah, semuanya adalah cara untuk menandai momen yang orang percaya penting.",
  ui_story_5084_50841201_49_dialog_content = "Jika para pemimpin membenci perubahan yang begitu mencolok, maka itulah yang akan saya tunjukkan kepada mereka.",
  ui_story_5084_50841201_50_dialog_content = "Karena bagi mereka, seorang wanita yang mengadopsi citra yang mencolok berarti mengucapkan selamat tinggal pada masa lalunya yang patuh.",
  ui_story_5084_50841201_51_dialog_content = "Ya. Saya hanya ingin mengatakan bahwa pakaian itu sangat cocok untukmu.",
  ui_story_5084_50841201_52_dialog_content = "PlayerName! PlayerName!",
  ui_story_5084_50841201_53_dialog_content = "Kamu rupanya!",
  ui_story_5084_50841201_54_dialog_content = "Ya, dia adalah Lady Victoria, seseorang yang bisa saya temukan di kerumunan mana pun!",
  ui_story_5084_50841201_55_dialog_content = "Aku tidak percaya itu kamu ketika aku melihatmu dari kejauhan.",
  ui_story_5084_50841201_56_dialog_content = "Bagaimana penampilanku?",
  ui_story_5084_50841201_57_dialog_content = "Ini Lady Victoria! Dan lebih mempesona dari sebelumnya!",
  ui_story_5084_50841201_58_dialog_content = "Sepertinya semuanya baik-baik saja denganmu, Lady Victoria. Selamat.",
  ui_story_5084_50841201_59_dialog_content = "Nails mengalami perubahan besar, saya lihat.",
  ui_story_5084_50841201_60_dialog_content = "Sudah lama sekali, Lady Victoria! Saya berterima kasih kepada mentorku atas hasilnya...",
  ui_story_5084_50841201_61_dialog_content = "Ada begitu banyak yang ingin kukatakan padamu!",
  ui_story_5084_50841201_62_dialog_content = "Ya, aku melihatmu di jalan. Saya menantikan untuk mendengarnya nanti.",
  ui_story_5084_50841201_63_dialog_content = "Sudah hampir waktunya.",
  ui_story_5084_50841201_64_dialog_content = "Tapi kami baru saja melihat mayat hidup melukai orang-orang, Lady Victoria...",
  ui_story_5084_50841201_65_dialog_content = "Sekarang saya tahu apa isi rumor terbaru di kota tentang Black Rider.",
  ui_story_5084_50841201_66_dialog_content = "Ayo, pengikut di jalanan. Wilhelm akan memastikan mereka aman.",
  ui_story_5084_50841201_67_dialog_content = "True Order harus menunjukkan kekuatannya malam ini. Ikuti aku ke gereja.",
  ui_story_5084_50841201_68_dialog_content = "Ya!",
  ui_story_5084_50841201_69_dialog_content = "May Semoga Truth selamanya memberkati True Order.",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>Kriek!</color>",
  ui_story_5084_50841201_71_dialog_content = "Mereka…",
  ui_story_5084_50841201_72_dialog_content = "Semua di tanah seolah-olah...",
  ui_story_5084_50841201_73_dialog_content = "...",
  ui_story_5084_50841201_74_dialog_content = "Mereka sudah berhenti bernapas, Lady Victoria.",
  ui_story_5084_50841201_75_dialog_content = "…!",
  ui_story_5084_50841201_76_dialog_content = "Biarkan aku mencoba membantu mereka... Aku bersedia menanggung rasa sakit untuk mereka.",
  ui_story_5084_50841201_77_dialog_content = "Hei, saya melihat kepala keluarga Varaki dan minion-minionnya akhirnya ada di sini.",
  ui_story_5084_50841201_78_dialog_content = "Ini adalah perayaan True Order, bagaimana saya bisa tidak hadir?",
  ui_story_5084_50841201_79_dialog_content = "Lady Victoria...",
  ui_story_5084_50841201_80_dialog_content = "...",
  ui_story_5084_50841201_81_dialog_content = "Gram terluka di banyak tempat...",
  ui_story_5084_50841201_82_dialog_content = "Itu adalah konsekuensi dari mengkhianati saya.",
  ui_story_5084_50841201_83_dialog_content = "Apa pun yang kamu lakukan tidak masalah... hanya jangan sakiti Charon dan istrinya...",
  ui_story_5084_50841201_84_dialog_content = "Menyakiti orang-orang di Aula Kebenaran...",
  ui_story_5084_50841201_85_dialog_content = "Tetap di tempat Anda berada, Varaki!",
  ui_story_5084_50841201_86_dialog_content = "Apa-apaan kau…!",
  ui_story_5084_50841201_87_dialog_content = "Dapatkan di belakangku, May.",
  ui_story_5084_50841201_88_dialog_content = "Kamu pasti telah lupa banyak aturan untuk vampir. Aku akan membiarkan Abraham menjelaskan kepadamu aturan mana saja yang telah kamu langgar...",
  ui_story_5084_50841201_89_dialog_content = "Kamu seharusnya tidak kembali, Victoria...",
  ui_story_5084_50841201_90_dialog_content = "Bahkan kamu pun tidak bisa berbuat apa-apa tentang itu, sekarang setelah ritual selesai. Semua \"pengorbanan\" untuk Tuhan telah dilakukan.",
  ui_story_5084_50841201_91_dialog_content = "Sekarang, saya hanya mengajarkan anak-anak kecil saya untuk tidak membuang-buang makanan.",
  ui_story_5084_50841201_92_dialog_content = "Aurorian adalah hadiah dari Lord of Truth. Apakah kamu pikir mereka adalah makanan?",
  ui_story_5084_50841201_93_dialog_content = "Oh, wanita dari Varaki, bukankah kamu mengirim orang-orangmu untuk mendapatkan darah segar untukmu ketika kamu juga merasa haus di tengah malam?",
  ui_story_5084_50841201_94_dialog_content = "Saya sendiri tidak menyia-nyiakan satu tetes pun pengorbanan yang menjadi milikku.",
  ui_story_5084_50841201_95_dialog_content = "Tapi hal yang sama tidak bisa dikatakan untuk Abraham, yang tidak hanya membuang-buang bagian miliknya tetapi juga berbohong padaku!",
  ui_story_5084_50841201_96_dialog_content = "!",
  ui_story_5084_50841201_97_dialog_content = "Hentikan, Porfirio... Berhenti!",
  ui_story_5084_50841201_98_dialog_content = "Dimana Wilhelm?!",
  ui_story_5084_50841201_99_dialog_content = "Berhenti, David Porfirio!",
  ui_story_5084_50841201_100_dialog_content = "Jadi, sekarang kamu yang mengambil keputusan?",
  ui_story_5084_50841201_101_dialog_content = "Bawalah ke sini.",
  ui_story_5084_50841201_102_dialog_content = "Yes, Lady Victoria.",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5084_50841201_104_dialog_content = "Apa yang kamu lakukan, Vine?",
  ui_story_5084_50841201_105_dialog_content = "Saya hanya mengikuti perintah Miss Varaki untuk mengantarkan peti parade kepada Anda, Lord Porfirio.",
  ui_story_5084_50841201_106_dialog_content = "Jangan bilang kamu pikir sisa-sisa leluhur Varaki akan menakutkanku.",
  ui_story_5084_50841201_107_dialog_content = "Atau kamu mencoba melarikan diri dengan trik yang sama yang digunakan Wilhelm Varaki?",
  ui_story_5084_50841201_108_dialog_content = "Ini Wilhelm di dalam peti mati.",
  ui_story_5084_50841201_109_dialog_content = "…?",
  ui_story_5084_50841201_110_dialog_content = "Kamu sudah melukainya tanpa ampun seperti ini dan kamu masih menginginkan lebih?",
  ui_story_5084_50841201_111_dialog_content = "Yah, kesabaranku tinggal seujung benang saja...",
  ui_story_5084_50841201_112_dialog_content = "Setelah aku selesai dengan darah di botol ini, aku pikir aku mungkin harus menghisap darahmu.",
  ui_story_5084_50841201_113_dialog_content = "Mendekatlah dan ceritakan apa rencana kalian berdua dengan Wilhelm.",
  ui_story_5084_50841201_114_dialog_content = "Wilhelm sudah mati.",
  ui_story_5084_50841201_115_dialog_content = "Pembohong!",
  ui_story_5084_50841201_116_dialog_content = "Hati-hati, Victoria!",
  ui_story_5084_50841201_117_dialog_content = "Langkahi dulu mayatku!",
  ui_story_5084_50841201_118_dialog_content = "Ini bukan hal baru bagi seseorang yang mencoba membangun sebuah kelompok di sekitar Truth, tetapi jarang bagi kalian minion untuk melindungi atasan kalian seperti ini.",
  ui_story_5084_50841201_119_dialog_content = "Jangan anggap aku bodoh, bagaimanapun. Aku melihat kalian berdua membunuh Viper dan Gold Rush.",
  ui_story_5084_50841201_120_dialog_content = "Apakah kamu ketakutan? Viper dan Gold Rush, serta semua konspirator, akan mati oleh pedangnya.",
  ui_story_5084_50841201_121_dialog_content = "Jadi, tidak peduli bagaimana kamu mencoba menyiksa, membunuh, atau mengubur Wilhelm Varaki, kamu tidak akan pernah bisa membunuhnya.",
  ui_story_5084_50841201_122_dialog_content = "Wilhelm... tidak mati? Dia masih hidup...?",
  ui_story_5084_50841201_123_dialog_content = "...",
  ui_story_5084_50841201_124_dialog_content = "Belum mati... jadi Varaki bisa menjadi arwah setelah mati?",
  ui_story_5084_50841201_125_dialog_content = "Tidak ada roh di dunia ini! Revenant hanya menjadi apa adanya setelah menyerap kekuatan Porfirio.",
  ui_story_5084_50841201_126_dialog_content = "Inilah kekuatanku atas para revenant... Satu-satunya dalam sejarah rumah vampir!",
  ui_story_5084_50841201_127_dialog_content = "Jangan bercanda tentang itu, ini bukan kebangkitan. Tidak mungkin.",
  ui_story_5084_50841201_128_dialog_content = "Kamu pikir kekuatan yang dimiliki oleh Varakis hanyalah hadiah leluhur yang digunakan untuk melihat ke masa depan?",
  ui_story_5084_50841201_129_dialog_content = "…?",
  ui_story_5084_50841201_130_dialog_content = "Baru saja, aku membuat pact dengan Bloody Bible untuk persetujuannya sebagai pemimpin The True Order.",
  ui_story_5084_50841201_131_dialog_content = "Murid-murid membungkuk dan kembali kepada Truth dengan pujian yang taat...",
  ui_story_5084_50841201_132_dialog_content = "Saya seharusnya tahu sekarang bahwa pemilihan Varaki hanyalah cara Varakis untuk mempertahankan kekuasaan mereka.",
  ui_story_5084_50841201_133_dialog_content = "Aku, Porfirio, seharusnya sudah lama mendapatkan kehormatan dan memikul tugas mengembalikan Order kepada pengikut.",
  ui_story_5084_50841201_134_dialog_content = "Vampir adalah penguasa darah dan malam. Mengapa saya harus melayani makhluk cahaya?",
  ui_story_5084_50841201_135_dialog_content = "Gelar itu seharusnya milikku, dan aku akan menguasai rakyat sesuai dengan keinginan leluhur. Itulah yang diungkapkan Bloody Bible kepadaku!",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>Pertarungan liar dan tak berpikir itu mengarah pada peti yang terbalik untuk disaksikan oleh semua yang hadir...</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>Sebuah Bloody Bible baru mendarat di kaki Victoria... seperti yang ditakdirkan.</color>",
  ui_story_5084_50841301_3_dialog_content = "Truth ingin menyelesaikan pembangunan jalan menuju penebusan, dan tampaknya ia lebih memilihku sebagai wakilnya.",
  ui_story_5084_50841301_4_dialog_content = "Calamity Codex, manifestasikan!",
  ui_story_5084_50841301_5_dialog_content = "...",
  ui_story_5084_50841301_6_dialog_content = "Apa maksudnya itu?",
  ui_story_5084_50841301_7_dialog_content = "Codex kenabian memberikanmu kilasan tentang masa depan, tetapi kamu gagal memanfaatkannya sambil tersandung-sandung seperti bayi yang sedang belajar berjalan.",
  ui_story_5084_50841301_8_dialog_content = "Codex ini, yang dibaptis di Sungai Pristine, tahu semua... Dia adalah Maha Mengetahui.",
  ui_story_5084_50841301_9_dialog_content = "Chapter baru telah terungkap, dan saya akan membalik halaman ini!",
  ui_story_5084_50841301_10_dialog_content = "Apakah kau ingin menyaksikan wahyu tentang kapan kau dilahirkan, kapan kau akan mati, dan kapan kau akan bertobat?",
  ui_story_5084_50841301_11_dialog_content = "…!",
  ui_story_5084_50841301_12_dialog_content = "Sisanya dari kalian pemimpin klan yang bersekongkol dengan Porfirio, dengarkan.",
  ui_story_5084_50841301_13_dialog_content = "Master dari ketiga dari dua belas Great Houses, Porifiro..",
  ui_story_5084_50841301_14_dialog_content = "Telah jatuh ke dalam dahaga darah di bawah bulan darah, membunuh banyak murid, menyerap darah mereka, dan mengendalikan orang mati melalui pusaka keluarga, Pipa Emas.",
  ui_story_5084_50841301_15_dialog_content = "Dia bersekongkol dengan kepala Ordo dari Rumah Besar ketiga belas yang dihapuskan untuk melepaskan entitas jahat di Varaki Town dan membantai pengikut.",
  ui_story_5084_50841301_16_dialog_content = "Anak terlantar itu...?",
  ui_story_5084_50841301_17_dialog_content = "Kepala rumah ketiga belas mencari tempat Tuhan Kebenaran turun di Dark Zone...",
  ui_story_5084_50841301_18_dialog_content = "Kemudian membawa dewa palsu ke kota, menyerang para pengikut, dan merusak upacara sang Lord.",
  ui_story_5084_50841301_19_dialog_content = "David Porfirio menciptakan dan memanfaatkan kesempatan untuk menguras darah dari pengikut yang terluka.",
  ui_story_5084_50841301_20_dialog_content = "Apakah itu prospek yang ingin kamu pimpin semua orang dan Order?",
  ui_story_5084_50841301_21_dialog_content = "...",
  ui_story_5084_50841301_22_dialog_content = "Hentikan semua omong kosong ini!",
  ui_story_5084_50841301_23_dialog_content = "Dengan kekuatan <color=#FFB400>Cincin Varaki</color>, tunjukkan <color=#FFB400>sifat aslimu</color>!",
  ui_story_5084_50841301_24_dialog_content = "—!",
  ui_story_5084_50841301_25_dialog_content = "Aku berpikir bergaul dengan rumah ketiga belas dan meminum darah para rasul akan meningkatkan kekuatanku...",
  ui_story_5084_50841301_26_dialog_content = "Sisa dari para penguasa menerima berkat dari sang Lord dan beralih ke alternatif lain.",
  ui_story_5084_50841301_27_dialog_content = "Kecuali aku... Dahaga darahku semakin besar. Saya harus mengandalkan tabung darah yang melayang ini sekarang hanya untuk mempertahankan diri.",
  ui_story_5084_50841301_28_dialog_content = "Tampaknya, kamu tidak menyadari bahwa kepala rumah ketiga belas tidak pernah merasakan apa pun dari ini ada dalam perjanjian antara kamu.",
  ui_story_5084_50841301_29_dialog_content = "Mengorbankanmu tidak berbeda dengan mengorbankan semua makhluk untuknya. Dia hanya memanfaatkanmu.",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>Dia</color> bergabung dengan Eclipse dan menjadi salah satu dari <color=#FFB400>Hantu-hantu</color>. Apakah kamu pikir kamu bisa lebih pintar darinya?",
  ui_story_5084_50841301_31_dialog_content = "Diam!",
  ui_story_5084_50841301_32_dialog_content = "Kamu, Victoria Varaki... Bagaimana mungkin kamu bisa mengontrolku dengan cincin itu?",
  ui_story_5084_50841301_33_dialog_content = "Tidak, ini tidak mungkin... Ini bukan cara Cincin Varaki bertindak sebelumnya.",
  ui_story_5084_50841301_34_dialog_content = "Saya telah menguasainya dan menyelaraskannya dengan semua leluhur Varaki.",
  ui_story_5084_50841301_35_dialog_content = "Apa yang kau hadapi adalah kekuatan gabungan dari Klan Varaki. Akui dosa-dosamu sekarang!",
  ui_story_5084_50841301_36_dialog_content = "Heh, aku...",
  ui_story_5084_50841301_37_dialog_content = "Aku membunuh Wilhelm!",
  ui_story_5084_50841301_38_dialog_content = "Tapi aku melakukannya untuk menghilangkan hambatan sebenarnya dari True Order!",
  ui_story_5084_50841301_39_dialog_content = "Bagaimana mungkin putra kedua yang terpelintir dari Varaki, yang hidup dalam pengasingan dan menyakiti saudaranya, bisa memimpin Order?",
  ui_story_5084_50841301_40_dialog_content = "Wilhelm tidak menyakiti siapa pun!",
  ui_story_5084_50841301_41_dialog_content = "Bukan tempatmu untuk berbicara!",
  ui_story_5084_50841301_42_dialog_content = "—!",
  ui_story_5084_50841301_43_dialog_content = "Bloody Bible adalah peninggalan Varaki. Ia memberikan kekuatan kepada pemegangnya dan membebaskan saya dari rasa takut.",
  ui_story_5084_50841301_44_dialog_content = "Bahkan ketika aku membunuh untuk memuaskan hasratku akan darah, itu masih menyetujui dan memberiku kekuatan.",
  ui_story_5084_50841301_45_dialog_content = "Tidak ada seorang pun di The True Order yang berharap bisa menentangku!",
  ui_story_5084_50841301_46_dialog_content = "Bloody Bible, berikan aku kekuatan untuk membasmi Varakis!",
  ui_story_5084_50841301_47_dialog_content = "...",
  ui_story_5084_50841301_48_dialog_content = "Bloody Bible...!",
  ui_story_5084_50841301_49_dialog_content = "Kamu tidak pernah mengerti alasan mengapa Varakis menjadi pemimpin Order.",
  ui_story_5084_50841301_50_dialog_content = "Kami tidak akan pernah menyakiti siapa pun dengan Bloody Bible.",
  ui_story_5084_50841301_51_dialog_content = "Sebaliknya, Biblelah yang menyedot darah Varaki sebagai imbalan atas penyingkapan masa depan.",
  ui_story_5084_50841301_52_dialog_content = "…?",
  ui_story_5084_50841301_53_dialog_content = "Sama saja, baik itu leluhur, orang tua saya, Wilhelm, bahkan saya.",
  ui_story_5084_50841301_54_dialog_content = "Relik-relik ini mempertahankan kehendak setiap kepala rumah, baik itu rasional atau sebaliknya.",
  ui_story_5084_50841301_55_dialog_content = "Mereka yang membuat Pact harus memiliki tekad untuk menahan bisikan menggoda untuk mencapai Truth...",
  ui_story_5084_50841301_56_dialog_content = "Dan tafsirkan wahyu Lord of Truth pada level yang lebih tinggi!",
  ui_story_5084_50841301_57_dialog_content = "Apa wahyu yang telah kamu lihat?",
  ui_story_5084_50841301_58_dialog_content = "...",
  ui_story_5084_50841301_59_dialog_content = "Apa yang akan kamu lakukan...?!",
  ui_story_5084_50841301_60_dialog_content = "Apakah kamu lupa tentang pertemuan itu?",
  ui_story_5084_50841301_61_dialog_content = "What revelation did you receive?",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>To purge the order.</color>",
  ui_story_5084_50841301_63_dialog_content = "Apa-apaan kau…!",
  ui_story_5084_50841301_64_dialog_content = "Pengikut Truth, ucapkan mantra bersamaku!",
  ui_story_5084_50841301_65_dialog_content = "Aku, Nails, akan membaca mantra dengan hidupku!",
  ui_story_5084_50841301_66_dialog_content = "Aku, May, akan membaca mantra bersama Beau!",
  ui_story_5084_50841301_67_dialog_content = "Murid Faust harus membaca mantra bersama Lady Victoria!",
  ui_story_5084_50841301_68_dialog_content = "Mengaku kalah, David.",
  ui_story_5084_50841301_69_dialog_content = "Pengecut! Kepala House Porfirio harus memimpin True Order!",
  ui_story_5084_50841301_70_dialog_content = "Sampai jumpa.",
  ui_story_5084_50841301_71_dialog_content = "Semua dari kalian berjanji padaku!",
  ui_story_5084_50841301_72_dialog_content = "Cukup. Kesepakatan kita berakhir pada bulan darah. Saya melihat saya telah membuat taruhan yang tepat! Selamat menikmati minum darah.",
  ui_story_5084_50841301_73_dialog_content = "Undead ku!",
  ui_story_5084_50841301_74_dialog_content = "Penguasa dari semua rumah dalam Orde, kamu diundang untuk menjadi saksi—",
  ui_story_5084_50841301_75_dialog_content = "...",
  ui_story_5084_50841301_76_dialog_content = "Semangat Kebenaran mengalir melalui semua murid. Silakan berdiri!",
  ui_story_5084_50841301_77_dialog_content = "Dengarkan Truth bersamaku!",
  ui_story_5084_50841301_78_dialog_content = "Aliran bergelombang yang menari bersamaku menembus kekosongan dan muncul di sini.",
  ui_story_5084_50841301_79_dialog_content = "Aku adalah Rune yang dipegang oleh Lord of Truth, menunggu kedatangannya di tanah suci.",
  ui_story_5084_50841301_80_dialog_content = "Akulah Pembawa Cahaya, Kondektur Kegelapan! May Kematian menjadi nyata di Alam Keabadian.",
  ui_story_5084_50841301_81_dialog_content = "Tuhan Yang Maha Kuasa dari Truth, mohon anugerahkan kekuatan ilahi melalui wahyu darah Varaki dalam diriku!",
  ui_story_5084_50841301_82_dialog_content = "Darah Suci akan mengambil bentuk... Aku akan mendengar semua pengakuan!",
  ui_story_5084_50841301_83_dialog_content = "Sulurnya telah dihidupkan kembali. May Tuhan datang padaku!",
  ui_story_5084_50841301_84_dialog_content = "Datanglah padaku dalam mimpi buruk yang sebenarnya ini! Saya akan membebaskan kekuatan kuno!",
  ui_story_5084_50841301_85_dialog_content = "Pinjamkan kami kekuatanmu, Navigator Kebenaran Universal yang bertindak sebagai jembatan ke Sungai Pristine!",
  ui_story_5084_50841301_86_dialog_content = "Apa yang kamu maksud dengan Kebenaran Semesta dan jembatan menuju Sungai Pristine?",
  ui_story_5084_50841301_87_dialog_content = "Tentu saja, saya akan membantu!",
  ui_story_5084_50841301_88_dialog_content = "Dia akan melihat kontribusi Anda. Pact telah selesai. Tunggu kedatangan Tuhan bersamaku!",
  ui_story_5084_50841302_1_dialog_content = "Kau berasal dari garis keturunan yang sama denganku, haus darah, kotor, terkutuk sejak lahir...",
  ui_story_5084_50841302_2_dialog_content = "Apa yang membuatmu, Varakis, pantas untuk memonopoli posisi ini?",
  ui_story_5084_50841302_3_dialog_content = "Jawaban seharusnya jelas bagi kamu ketika kamu mengajukan pertanyaan.",
  ui_story_5084_50841302_4_dialog_content = "Varaki...",
  ui_story_5084_50841302_5_dialog_content = "Dahaga akan darah, keabadian, kutukan... Vampir harus membayar harga tertentu untuk kekuatan tersebut.",
  ui_story_5084_50841302_6_dialog_content = "Gagasan itu telah bersama saya dan membentuk saya sejak saya lahir.",
  ui_story_5084_50841302_7_dialog_content = "Namun baru-baru ini, saya sampai pada kesimpulan yang tercerahkan bahwa semua yang saya alami bukanlah biaya, tetapi yang membuat saya pantas menerima hadiah dan petunjuk yang saya terima.",
  ui_story_5084_50841302_8_dialog_content = "Tuhan dari Truth memilih dan memberi kita kekuatan untuk memimpin perubahan dan era baru.",
  ui_story_5084_50841302_9_dialog_content = "Setiap Eclipsite, senjata dari peradaban kuno, atau dewa palsu bisa menjadi ancaman bagi kelangsungan hidup Aurorian.",
  ui_story_5084_50841302_10_dialog_content = "Apalagi Aurorian jahat dan sesat seperti dirimu.",
  ui_story_5084_50841302_11_dialog_content = "Tanpa meninggalkan Kota Varaki untuk mengamati sungai atau bintang...",
  ui_story_5084_50841302_12_dialog_content = "Tanpa melihat bagaimana planet berkat ini, Eoria, beroperasi di bawah pengawasan Tuhan...",
  ui_story_5084_50841302_13_dialog_content = "Kamu tidak akan pernah mengerti bagaimana bintang tunggal itu jatuh, karena hal itu sudah terjadi terlalu banyak kali.",
  ui_story_5084_50841302_14_dialog_content = "Ketika Aurorian menghadapi kepunahan lagi, hanya Varaki yang dipilih oleh Tuhan yang dapat mencegah kehancuran Eoria.",
  ui_story_5084_50841302_15_dialog_content = "Kemampuan untuk membalikkan rasa takut akan yang tidak diketahui melalui ketenangan yang lebih besar adalah dasar bagi yang Terpilih.",
  ui_story_5084_50841302_16_dialog_content = "David Porfirio, sebagai vampir yang menerima kehormatan tetapi gagal memahami Kebenaran, kamu harus mengembalikan kekuatan yang telah diberikan Lord kepadamu.",
  ui_story_5084_50841302_17_dialog_content = "Ini tidak ada hubungannya dengan pemahaman atau pilihan Tuhan. Hanya Varakis yang diakui oleh vampir.",
  ui_story_5084_50841302_18_dialog_content = "Porfirios dimulai sebagai keturunan dari Varakis...",
  ui_story_5084_50841302_19_dialog_content = "Tapi leluhurku kehilangan tempat mereka karena penindasan Varaki, yang kemudian mencegahku mendapatkan persetujuan...",
  ui_story_5084_50841302_20_dialog_content = "Beberapa abad kemudian, itu tetap sama. Kamu tidak memiliki hak untuk berbicara tentang pencerahan.",
  ui_story_5084_50841302_21_dialog_content = "Kamu—dan Varakis—tidak akan pernah bisa lari dari takdir vampir.",
  ui_story_5084_50841302_22_dialog_content = "Haha... Hahahaha...",
  ui_story_5084_50841302_23_dialog_content = "...",
  ui_story_5084_50841302_24_dialog_content = "Miss Varaki... Maksudku, Lady Victoria...",
  ui_story_5084_50841302_25_dialog_content = "Apakah kamu benar-benar menerima wahyu dari Tuhan dalam perjalananmu ke luar negeri?",
  ui_story_5084_50841302_26_dialog_content = "Kami selalu memiliki banyak relik kuno dalam kepemilikan kami.",
  ui_story_5084_50841302_27_dialog_content = "Bagaimana kita bisa menilai apa yang datang dari bisikan dan apakah kita layak untuk kekuatan yang diberikan oleh Tuhan Kebenaran?",
  ui_story_5084_50841302_28_dialog_content = "Order selalu dikenal karena semangat superior para vampir, sehingga kemampuan untuk beresonansi dengan relic adalah sebuah karunia.",
  ui_story_5084_50841302_29_dialog_content = "Tapi sepanjang tahun, pertarungan kekuasaan antara kepala-kepala rumah dan kepuasan diri telah membingungkan pesan dalam peninggalan yang diwariskan melalui generasi.",
  ui_story_5084_50841302_30_dialog_content = "Untuk banyak peninggalan, bukan sampai saya menetapkan keselarasan bahwa saya menyadari mereka tidak mengandung apa-apa selain rasa sakit yang membuat gila dan jeritan.",
  ui_story_5084_50841302_31_dialog_content = "Ketakutan adalah dasar untuk pengecekan dan keseimbangan antara Aurorian dan objek.",
  ui_story_5084_50841302_32_dialog_content = "Semua penerus Varaki berjalan setiap malam karena ketakutan itu, menyebabkan tubuh dan pikiran mereka memburuk di bawah beban...",
  ui_story_5084_50841302_33_dialog_content = "Itulah mengapa saya mempelajari buku-buku dan gulungan untuk mendapatkan kebijaksanaan dan pengetahuan Aurorian untuk mengendalikan naluri bawaan kita.",
  ui_story_5084_50841302_34_dialog_content = "Melalui mana, aku bisa menjelajah suara-suara dan menuju pelukan Tuhan.",
  ui_story_5084_50841302_35_dialog_content = "Melanjutkan untuk bertanya dan menjelajah, kemudian menekan kelemahan hingga mereka takut pada kita dan menyerah, menurutku, itulah caranya.",
  ui_story_5084_50841302_36_dialog_content = "Kami berterima kasih atas wawasannya, Lady Victoria.",
  ui_story_5084_50841302_37_dialog_content = "Tapi saya harus mengatakan ini tidak hanya berlaku untuk vampir saja.",
  ui_story_5084_50841302_38_dialog_content = "Dalam perjalanan saya, saya menemukan Aurorian non vampir yang memiliki kemampuan tidak diketahui untuk menarik objek khusus.",
  ui_story_5084_50841302_39_dialog_content = "Ini mungkin hanya roda, sebuah jari-jari...",
  ui_story_5084_50841302_40_dialog_content = "Sebuah sulur, selembar kertas...",
  ui_story_5084_50841302_41_dialog_content = "Sebuah hewan peliharaan, sebuah koper putih...",
  ui_story_5084_50841302_42_dialog_content = "Tergantung pada pemiliknya, potensi luar biasa yang berbeda-beda berhasil dibuka.",
  ui_story_5084_50841302_43_dialog_content = "Aku percaya kau belum pernah melihat darah yang dapat berubah dan membunuh Eclipsite.",
  ui_story_5084_50841302_44_dialog_content = "Pengikut saya mengaku pernah bertemu seorang murid yang mampu melakukan itu di jalanan sebelumnya.",
  ui_story_5084_50841302_45_dialog_content = "...",
  ui_story_5084_50841302_46_dialog_content = "Murid-murid seperti itu merajalela di dunia. Order harus berintegrasi ke dalam masyarakat Aurorian dan menyebarkan The Truth, membawa kekuatan seperti itu ke dalam lingkungan kita.",
  ui_story_5084_50841302_47_dialog_content = "Orang lain yang juga menerima wahyu memang ada tetapi tersebar di seluruh dunia, tidak menyadari apa artinya.",
  ui_story_5084_50841302_48_dialog_content = "Kami, sebagai vampir, harus mengumpulkan wahyu untuk memberi tahu Lord of Truth bahwa saatnya Dia datang dan memimpin Aurorian menuju masa depan.",
  ui_story_5084_50841302_49_dialog_content = "Jika itu kasusnya, saya setuju untuk meninggalkan kota dan menyebarkan The Truth di antara Aurorian.",
  ui_story_5084_50841302_50_dialog_content = "Bangun pengikut dan kumpulkan pengaruh...",
  ui_story_5084_50841302_51_dialog_content = "Tapi bagaimana kita bisa menyampaikan pesan kepada Tuan?",
  ui_story_5084_50841302_52_dialog_content = "Jika aku memberitahumu ada Navigator yang mampu mencapai Sungai Pristine melalui peninggalan dan bahkan memerintah peninggalan yang sama...",
  ui_story_5084_50841302_53_dialog_content = "Bukankah kamu juga sangat menantikan masa depan The Order?",
  ui_story_5084_50841302_54_dialog_content = "Apa Navigator?",
  ui_story_5084_50841302_55_dialog_content = "Hei, aku tidak pernah bilang aku akan bergabung dengan Order of Truth!",
  ui_story_5084_50841302_56_dialog_content = "Berikan aku penahan lilin itu, Caelestite.",
  ui_story_5084_50841302_57_dialog_content = "Hah? Tapi ada begitu banyak orang di sini...",
  ui_story_5084_50841302_58_dialog_content = "Berikan padaku.",
  ui_story_5084_50841302_59_dialog_content = "...",
  ui_story_5084_50841302_60_dialog_content = "Ini adalah... Caelestite, sekutu dari The Order.",
  ui_story_5084_50841302_61_dialog_content = "Uh, hai, semuanya.",
  ui_story_5084_50841302_62_dialog_content = "Saya pernah mendengar tentang Caelestites. Mereka bisa mengemudikan Colossi dan memiliki kemampuan telepati.",
  ui_story_5084_50841302_63_dialog_content = "Apakah kau telah berada di sini sepanjang waktu, Caelestite?",
  ui_story_5084_50841302_64_dialog_content = "Yah, untuk lebih akurat, saya ada sebagian besar waktu, tetapi saya tidak menunjukkan diri saya karena berbagai alasan.",
  ui_story_5084_50841302_65_dialog_content = "Telepati... Bukankah itu sama dengan kemampuan vampir untuk beresonansi?",
  ui_story_5084_50841302_66_dialog_content = "Tidak, ini tidak sama.",
  ui_story_5084_50841302_67_dialog_content = "Seperti yang saya sebutkan, vampir berkomunikasi dengan relik melalui garis keturunan.",
  ui_story_5084_50841302_68_dialog_content = "Telepati Caelestite sebenarnya memiliki kesamaan dengan kekuatan yang dimiliki oleh vampir level tinggi, dan kekuatan yang sama juga merupakan dasar bagi semua Aurorian.",
  ui_story_5084_50841302_69_dialog_content = "Sungai Pristine?",
  ui_story_5084_50841302_70_dialog_content = "Astaga! Apakah kamu telah menemukan Ancient Scroll, Lady Victoria?",
  ui_story_5084_50841302_71_dialog_content = "Tidak. Tak seorang pun yang memiliki gulir atau tahu keberadaannya.",
  ui_story_5084_50841302_72_dialog_content = "Tapi Sungai Pristine di belakang Gulungan Kuno tampaknya telah dikunjungi.",
  ui_story_5084_50841302_73_dialog_content = "Aku akan mencari lokasi itu, jadi dengan ini aku ingin menyerahkan kota ini kepada kalian semua.",
  ui_story_5084_50841302_74_dialog_content = "Kami akan mengikuti kata-kata Anda dan standar yang telah Anda tetapkan.",
  ui_story_5084_50841302_75_dialog_content = "Benarkah? Ada yang mengunjungi Sungai Pristine?",
  ui_story_5084_50841302_76_dialog_content = "Cleves Abraham, apakah kamu sedang mempertimbangkan untuk memberitahuku kebenaran tentang membunuh Wilhelm?",
  ui_story_5084_50841302_77_dialog_content = "...",
  ui_story_5084_50841302_78_dialog_content = "Saya di sini untuk meminjam sebuah objek darimu, Cleves.",
  ui_story_5084_50841302_79_dialog_content = "Faria the Black Box?",
  ui_story_5084_50841302_80_dialog_content = "Ya.",
  ui_story_5084_50841302_81_dialog_content = "Kamu sedang mengambil Bloody Bible?!",
  ui_story_5084_50841302_82_dialog_content = "Hanya masalah waktu sebelum vampir itu merampasnya dari makam.",
  ui_story_5084_50841302_83_dialog_content = "Dia tidak berhak mengambilnya.",
  ui_story_5084_50841302_84_dialog_content = "Itu karena suksesi pemimpin Varaki meninggalkan bekas di pikiran para penguasa rumah.",
  ui_story_5084_50841302_85_dialog_content = "Tapi bahkan sekarang, Victoria belum menyadari kekuatan signifikan yang ada dalam urat nadinya.",
  ui_story_5084_50841302_86_dialog_content = "Tambahkan fakta bahwa sejarahku telah mencemarkan kesucian Varakis, para penguasa telah lama membidik posisiku.",
  ui_story_5084_50841302_87_dialog_content = "Jika aku tidak ada lagi, mereka pasti akan mengejar Victoria.",
  ui_story_5084_50841302_88_dialog_content = "Dan True Order yang dipimpin oleh Porfirio pasti akan membawa bencana bagi dunia.",
  ui_story_5084_50841302_89_dialog_content = "Mengenai ini, Wilhelm...",
  ui_story_5084_50841302_90_dialog_content = "Hanya ketika cahaya bulan darah diterangi pada tanaman ivy pada malam Advent of Truth, maka makam akan terbuka untuk penguasa rumah.",
  ui_story_5084_50841302_91_dialog_content = "Tapi, akan terlambat pada saat itu. Kami telah membahas kemungkinan-kemungkinan mengenai Faria the Black Box.",
  ui_story_5084_50841302_92_dialog_content = "Mungkin saudara saya mempercayakan buku itu kepada kamu, teman dekatnya, dengan niatan membiarkan saya mengambilnya saat waktunya tepat.",
  ui_story_5084_50841302_93_dialog_content = "...",
  ui_story_5084_50841302_94_dialog_content = "Mengapa jeda yang lama, Cleves?",
  ui_story_5084_50841302_95_dialog_content = "Wilhelm, dengan asumsi kotak itu bisa membuka makam, dilarang oleh pact umum untuk mengambil buku tanpa kehadiran semua penguasa.",
  ui_story_5084_50841302_96_dialog_content = "Aku tahu.",
  ui_story_5084_50841302_97_dialog_content = "Namun Anda telah sepenuhnya menyampaikan keputusan untuk membatalkan pact kepada saya... Apa yang Anda pikirkan, Wilhelm?",
  ui_story_5084_50841302_98_dialog_content = "Berapa umur Victoria sekarang?",
  ui_story_5084_50841302_99_dialog_content = "Kenapa tanya begitu?",
  ui_story_5084_50841302_100_dialog_content = "Kamu telah merawatnya selama bertahun-tahun. Kamu yang muda, ambisius, dan egois itu...",
  ui_story_5084_50841302_101_dialog_content = "Telah menjadi seorang pria tua yang selalu menjaga orang lain.",
  ui_story_5084_50841302_102_dialog_content = "Jika kamu hanya tahu betapa baiknya Victoria dan aku biasanya akur, kamu mungkin tidak akan mengatakan hal itu.",
  ui_story_5084_50841302_103_dialog_content = "Yang ingin saya katakan adalah, apakah kamu tahu mengapa saya pindah ke Old Town?",
  ui_story_5084_50841302_104_dialog_content = "Untuk Charon, tanpa keraguan.",
  ui_story_5084_50841302_105_dialog_content = "Ya, Wilhelm. Ibu Charon dan saya tidak lagi ingin khawatir tentang Orde, apalagi membiarkan Charon bergabung dengannya.",
  ui_story_5084_50841302_106_dialog_content = "Kamu mundur.",
  ui_story_5084_50841302_107_dialog_content = "Tidak, Wilhelm, saya mengambil langkah sulit ke depan demi Charon.",
  ui_story_5084_50841302_108_dialog_content = "Bagaimana jika aku bilang kamu harus memberiku kotak itu agar Charon dan ibunya terhindar dari masalah?",
  ui_story_5084_50841302_109_dialog_content = "...",
  ui_story_5084_50841302_110_dialog_content = "Order hanya bisa mendapatkan manfaat ketika Alkitab berada di tangan Varaki. Dalam semua kenangan yang saya warisi, itulah satu-satunya cara untuk membawa reformasi!",
  ui_story_5084_50841302_111_dialog_content = "Tampaknya kau telah kembali ke cara-cara ambisiusmu.",
  ui_story_5084_50841302_112_dialog_content = "Belum cukupkah suara-suara gila yang mencoba merusakmu menghukummu?",
  ui_story_5084_50841302_113_dialog_content = "Benar, aku punya ambisi! Tapi lalu apa?!",
  ui_story_5084_50841302_114_dialog_content = "Haruskah aku terus meratapi diri sendiri karena dilindungi oleh seorang kakak yang berbakat dan kuat? Tidak! Tidak pernah!",
  ui_story_5084_50841302_115_dialog_content = "...",
  ui_story_5084_50841302_116_dialog_content = "Maaf, Cleves. Aku tidak bermaksud mengatakan itu.",
  ui_story_5084_50841302_117_dialog_content = "Yang ingin saya katakan adalah kali ini aku tidak melakukannya untuk diriku sendiri. Ini untuk Victoria.",
  ui_story_5084_50841302_118_dialog_content = "I cannot agree with that, Wilhelm...",
  ui_story_5084_50841302_119_dialog_content = "Apa yang kamu takutkan, tepatnya? Tidak bisakah kamu lihat situasi semakin memburuk?",
  ui_story_5084_50841302_120_dialog_content = "Porfirio and the house rulers have stopped following the rules after branching off the Varaki bloodline.",
  ui_story_5084_50841302_121_dialog_content = "Seberapa baikkah bagi kamu untuk mengikuti aturan sendirian?",
  ui_story_5084_50841302_122_dialog_content = "Aturan-aturan untuk vampir selalu menjadi belenggu. Ini adalah penghalang bagi The True Order sekarang, bagi kamu, bagi aku, bagi setiap orang di kota ini.",
  ui_story_5084_50841302_123_dialog_content = "Itulah sifat vampir, kecuali kamu lebih beruntung daripada kami.",
  ui_story_5084_50841302_124_dialog_content = "Kapan kamu memutuskan untuk tunduk pada takdir juga?",
  ui_story_5084_50841302_125_dialog_content = "Do not fault me for this, Wilhelm. I simply cannot deny what I know to be true...",
  ui_story_5084_50841302_126_dialog_content = "Kunci itu hanya akan membahayakanmu.",
  ui_story_5084_50841302_127_dialog_content = "Tapi kamu juga tidak berencana untuk membantu, 'kan?",
  ui_story_5084_50841302_128_dialog_content = "...",
  ui_story_5084_50841302_129_dialog_content = "Tidak apa-apa, Cleves. Aku akan memikirkan sesuatu.",
  ui_story_5084_50841302_130_dialog_content = "Aku tidak memberikan Kotak Hitam kepada Wilhelm, dan juga tidak berniat membunuhnya saat itu.",
  ui_story_5084_50841302_131_dialog_content = "Kupikir aku hanya bisa menonton para penguasa... membunuhnya di malam Advent of Truth.",
  ui_story_5084_50841302_132_dialog_content = "...",
  ui_story_5084_50841302_133_dialog_content = "<size=45>Aahhhh!</size>",
  ui_story_5084_50841302_134_dialog_content = "Haha, hahaha...",
  ui_story_5084_50841302_135_dialog_content = "Cleves...",
  ui_story_5084_50841302_136_dialog_content = "Maaf, Wilhelm...",
  ui_story_5084_50841302_137_dialog_content = "Saya harus memberikan Charon lembaran yang bersih.",
  ui_story_5084_50841302_138_dialog_content = "Aku tahu kamu akan mengerti dari merawat Victoria.",
  ui_story_5084_50841302_139_dialog_content = "Victoria...",
  ui_story_5084_50841302_140_dialog_content = "Heh...",
  ui_story_5084_50841302_141_dialog_content = "Maaf...!",
  ui_story_5084_50841302_142_dialog_content = "Kupikir kau tak akan datang, Cleves.",
  ui_story_5084_50841302_143_dialog_content = "Apakah kamu pikir menyembunyikannya dengan trikmu akan mengubah apa pun, Wilhelm?",
  ui_story_5084_50841302_144_dialog_content = "Doomed to a disgraceful death in your very own hometown... How I pity you, Wilhelm Varaki.",
  ui_story_5084_50841302_145_dialog_content = "...",
  ui_story_5084_50841302_146_dialog_content = "Yah, sekarang sudah tidak relevan lagi untuk mewariskan Cincin Varaki.",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>David Porfirio mendorong kaleng berdarah di belakangnya dan menerapkan kekuatan terbesar yang pernah dia keluarkan di antara jarinya.</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>Dia menghancurkan Cincin Varaki menjadi debu perak dan merah yang berceceran di Wilhelm.</color>",
  ui_story_5084_50841302_149_dialog_content = "What have you done? By crushing the ring, you've...",
  ui_story_5084_50841302_150_dialog_content = "It's useless to you or me now. Let the debris rest with Wilhelm in peace.",
  ui_story_5084_50841302_151_dialog_content = "From this day forth, it cannot be used to threaten us ever again.",
  ui_story_5084_50841302_152_dialog_content = "Belenggu yang adalah Grand Ruler Varaki ada di masa lalu!",
  ui_story_5084_50841302_153_dialog_content = "Saya harus mengatakan, kamu benar-benar menyajikan pesta yang lezat untuk Advent of Truth, David!",
  ui_story_5084_50841302_154_dialog_content = "Tapi Wilhelm sudah mati...!",
  ui_story_5084_50841302_155_dialog_content = "Ya, dengan bantuanmu. Kita masih harus mengikuti hirarki dalam mencicipi darah Varaki.",
  ui_story_5084_50841302_156_dialog_content = "Setelah diriku sendiri, tentu saja, teman terdekatku—Cleves.",
  ui_story_5084_50841302_157_dialog_content = "Setelah anak buahku makan, Wilhelm sepenuhnya milikmu.",
  ui_story_5084_50841302_158_dialog_content = "Karena kalian berdua adalah teman lama, kamu bisa memberinya pemakaman.",
  ui_story_5084_50841302_159_dialog_content = "Maksud saya, beristirahat selamanya di dalam peti mati adalah salah satu tradisi kita, setelah semua.",
  ui_story_5084_50841302_160_dialog_content = "Tapi jangan lupa untuk memohon ampun kepadanya. Mungkin dia masih bisa mendengar kata-kata dari seorang teman yang menikamnya dari belakang.",
  ui_story_5084_50841302_161_dialog_content = "Jadi, apakah kamu akan berhenti menyulitkan Charon dan istriku sekarang?",
  ui_story_5084_50841302_162_dialog_content = "Tentu saja. Tapi Cleves, ada sesuatu yang tidak cukup aku mengerti... Apakah benar bahwa anak buahku melihatmu berencana untuk pindah?",
  ui_story_5084_50841302_163_dialog_content = "...",
  ui_story_5084_50841302_164_dialog_content = "Itu akan membuatnya lebih sulit bagi saya untuk meminta lebih banyak bantuan darimu, bukan?",
  ui_story_5084_50841302_165_dialog_content = "Apa-apaan kau…!",
  ui_story_5084_50841302_166_dialog_content = "Hahaha!",
  ui_story_5084_50841302_167_dialog_content = "Bodoh.",
  ui_story_5084_50841302_168_dialog_content = "Kamu punya telinga di tanah, Demam Emas. Jangan lupa untuk melacak Victoria untukku.",
  ui_story_5084_50841302_169_dialog_content = "Apa yang telah kulakukan... Apa yang telah kulakukan?!",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>Cleves membawa Wilhelm yang telah meninggal ke Makam Varaki.</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>Namun, penjaga menolak permintaannya untuk mengubur Wilhelm di dalam.</color>",
  ui_story_5084_50841302_172_dialog_content = "Kunci universal—<color=#FFB400>Faria the Black Box</color>!",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>Relik muncul dan merobek sebuah retakan. Melalui celah di The Flow, Cleves memasuki kripta.</color>",
  ui_story_5084_50841302_174_dialog_content = "Ini adalah Makam Varaki, Wilhelm. Meskipun tidak ada tempat yang lebih aman untukmu, aku harus segera pergi.",
  ui_story_5084_50841302_175_dialog_content = "Kuharap kamu bisa beristirahat dalam damai dan kembali kepada Tuhan Kebenaran seperti leluhurmu.",
  ui_story_5084_50841302_176_dialog_content = "Kunci ini hanya akan menimbulkan masalah bagi saya.",
  ui_story_5084_50841302_177_dialog_content = "Tidak bisa dihindari bagi Porfirio untuk mengetahui jika aku harus menyimpannya.",
  ui_story_5084_50841302_178_dialog_content = "Jika para leluhur melihat peristiwa itu, biarlah siksaan pengkhianatan menjadi hukumanku.",
  ui_story_5084_50841302_179_dialog_content = "True Order... Varaki... Kami mencoba, tapi tidak bisa mengendalikan takdir mereka.",
  ui_story_5084_50841302_180_dialog_content = "Wilhelm... Vampir... Bukankah pada akhirnya kita semua tetap menjadi tawanan takdir?",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>Saat penjaga makam menonton dalam diam, Cleves meletakkan Black Box di dalam peti mati bersama Wilhelm.</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>Tidak ada yang menyadari bahwa kunci universal secara sewenang-wenang membuka pintu yang disebut \"Takdir\".</color>",
  ui_story_5084_50841302_183_dialog_content = "Aku tidak akan mencoba membela diriku. Aku pantas mendapatkan semua ini.",
  ui_story_5084_50841302_184_dialog_content = "Untuk pengkhianatan itu, kamu harus segera bertobat kepada Lord of Truth, Mr. Cleves.",
  ui_story_5084_50841302_185_dialog_content = "Saya tidak akan meminta pengampunan Tuhan, karena saya bahkan tidak bisa menghadapi Wilhelm.",
  ui_story_5084_50841302_186_dialog_content = "...",
  ui_story_5084_50841302_187_dialog_content = "Tidak ada yang tahu tentang tempat itu selain kamu dan saya. Dan Wilhelm sudah mati.",
  ui_story_5084_50841302_188_dialog_content = "Hari aku memutuskan untuk meninggalkan Kota Varaki, kamu tidak mencari Wilhelm. Kamu mencari aku.",
  ui_story_5084_50841302_189_dialog_content = "Jika kamu tinggal, aku akan mengaku semua hal kepadamu. Tapi jika kamu pergi...",
  ui_story_5084_50841302_190_dialog_content = "Kamu tidak akan mengatakan sepatah kata pun.",
  ui_story_5084_50841302_191_dialog_content = "Jujur, tidak sehari pun berlalu tanpa aku merasakan siksaan...",
  ui_story_5084_50841302_192_dialog_content = "Kamu bisa mengambil nyawaku kapan saja yang kamu mau. Yang aku minta hanyalah izinkan aku melakukan satu hal terakhir.",
  ui_story_5084_50841302_193_dialog_content = "...",
  ui_story_5084_50841302_194_dialog_content = "Apakah Anda baik-baik saja, Pak Cleve?",
  ui_story_5084_50841302_195_dialog_content = "Charon dan istriku tak ada hubungannya dengan semua ini. Aku harus memberi mereka lembaran yang bersih.",
  ui_story_5084_50841302_196_dialog_content = "Tapi meski aku tetap hidup, Charon mungkin masih akan membenciku pasti...",
  ui_story_5084_50841302_197_dialog_content = "Apa yang dapat saya lakukan? Mungkin ini adalah hukuman lain untukku.",
  ui_story_5084_50841302_198_dialog_content = "Aku ingat Charon menceritakan tentang ayahnya. Mereka memang memiliki hubungan yang rumit.",
  ui_story_5084_50841302_199_dialog_content = "...",
  ui_story_5084_50841302_200_dialog_content = "Hei, lilinnya hampir padam, Victoria.",
  ui_story_5084_50841400_1_dialog_content = "Mengenai \"Kunci Universal\" ini, Lady Victoria...",
  ui_story_5084_50841400_2_dialog_content = "Tuan Cleves menguburkannya bersama Tuan Wilhelm, yang sekarang tidak ada di mana-mana, jadi ini semua yang bisa saya temukan.",
  ui_story_5084_50841400_3_dialog_content = "Bukankah ini Kotak Hitam...?",
  ui_story_5084_50841400_4_dialog_content = "PlayerName…",
  ui_story_5084_50841400_5_dialog_content = "Oh, maaf, saya lupa informasi seperti itu tidak seharusnya ada di sini.",
  ui_story_5084_50841400_6_dialog_content = "Aku tahu kamu akan pergi, jadi aku meneruskannya ke pemimpin True Order, Lady Victoria!",
  ui_story_5084_50841400_7_dialog_content = "Tidak, tidak ada satu pun dari kita yang bisa berharap untuk mengendalikannya. Biarkan saja di sini.",
  ui_story_5084_50841400_8_dialog_content = "Pastikan tidak ada yang menyentuhnya, bahkan aku sekalipun. Semuanya harus mengikuti kehendak Lord.",
  ui_story_5084_50841400_9_dialog_content = "Saya memiliki permintaan, Lady Victoria. Apakah mungkin untuk tidak menjadikan saya penjaganya?",
  ui_story_5084_50841400_10_dialog_content = "Kamu seharusnya menjadi penjaganya. Ketika ayahku memberikannya kepada Cleves, kemungkinan dia sudah melihat bagaimana takdirnya akan terbentang.",
  ui_story_5084_50841400_11_dialog_content = "Saya tidak tahu berapa lama lagi saya bisa menjaga Makam Varaki.",
  ui_story_5084_50841400_12_dialog_content = "Dengan izin, saya ingin melepaskan posisi saya sebagai penguasa rumah dan menjadi tanaman anggur penuh waktu yang menjaga makam dan menunggu kedatangan Anda.",
  ui_story_5084_50841400_13_dialog_content = "Saya bisa menghilangkan makam dari pikiran para penguasa dengan sihir, tetapi apakah ada kebenaran yang kamu pegang teguh di hatimu?",
  ui_story_5084_50841400_14_dialog_content = "Kenyataannya adalah aku ingin meninggalkan dunia sejak awal, dan makam ini kebetulan menjadi pilihan yang sempurna.",
  ui_story_5084_50841400_15_dialog_content = "Ini tidak ada hubungannya dengan siapa yang memimpin Order. Saya tidak mempertanyakan keputusan Anda, tentu saja, Lady Victoria.",
  ui_story_5084_50841400_16_dialog_content = "Apakah kamu masih memilih menjaga makam daripada merasakan kebebasan?",
  ui_story_5084_50841400_17_dialog_content = "Keluargaku sudah tiada. Aku akan sendiri di mana pun aku berada.",
  ui_story_5084_50841400_18_dialog_content = "Maka, akan kuberikan hak untuk mencari kedamaianmu di sini.",
  ui_story_5084_50841400_19_dialog_content = "Kamu adalah teman paling setia Varakis. Kamu memiliki hak untuk menggantikan David Porfirio dan mengawasi kota saat saya tidak ada.",
  ui_story_5084_50841400_20_dialog_content = "Saya tidak akan berani memimpikan itu...!",
  ui_story_5084_50841400_21_dialog_content = "Tetapi itu adalah akhir yang sangat Anda harapkan. Anda dapat memulai keluarga dan masa depan baru.",
  ui_story_5084_50841400_22_dialog_content = "Aku ingat kamu meninggalkan semua hubungan masa lalu dengan Lumopolis, termasuk nama belakangmu.",
  ui_story_5084_50841400_23_dialog_content = "Silakan, pilih nama belakang baru dan biarkan itu menjadi dasar dari awal yang baru.",
  ui_story_5084_50841400_24_dialog_content = "Aku paham, Nyonya.",
  ui_story_5084_50841400_25_dialog_content = "Aku memilih... Dantes.",
  ui_story_5084_50841400_26_dialog_content = "Mulai dari titik ini, aku akan dikenal sebagai Glave Dantes.",
  ui_story_5084_50841400_27_dialog_content = "(Dantes?! Dia adalah leluhur dari Sikare Dantes?)",
  ui_story_5084_50841400_28_dialog_content = "Karena kamu telah memilih takdirmu, mari kita lanjutkan.",
  ui_story_5084_50841400_29_dialog_content = "Klanmu telah dan selalu akan menjadi sekutu tepercaya bagi Varakis. Black Box akan mengawasi garis keturunanmu.",
  ui_story_5084_50841400_30_dialog_content = "Mengerti. Saya akan pergi sekarang.",
  ui_story_5084_50841400_31_dialog_content = "Fiuh, sepertinya itu sudah berakhir.",
  ui_story_5084_50841400_32_dialog_content = "Kami sudah selesai dengan Advent of Truth di sini, tetapi ada satu lagi yang menanti kita kembali di Vortex.",
  ui_story_5084_50841400_33_dialog_content = "Tidak, itu berarti tiga Kedatangan Kebenaran! Saya mulai merindukan Lenore...",
  ui_story_5084_50841400_34_dialog_content = "Hei, lilin ini benar-benar akan padam kali ini.",
  ui_story_5084_50841400_35_dialog_content = "...",
  ui_story_5084_50841400_36_dialog_content = "(Victoria tampaknya sedang menantikan Wilhelm dengan cara dia menatap ke kejauhan...)",
  ui_story_5084_50841400_37_dialog_content = "Ayo.",
  ui_story_5084_50841400_38_dialog_content = "Apakah Anda akan membawa kedua Alkitab dengan Anda, Lady Victoria?",
  ui_story_5084_50841400_39_dialog_content = "Mereka akan pergi ke tempat yang seharusnya mereka tuju dalam perjalanan kita kembali. Mari kita bersiap.",
  ui_story_5084_50841400_40_dialog_content = "Lilinnya padam! Hei, kamu masih memegang kitab suci lama.",
  ui_story_5084_50841400_41_dialog_content = "Ini membawa kita ke sini untuk bertemu dengan versi barunya, jadi inilah saatnya saya mengembalikannya ke tangan takdir.",
  ui_story_5084_50841400_42_dialog_content = "Victoria?",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>Di dalam kegelapan yang kembali, muncul retakan dalam hujan waktu. Sehelai panjang dan aneh bisa terlihat dalam kabut.</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>Victoria melepaskan alkitab yang telah bersamanya selama bertahun-tahun dan menontonnya berenang dalam arus deras.</color>",
  ui_story_5084_50841400_45_dialog_content = "Ke mana ia pergi?",
  ui_story_5084_50841400_46_dialog_content = "Tataplah arus deras itu, dan kamu mungkin bisa melihat Kebenaran.",
  ui_story_5084_50841400_47_dialog_content = "Setiap dari kita hanyalah pasir di sungai. Pada akhirnya, kita akan kembali kepada Tuhan dari Kebenaran.",
  ui_story_5084_50841400_48_dialog_content = "Pergilah dan penuhi takdirmu.",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>Alkitab mengalir \"ke hilir\" dan meninggalkan \"orang asing masa depan\".</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>Itu melayang dengan damai di Sungai Pristine saat gambar tak terhitung jumlahnya muncul dalam gelombang jalannya, menunjukkan masa lalu dan masa depan.</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>Halaman-halamannya membuka sendiri dan memunculkan huruf-huruf di lembaran kosong yang sebelumnya.</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>Jadi, takdir telah ditulis...</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>Pantulan dari kitab suci tercermin dalam cerita dan buku itu mulai mendapatkan pengakuan. Akhirnya menjadi bagian dari sungai.</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>\"Wilhelm mengambil Bloody Bible yang datang dari tempat yang tidak diketahui. Dia merasakan kehadiran wahyu di dalamnya dan memutuskan untuk membawanya ke Victoria yang sedang tidur.\"</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>\"Sang Victoria muda itu membaca buku kosong dan mendengar ramalan The Truth untuk pertama kalinya.\"</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>Buku itu terus mengalir ke hilir. Waktu tidak memiliki awal maupun akhir di sungai ini, hanya siklus yang tak berujung.</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>\"Oleh karena itu, Victoria melepaskan Alkitab yang telah bersamanya selama bertahun-tahun dan menyaksikannya berenang dalam arus deras.\"</color>",
  ui_story_5084_50841400_58_dialog_content = "Semua pelancong telah kembali ke waktu mereka masing-masing. Saya harus menyelesaikan pekerjaan saya juga.",
  ui_story_5084_50841400_59_dialog_content = "Victoria Tahun 1918, kamu masih berada di jalan untuk menemukan Kebenaran. Kamu masih tersesat dan segalanya pasti tampak membingungkan bagimu.",
  ui_story_5084_50841400_60_dialog_content = "Itu tidak masalah. Waktu akan membawamu ke sana.",
  ui_story_5084_50841400_61_dialog_content = "Kamu akan memulai perjalanan panjang sebelum mencapai pencerahan.",
  ui_story_5084_50841400_62_dialog_content = "Kalau begitu, kamu akan membawa mereka kembali ke titik ini dan kita akan bertemu lagi.",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>Wilhelm mengantarkan Victoria yang sedang tidur dari Vortex kepadanya dan meletakkan Bloody Bible di tangannya.</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>Kemudian dia berbaring di dalam peti mati tempat dia datang dan merenung tentang masa lalunya.</color>",
  ui_story_5084_50841400_65_dialog_content = "Ketika kamu, sebagai anak kecil, bertemu dengan saya untuk pertama kalinya, itu karena kakakmu ingin mempercayakanmu kepada saya, karena dia akan segera meninggal.",
  ui_story_5084_50841400_66_dialog_content = "Jadi aku bisa menjadi pemimpin?",
  ui_story_5084_50841400_67_dialog_content = "Ya, dan kemudian merawat Victoria.",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>Victoria berdiri diam di samping orang tuanya, tidak memahami alasan kepuasan mereka meskipun mereka sedang sekarat.</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>Tapi Wilhelm Varaki, yang telah menahan penghinaan tak terhitung jumlahnya, tidak tahan untuk memimpin Victoria yang hancur ke jalan takdir para vampir.</color>",
  ui_story_5084_50841400_70_dialog_content = "Berhenti membuang-buang napas. Aku tidak akan melakukannya.",
  ui_story_5084_50841400_71_dialog_content = "...",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>Tapi pada hari pemakaman, Wilhelm masih mengenakan pakaian seorang murid dan menyaksikan saudara laki-lakinya dan adik iparnya meninggalkan Kota Varaki dalam peti mati.</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>Wilhelm berlama-lama di luar Makam Varaki, mendengarkan \"salam\" para master untuk Victoria.</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>Kekuatan badai dan petir yang tampaknya ditujukan untuk merobek dunia ini mencerminkan emosi Wilhelm.</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>Dia menyerbu ke jantung makam hanya untuk memakai Cincin Varaki yang bisa merusaknya di depan para master...</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>Hanya untuk melindungi gadis yang akan memulai pencarian akan Kebenaran bersamanya.</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>Hubungan mereka memang tidak bahagia, tetapi Wilhelm harus memaksa Victoria untuk berhenti melawan Ordo dan menjadi lebih kuat.</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>Selama ini mencari setiap opsi untuk menjaga keamanan mereka.</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>Juga tentang kematian dirinya sendiri...</color>",
  ui_story_5084_50841400_80_dialog_content = "Cleves...",
  ui_story_5084_50841400_81_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841400_82_dialog_content = "Victoria...",
  ui_story_5084_50841400_83_dialog_content = "Heh...",
  ui_story_5084_50841400_84_dialog_content = "(Menurut tradisi vampir, kematian mungkin adalah sebuah berkah.)",
  ui_story_5084_50841400_85_dialog_content = "(Tapi aku ini tidak lagi merasakan sakit karena pengkhianatan orang lain.)",
  ui_story_5084_50841400_86_dialog_content = "(Aku mengerti betapa sulitnya untukmu, tapi apa yang akan terjadi pada Victoria sekarang?)",
  ui_story_5084_50841400_87_dialog_content = "(Apakah saya telah meneruskan setiap Kebenaran yang telah saya pelajari kepadanya?)",
  ui_story_5084_50841400_88_dialog_content = "(Apakah dia akan memberi tahu saya bahwa dia berada di jalan yang tidak goyah menuju Kebenaran sebelum dia pergi?)",
  ui_story_5084_50841400_89_dialog_content = "(...)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>Wilhelm tidak pernah berhenti bertanya tentang Kebenaran ketika pikirannya beralih ke sungai yang jernih.</color>",
  ui_story_5084_50841400_91_dialog_content = "Apa yang terjadi? Bukankah saya berada di gereja...? Seharusnya saya sudah mati sekarang.",
  ui_story_5084_50841400_92_dialog_content = "Di mana aku?",
  ui_story_5084_50841400_93_dialog_content = "Kerajaan Orang Mati, atau Kuil Tuhan Kebenaran?",
  ui_story_5084_50841400_94_dialog_content = "Apa ini sungai?",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>Wilhelm terapung tanpa henti tanpa bergerak, tetapi pikirannya menyerap semua informasi di dunia.</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>Sebuah dekade? Seabad? Sudah berapa lama...?</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>Eoria menjadi gelap dan menerangi lagi, saat konflik antara Aurorian dan Eclipsite terus berlangsung.</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>Tapi dia melayang melalui semua itu.</color>",
  ui_story_5084_50841400_99_dialog_content = "Apakah itu aku?",
  ui_story_5084_50841400_100_dialog_content = "Itu bukan keinginannya tetapi itu adalah takdirnya. Letakkan Bloody Bible baru ini di peti mati untukku. Dia akan menemukannya berguna.",
  ui_story_5084_50841400_101_dialog_content = "Ya, Tuan Wilhelm.",
  ui_story_5084_50841400_102_dialog_content = "Dan ketika saat itu tiba...",
  ui_story_5084_50841400_103_dialog_content = "Mengapa kamu sedih? Kamu bisa saja memulai sebuah keluarga dan selesai dengan itu.",
  ui_story_5084_50841400_104_dialog_content = "Memulai sebuah keluarga dan membesarkan anak-anak? Sungguh membosankan.",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>Banyak versi dari Wilhelm tersebar di mana-mana, namun ditumpuk satu sama lain. Itu adalah kekacauan murni hingga dia melihat keberadaan selain dirinya sendiri.</color>",
  ui_story_5084_50841400_106_dialog_content = "Aku tidak akan mengambil kredit untuk itu. Ini adalah berkah dari Tuhan Truth.",
  ui_story_5084_50841400_107_dialog_content = "Ada apa ini?",
  ui_story_5084_50841400_108_dialog_content = "Sungai <color=#FFB400>Pristine</color>, di luar waktu dan ruang. Satu-satunya perbedaan dari dunia luar adalah bahwa ia mengalir.",
  ui_story_5084_50841400_109_dialog_content = "Kami tidak akan bisa mengendalikan hidup kami jika ini terus berlanjut! Kenapa kamu membawa kami ke sini?",
  ui_story_5084_50841400_110_dialog_content = "Victoria?!",
  ui_story_5084_50841400_111_dialog_content = "Heh, hahaha!",
  ui_story_5084_50841400_112_dialog_content = "Aku tahu kamu bisa melakukannya, Victoria Varaki.",
  ui_story_5084_50841400_113_dialog_content = "Dan Charon juga.",
  ui_story_5084_50841400_114_dialog_content = "Kami melakukannya sebagai tetua mereka, Cleves.",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>Ketika kenangan itu memudar, Wilhelm bangkit hanya untuk menyadari bahwa dia tidak berada di peti matinya—tetapi menonton dan tenggelam dalam Sungai Pristine yang selalu mengalir.</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>Semua yang telah dia ganggu akan melibatkannya dan membawanya ke Asumsi Kebenaran.</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>Kemudian...</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>Buku yang dijatuhkan oleh Victoria berhenti mengambang karena menabrak penghalang—sebuah \"mayat\" yang tergeletak di sungai.</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>Mayat Wilhelm yang dikhianati, pria yang dipanggil oleh Pintu Takdir, terbangun di dalam aliran yang menakjubkan.</color>",
  ui_story_5084_50841400_120_dialog_content = "…?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>Wilhelm yang bingung berhasil menyadari Bloody Bible berhenti di kaki sungainya.</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>Seolah menjawab panggilan diam, dia membalik-balik buku yang benar-benar kosong dan mulai melihat...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>\"Bloody Bible mengapung dan berhenti di samping kaki Wilhelm yang mati. Vampir muda terbangun karena tetesan darah dalam reruntuhan cincin.\"</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>\"Wilhelm yang bingung berhasil melihat Bloody Bible berhenti di kaki mereka di sungai.\"</color>",
  ui_story_5084_50841400_125_dialog_content = "Apa?",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>\"Terkejut, Wilhelm tersandung mundur ke sungai, basah kuyup dalam air yang telah dia ganggu dan mencemari sebab dan akibatnya.\"</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>\"Sambil duduk di sungai, Wilhelm menyadari ada sesuatu di tangannya. Saat dia mengambilnya dengan gemetar, dia menyadari itu adalah...\"</color>",
  ui_story_5084_50841400_128_dialog_content = "Cincin leluhur Varaki?",
  ui_story_5084_50841400_129_dialog_content = "Apa arti semua ini?",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>\"Setelah menerima panggilan, Wilhelm ditakdirkan untuk mengembara dan memimpin orang lain menuju Kebenaran.\"</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>\"Ketika waktunya tepat, Makam Varaki akan terbuka untuk Victoria. Wilhelm, Pelayan dari Kebenaran, akan menjadi pemandunya.\"</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>\"Wilhelm kemudian berbaring di dalam peti mati tempat dia datang dan merenung tentang masa lalunya.\"</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>\"Ketika dia menyadari tujuannya telah terpenuhi dan Victoria sudah siap, akankah dia akhirnya beristirahat dengan damai?\"</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>\"Namun ketika dia menyentuh cincin itu, setetes darah Varaki di dalamnya mengalir melalui tubuhnya. Dia jatuh tertidur saat perasaan yang akrab kembali.\"</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>\"Ketika Wilhelm terbangun lagi, dia akan dipandu ke persimpangan takdir.\"</color>",
  ui_story_5084_50841400_136_dialog_content = "Dimana saya...",
  ui_story_5084_50841400_137_dialog_content = "Meskipun Lady Victoria mengatakan kebaktian akan menunjukkan jalan untukku...",
  ui_story_5084_50841400_138_dialog_content = "Tapi aku akan mengorbankan...",
  ui_story_5084_50841400_139_dialog_content = "I will...",
  ui_story_5084_50841400_140_dialog_content = "...",
  ui_story_5084_50841400_141_dialog_content = "... My lord?",
  ui_story_5084_50841400_142_dialog_content = "Lord of Truth yang agung!",
  ui_story_5084_50841400_143_dialog_content = "Did you just say... Lady Victoria?",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>\"Waktu tidak memiliki awal maupun akhir di sungai, tetapi siklus yang tak berujung.\"</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>\"Dengan demikian, Victoria melepaskan alkitab yang telah bersamanya selama bertahun-tahun dan menontonnya berenang dalam arus deras.\"</color>",
  ui_story_5084_50841400_146_dialog_content = "Kamu kembali.",
  ui_story_5084_50841400_147_dialog_content = "Ya. Lilin itu hilang.",
  ui_story_5084_50841400_148_dialog_content = "Jenis kekuatan itu milik Faria.",
  ui_story_5084_50841400_149_dialog_content = "Tutup, Faria.",
  ui_story_5084_50841400_150_dialog_content = "(Aku mengerti... Jadi Starry Crypt adalah Makam Varaki waktu itu.)",
  ui_story_5084_50841400_151_dialog_content = "Kita bertemu lagi, \"Kunci Universal.\"",
  ui_story_5084_50841400_152_dialog_content = "Miss Victoria?",
  ui_story_5084_50841400_153_dialog_content = "Hehe, mohon maafkan aku yang sedang bergumam sendiri.",
  ui_story_5084_50841400_154_dialog_content = "Tentu.",
  ui_story_5084_50841400_155_dialog_content = "May?",
  ui_story_5084_50841400_156_dialog_content = "Sedang apa kamu di sini, May?",
  ui_story_5084_50841400_157_dialog_content = "Kamu tidak ada di rumah setelah roti dibuat, jadi saya pikir kamu datang untuk melihat Sikare. Saya tidak berharap melihat Nona Victoria dan setiap orang lainnya di sini juga.",
  ui_story_5084_50841400_158_dialog_content = "Tunggu, sepertinya aku mendengar ada yang menyebutkan makanan...",
  ui_story_5084_50841400_159_dialog_content = "Roti dan anggur yang enak... semua disiapkan secara pribadi oleh May untuk Kedatangan Truth!",
  ui_story_5084_50841400_160_dialog_content = "Sekarang aku lapar karena kamu bilang begitu.",
  ui_story_5084_50841400_161_dialog_content = "Kamu akan datang ke perayaan bersama kami, bukan, Sikare?",
  ui_story_5084_50841400_162_dialog_content = "Ya. Saya pasti akan menjawab undangan Victoria.",
  ui_story_5084_50841400_163_dialog_content = "Sudah waktunya. Anggota Order seharusnya sudah berkumpul di kota, Lady Victoria.",
  ui_story_5084_50841400_164_dialog_content = "Apakah semua orang dari True Order akan ada di sana?",
  ui_story_5084_50841400_165_dialog_content = "Kamu tampak enggan saat kami mengundangmu. Apakah kamu penuh antisipasi sekarang?",
  ui_story_5084_50841400_166_dialog_content = "Saya tidak bisa mengatakan bahwa saya sering melihat teman-teman saya dari Order, tetapi selalu baik berada di perusahaan mereka.",
  ui_story_5084_50841400_167_dialog_content = "Selamat datang, setiap orang, di perayaan tiga tahunan True Order.",
  ui_story_5084_50841400_168_dialog_content = "Dalam tiga tahun terakhir, kita semakin dekat dalam memahami Eoria serta Lord of Truth.",
  ui_story_5084_50841400_169_dialog_content = "Selain Tuhan yang abadi, kami tidak mengikuti ajaran tetap apa pun, terlepas dari latar belakang kami.",
  ui_story_5084_50841400_170_dialog_content = "Entah itu individualitas unik kita, melarikan diri dari belenggu masa lalu, atau memenuhi tujuan tertentu...",
  ui_story_5084_50841400_171_dialog_content = "Karena transformasi yang terus menerus, kita bersinar terang dalam perjalanan menuju Truth.",
  ui_story_5084_50841400_172_dialog_content = "True Order yang kamu lihat sekarang berada di jalan yang diberkati oleh The Truth.",
  ui_story_5084_50841400_173_dialog_content = "Aku bisa menjamin bahwa vampir-vampir di luar Astra yang memiliki hubungan dekat dengan True Order sudah siap.",
  ui_story_5084_50841400_174_dialog_content = "Dan aku akan memimpin kalian semua untuk menyaksikan kedatangan Lord of Truth.",
  ui_story_5084_50841400_175_dialog_content = "Dalam Krisis Darkover, Bloody Bible mengungkapkan revolusi besar yang akan datang.",
  ui_story_5084_50841400_176_dialog_content = "Revolusioner yang saya asuh saat itu telah berkembang menjadi dewasa.",
  ui_story_5084_50841400_177_dialog_content = "Gembok itu akan muncul di Dark Zone. Aku akan membawa kunci ke tujuan dan membangun kembali kerajaan bersama Tuhan.",
  ui_story_5084_50841400_178_dialog_content = "Ini akan menjadi perjalanan berbahaya melalui Zona Gelap. Sekali lagi, True Order akan memandu Aurorian melewati krisis sebagai sekutu mereka.",
  ui_story_5084_50841400_179_dialog_content = "Sekarang silakan nikmati pestanya.",
  ui_story_5084_50841400_180_dialog_content = "Dia lah yang menghormati saya dan memberikan Nutrisi Truth kepada kamu.",
  ui_story_5084_50841400_181_dialog_content = "Anda juga dipersilakan untuk bertukar pencerahan pribadi Anda dengan orang lain.",
  ui_story_5084_50841400_182_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50841400_183_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5084_50841400_184_dialog_content = "Kamu sudah mengintip Faust untuk beberapa saat sekarang, Pasolo. Apakah ada yang salah dengannya?",
  ui_story_5084_50841400_185_dialog_content = "Nah, Tuan Faust, ini tentang jiwa orang tua saya yang telah meninggal. Nona Sikare berpikir mungkin Anda bisa memberi saya perspektif baru...",
  ui_story_5084_50841400_186_dialog_content = "Jika kamu menginginkan perspektif baru, coba Nails. Dia telah berkembang lebih dari siapa pun akhir-akhir ini.",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>Gemuruh, gemuruh...</color>",
  ui_story_5084_50841400_188_dialog_content = "Tolong hentikan benda itu, PlayerName!",
  ui_story_5084_50841400_189_dialog_content = "Oh tidak, ini terlalu cepat... dan ini berguling menuju Nails!",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5084_50841400_191_dialog_content = "Maaf, Pak Nails! Hunting Stone tidak melukaimu, bukan?",
  ui_story_5084_50841400_192_dialog_content = "Tidak, Nyonya Pact. Jika kamu ingin membuatku merasakan sakit, kamu bisa menusukku dengan duri di sini.",
  ui_story_5084_50841400_193_dialog_content = "Tuan Nails! Bukankah kamu sudah berjanji tidak akan menyakiti dirimu sendiri malam ini? Apakah itu ada hubungannya dengan pakaian barumu?",
  ui_story_5084_50841400_194_dialog_content = "Tn. Nails, Tn. Faust memberitahuku bahwa Anda bisa memberikan saya perspektif baru tentang jiwa.",
  ui_story_5084_50841400_195_dialog_content = "Ah, perspektif... Memang mentor saya menawarkan beberapa kepada saya.",
  ui_story_5084_50841400_196_dialog_content = "Saya percaya bahwa jiwa adalah konsentrasi dari roh seseorang. Selama roh itu masih ada, seseorang tidak pernah benar-benar pergi.",
  ui_story_5084_50841400_197_dialog_content = "Begitu, ya... Lalu, apakah aku bisa melihat arwah orang mati lagi?",
  ui_story_5084_50841400_198_dialog_content = "Mungkin Victoria memiliki jawaban untuk itu.",
  ui_story_5084_50841400_199_dialog_content = "Hei, sudah lama sekali dan aku bisa merasakan aura suci yang menghantamku.",
  ui_story_5084_50841400_200_dialog_content = "Apa kabar, Tuan Telamont.",
  ui_story_5084_50841400_201_dialog_content = "Apakah kamu menemukan sesuatu selama waktu kamu bersama Lady Victoria?",
  ui_story_5084_50841400_202_dialog_content = "Merupakan suatu kehormatan bagi saya untuk bertemu dengan mentor yang penting. Dialah yang membimbing saya dalam transformasi saya di bawah Tuhan.",
  ui_story_5084_50841400_203_dialog_content = "Saya tidak berpikir para pertapa bisa datang. Apakah mentor Anda di sini sekarang?",
  ui_story_5084_50841400_204_dialog_content = "Aku malu mengaku bahwa aku tidak tahu...",
  ui_story_5084_50841400_205_dialog_content = "Lady Victoria, Mr. Nails berkata, \"Selama semangat masih ada, seseorang tidak pernah benar-benar pergi.\"",
  ui_story_5084_50841400_206_dialog_content = "Apakah itu berarti orang tua yang telah meninggal telah bersamaku selama ini?",
  ui_story_5084_50841400_207_dialog_content = "Aurorian lahir dari cahaya iman. Kekuatan spiritual mereka berasal dari sungai yang tinggi.",
  ui_story_5084_50841400_208_dialog_content = "Kamu harus berdoa agar sebagian roh orang tuamu kembali ke sana.",
  ui_story_5084_50841400_209_dialog_content = "Aku harus berdoa untuk mereka...",
  ui_story_5084_50841400_210_dialog_content = "Terima kasih atas jawabannya, Lady Victoria. Saya akan merenungkannya lebih lanjut...",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>Victoria terharu melihat betapa kuatnya Order telah menjadi.</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>Itu adalah hasil dari Wilhelm masa lalu dan dirinya sekarang yang membersihkan rintangan bagi Victoria muda untuk maju.</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>Panduan yang mereka terima bisa berasal dari seseorang di masa lalu atau masa depan, yang berusaha sebaik mungkin untuk menyampaikan maksud mereka dalam aliran waktu dan ruang.</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>Victoria melihat banyak pelancong di Sungai Takdir, masing-masing mewakili keberanian untuk mencari Kebenaran.</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>Semua itu akan dilihat oleh seseorang tertentu yang mengambang dalam aliran waktu.</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>Arah arus akan berganti seperti yang tertulis dalam kitab, tetapi Victoria tidak memiliki keinginan untuk membalik halaman secepat itu.</color>",
  ui_story_5084_50841400_217_dialog_content = "Apakah itu berarti kau percaya pada pengasingan sebanyak aku?",
  ui_story_5084_50841400_218_dialog_content = "Meski aku bisa mengerti kenapa mereka tidak akan menghadiri perayaan apa pun, selalu begitu dengan orang-orang yang suka menyendiri.",
  ui_story_5084_50841400_219_dialog_content = "Apakah para pertapa memiliki organisasi mereka sendiri?",
  ui_story_5084_50841400_220_dialog_content = "Tidak tepatnya, tetapi dikatakan bahwa sekte itu didirikan oleh seorang murid pria misterius di Varaki Town sekitar tahun 1915.",
  ui_story_5084_50841400_221_dialog_content = "Apakah Lady Victoria tidak pernah memberitahumu?",
  ui_story_5084_50841400_222_dialog_content = "Dibandingkan dengan kehadiranmu di kota-kota Aurorian, aku hanya bertemu dengan segelintir orang yang mengaku sebagai pertapa di alam liar.",
  ui_story_5084_50841400_223_dialog_content = "Apa yang biasanya kamu lakukan?",
  ui_story_5084_50841400_224_dialog_content = "Cari ruang kosong atau jelajahi sudut tersembunyi.",
  ui_story_5084_50841400_225_dialog_content = "Lalu?",
  ui_story_5084_50841400_226_dialog_content = "Tetap di sana dan jangan melakukan apa pun.",
  ui_story_5084_50841400_227_dialog_content = "Sejauh ini, pengasingan yang disebut-sebut ini terdengar seperti tidak ingin belajar dari buku bagi saya...",
  ui_story_5084_50841400_228_dialog_content = "Itu mungkin karena tidak ada buku yang tidak dibaca oleh seorang master pertapa.",
  ui_story_5084_50841400_229_dialog_content = "Tapi, mengapa saya merasa bahwa, dalam kasusmu, kamu memiliki buku-buku itu tetapi memilih untuk tidak membacanya...",
  ui_story_5084_50841400_230_dialog_content = "Dia pasti sosok yang hebat! May Bolehkah saya menanyakan namanya?",
  ui_story_5084_50841400_231_dialog_content = "Tidak ada yang tahu namanya, tetapi saya telah melihatnya.",
  ui_story_5084_50841400_232_dialog_content = "Ramping, dengan semacam aura kebangsawanan tradisional...",
  ui_story_5084_50841400_233_dialog_content = "Karena dia sering memakai topi tinggi hitam, jubah hitam kemerahan, dan kuda hitam.",
  ui_story_5084_50841400_234_dialog_content = "…?",
  ui_story_5084_50841400_235_dialog_content = "Dia adalah orang yang sulit ditebak dan sering bepergian. Beberapa orang mengklaim dia berharap ada kesempatan untuk bertemu dengan seorang teman lama.",
  ui_story_5084_50841400_236_dialog_content = "Bisakah itu menjadi mentor saya?",
  ui_story_5084_50841400_237_dialog_content = "Siapa itu?",
  ui_story_5084_50841400_238_dialog_content = "Teman lama yang ingin dia temui...",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>\"Ketika semua hal telah berakhir, datang temui saya di sini,\" itulah yang dia katakan.</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>Victoria masih berada di jendela saat dia melihat langsung melalui waktu dan menjadi terpaku pada sosok-sosok yang mengejar Kebenaran.</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>Seperti bintang-bintang di langit malam, beberapa di antaranya terang, beberapa redup, tetapi setiap satu dari mereka menafsirkan Kebenaran dengan cara mereka sendiri.</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>Victoria mengerti bahwa mencari Truth itu seperti mengejar bintang yang jauh dan menuntut wawasan dari mata pikiran.</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>Tapi dia hanyalah pemandu yang membawa mereka maju.</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>Di luar jendela, dia menghela nafas. Dia telah melihat setiap anggota True Order sebagai anak kecilnya.</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>Dia tahu, tidak peduli seberapa berat jalan yang mereka tempuh, Victoria akan selalu memberikan cahaya di saat tergelap.</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>Tetapi hanya dia yang tahu wanita di samping jendela juga seorang pencari yang kesepian.</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>Victoria menutup matanya dan membiarkan hatinya bergema sepanjang malam.</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>Dia mengerti bahwa ada berbagai jalan menuju The Truth, baik itu kesendirian yang sepi atau Order yang ramai.</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>\"Pencarian Truth adalah perjalanan yang tidak pernah berakhir,\" gumamnya.</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>\"Dan aku akan mengawasi dan membimbingmu dalam perjalananmu.\"</color>"
}
return config
